-- kingres_timepart--0.3.sql
--   Install script of the kingres_timepart extension, version 0.3: everything of 0.2 and the changes of
--   kingres_timepart--0.2--0.3.sql appended (time partitioning policies on distributed tables).  Generated by
--   mk-install-script.sh from the 0.2 install script and the 0.2--0.3 upgrade script: change the upgrade
--   script and run the generator, never edit this file by hand.
--
\echo Use "CREATE EXTENSION kingres_timepart" to load this file. \quit

-- Conventions of this script
--
--   * The control file sets "schema = kingres" and "relocatable = false".
--     Every object is created in that schema and every reference to an
--     object of the extension is qualified.
--   * Every function carries "SET search_path = pg_catalog, kingres,
--     pg_temp", with two exceptions: the two procedures that commit between
--     their steps (timepart_run and timepart_run_phase).  A procedure with a
--     SET clause or with SECURITY DEFINER cannot COMMIT.  These two carry no
--     SET clause; instead their first statement, and the first statement
--     after each COMMIT, sets the search_path of the transaction to
--     "pg_catalog, pg_temp" with set_config(..., true); every function they
--     call is schema-qualified, and every operator is resolved under that
--     path.  The test timepart_security attacks them with a schema that
--     holds a look-alike of every function the bodies call.
--   * Dynamic SQL is built with format() and %I / %L only.  Names of
--     partitions are generated by timepart_part_name and always quoted.
--   * The caller's identity is current_user.  SECURITY DEFINER is used by the
--     event trigger functions, by the seal functions and triggers, and by the
--     four functions that write the history for a table owner who drives its
--     own maintenance (timepart__begin_run, timepart__finish_run,
--     timepart__step_begin, timepart__step_end); those judge the caller by
--     session_user and by the role that the SECURITY INVOKER function in front
--     of them says it runs as.  One more function is made, by
--     timepart__exec_as, in the temporary schema of a session for the length
--     of an action (see there).  The policy and history tables
--     (the "_data" tables) grant nothing to PUBLIC; a role reaches them
--     through security_barrier views that show the rows of the tables it owns
--     (judged by current_user), and a trigger pins the columns a role must
--     not choose; so set_policy and the
--     others are SECURITY INVOKER and PostgreSQL checks what the caller may
--     do, also when code of a low-privilege role runs in a session of a
--     superuser.
--   * Names that start with "timepart__" are internal helpers.

------------------------------------------------------------------------
-- Identity: what a row of the policy or the history refers to
------------------------------------------------------------------------

-- A row names a table by schema and name and a role by name, which a backup
-- carries, and keeps the OID of both, which a rename does not change but a
-- backup does not carry: another cluster has other role OIDs, another
-- database other table OIDs, and an OID can even be the one of another object
-- there.  The stamp tells which of the two a row can be trusted for.  It is
-- made when the extension is created, so it differs in every database that
-- was made by CREATE EXTENSION and is never copied by a dump (the function
-- is part of the extension, the rows are data).  But the stamp is also public
-- (anybody can read the function) and a row is data, so a stamp does not make
-- a policy trusted; the seal does (see timepart_policy_seal):
--
--   * a history row whose stamp is the stamp of this installation was written
--     here: its OIDs are the identity (a role renamed, a table renamed or
--     moved keep it; a role or a table that was dropped is gone for good, and
--     a new one of the same name is another one);
--   * a policy row is trusted only with a seal that matches it; the interface
--     makes the seal when it writes the row;
--   * any other row was restored from a backup: its OIDs mean nothing, and its
--     names are the identity until timepart_adopt() replaces them by the OIDs
--     of the roles and tables of that name and gives the row the stamp of this
--     installation (a policy row, only after the checks of that function and
--     only when a superuser calls it; a history row on every begin of a run).
--
-- The function is created by the DO block below because its body holds a
-- random value, and is not part of the pure helpers.
DO $stamp$
BEGIN
    EXECUTE pg_catalog.format(
        'CREATE FUNCTION kingres.timepart__stamp() RETURNS pg_catalog.uuid '
        'LANGUAGE sql STABLE SET search_path = pg_catalog, pg_temp AS %L',
        pg_catalog.format('SELECT %L::pg_catalog.uuid', pg_catalog.gen_random_uuid()));
END
$stamp$;

COMMENT ON FUNCTION kingres.timepart__stamp() IS
    'Identifies this installation of the extension: OIDs in rows with another stamp come from a backup';

CREATE TABLE kingres.timepart_policy_data (
    schema_name      name        NOT NULL,
    table_name       name        NOT NULL,
    parent_oid       oid         NOT NULL,
    partition_every  interval    NOT NULL,
    timezone         text        NOT NULL DEFAULT 'UTC',
    create_ahead     interval    NOT NULL DEFAULT '7 days',
    retention        interval,
    retention_action text        NOT NULL DEFAULT 'drop',
    columnar_after   interval,
    columnar_sort    text[],
    columnar_options jsonb,
    run_every        interval    NOT NULL DEFAULT '1 hour',
    enabled          boolean     NOT NULL DEFAULT true,
    next_run_at      timestamptz NOT NULL DEFAULT now(),
    table_owner      name        NOT NULL,
    created_by       name        NOT NULL,
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    -- see "Identity": the OIDs below are trusted only when stamp is this
    -- installation's; table_owner and created_by are the names as recorded
    stamp            uuid        NOT NULL DEFAULT kingres.timepart__stamp(),
    table_owner_oid  oid         NOT NULL,
    created_by_oid   oid,
    CONSTRAINT timepart_policy_pkey PRIMARY KEY (schema_name, table_name),
    CONSTRAINT timepart_policy_retention_action_check
        CHECK (retention_action IN ('drop', 'detach')),
    CONSTRAINT timepart_policy_columnar_retention_check
        CHECK (columnar_after IS NULL OR retention IS NULL
               OR columnar_after <= retention)
);

CREATE TABLE kingres.timepart_run_data (
    run_id      bigint GENERATED ALWAYS AS IDENTITY,
    schema_name name        NOT NULL,
    table_name  name        NOT NULL,
    as_of       timestamptz NOT NULL,
    trigger     text        NOT NULL,
    state       text        NOT NULL,
    started_at  timestamptz NOT NULL DEFAULT now(),
    finished_at timestamptz,
    started_by  name        NOT NULL,
    error       text,
    backend_pid   integer,
    backend_start timestamptz,
    -- The table and its owner as the run began (see "Identity"): table_oid is
    -- null once the table is gone; table_owner is the name as recorded.
    stamp           uuid     NOT NULL DEFAULT kingres.timepart__stamp(),
    table_oid       oid,
    table_owner_oid oid      NOT NULL,
    table_owner     name     NOT NULL,
    started_by_oid  oid,
    CONSTRAINT timepart_run_pkey PRIMARY KEY (run_id),
    CONSTRAINT timepart_run_trigger_check
        CHECK (trigger IN ('schedule', 'manual', 'sql')),
    CONSTRAINT timepart_run_state_check
        CHECK (state IN ('running', 'done', 'partial', 'failed'))
);

CREATE INDEX timepart_run_table_idx
    ON kingres.timepart_run_data (schema_name, table_name, run_id DESC);
CREATE INDEX timepart_run_table_oid_idx
    ON kingres.timepart_run_data (table_oid) WHERE table_oid IS NOT NULL;

CREATE TABLE kingres.timepart_run_action_data (
    run_id           bigint      NOT NULL,
    seq              integer     NOT NULL,
    kind             text        NOT NULL,
    partition_schema name        NOT NULL,
    partition_name   name        NOT NULL,
    range_from       timestamptz,
    range_to         timestamptz,
    state            text        NOT NULL,
    detail           text,
    bytes_before     bigint,
    bytes_after      bigint,
    started_at       timestamptz NOT NULL DEFAULT now(),
    finished_at      timestamptz,
    CONSTRAINT timepart_run_action_pkey PRIMARY KEY (run_id, seq),
    CONSTRAINT timepart_run_action_run_id_fkey FOREIGN KEY (run_id)
        REFERENCES kingres.timepart_run_data (run_id) ON DELETE CASCADE,
    CONSTRAINT timepart_run_action_kind_check
        CHECK (kind IN ('create', 'convert', 'drop', 'detach', 'misaligned')),
    CONSTRAINT timepart_run_action_state_check
        CHECK (state IN ('running', 'done', 'failed', 'skipped'))
);

-- One row per table, locked (FOR UPDATE NOWAIT) by begin_run and by every step
-- of a run.  Only the extension owner can touch it, so no other role can
-- hold a lock that stops the runs of a table.  Not dumped: the rows are made
-- when they are needed.
CREATE TABLE kingres.timepart_lock (
    schema_name name NOT NULL,
    table_name  name NOT NULL,
    CONSTRAINT timepart_lock_pkey PRIMARY KEY (schema_name, table_name)
);

-- The seal of a policy: one row per policy that was written here by the
-- interface (timepart_set_policy, a write through the view timepart_policy,
-- both after the checks of the owner) or adopted here (timepart_adopt, after
-- the checks of the catalog), with a fingerprint of what the policy says.  A
-- policy row without a seal that matches it is not trusted by anything: the
-- maintenance does not act on it, whatever its stamp and OIDs say, because
-- those are data and a dump can carry any data.  The table is not registered
-- with pg_extension_config_dump, so a dump does not carry it and a restore
-- starts without seals; the rows of this table are written only by the
-- trigger timepart_policy_seal and by nothing a role can call.
CREATE TABLE kingres.timepart_policy_seal (
    schema_name name NOT NULL,
    table_name  name NOT NULL,
    fingerprint text NOT NULL,
    CONSTRAINT timepart_policy_seal_pkey PRIMARY KEY (schema_name, table_name)
);

REVOKE ALL ON kingres.timepart_policy_data, kingres.timepart_run_data,
    kingres.timepart_run_action_data, kingres.timepart_lock,
    kingres.timepart_policy_seal FROM PUBLIC;

-- A logical backup carries the policies and the history; the sequence behind
-- run_id is carried too, so a restored database does not reuse run numbers.
SELECT pg_catalog.pg_extension_config_dump('kingres.timepart_policy_data', '');
SELECT pg_catalog.pg_extension_config_dump('kingres.timepart_run_data', '');
SELECT pg_catalog.pg_extension_config_dump('kingres.timepart_run_action_data', '');
SELECT pg_catalog.pg_extension_config_dump(
    pg_catalog.pg_get_serial_sequence('kingres.timepart_run_data', 'run_id'), '');

------------------------------------------------------------------------
-- Pure helpers: intervals, the grid, names and literals
------------------------------------------------------------------------

-- Split an interval into the unit and the count the grid understands (10.3):
-- N hours with 24 mod N = 0; N days (7 days is the week, aligned on Monday);
-- N months with 12 mod N = 0; N years.  Anything else, a mixture of units, a
-- zero or a negative value is refused.
CREATE FUNCTION kingres.timepart_interval_parts(p_every interval,
                                                OUT unit text, OUT n integer)
LANGUAGE plpgsql IMMUTABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_m numeric;
    v_d numeric;
    v_t numeric;
BEGIN
    IF p_every IS NULL THEN
        RAISE EXCEPTION 'partition_every must not be null'
            USING ERRCODE = '22004';
    END IF;
    v_m := extract(year FROM p_every) * 12 + extract(month FROM p_every);
    v_d := extract(day FROM p_every);
    v_t := extract(hour FROM p_every) * 3600
         + extract(minute FROM p_every) * 60
         + extract(second FROM p_every);
    IF v_m < 0 OR v_d < 0 OR v_t < 0
       OR (v_m > 0)::int + (v_d > 0)::int + (v_t > 0)::int <> 1 THEN
        RAISE EXCEPTION 'invalid partition_every "%"', p_every
            USING ERRCODE = '22023',
                  HINT = 'Use N hours (24 mod N = 0), N days, 1 week, N months (12 mod N = 0) or N years, in one unit.';
    END IF;
    IF v_t > 0 THEN
        IF v_t % 3600 <> 0 OR 24 % (v_t / 3600) <> 0 THEN
            RAISE EXCEPTION 'invalid partition_every "%"', p_every
                USING ERRCODE = '22023',
                      HINT = 'Hours must divide a day: 1, 2, 3, 4, 6, 8, 12 or 24.';
        END IF;
        unit := 'hour';
        n := (v_t / 3600)::int;
    ELSIF v_d > 0 THEN
        IF v_d > 3660 THEN
            RAISE EXCEPTION 'invalid partition_every "%"', p_every
                USING ERRCODE = '22023', HINT = 'At most 3660 days.';
        END IF;
        IF v_d = 7 THEN
            unit := 'week';
            n := 1;
        ELSE
            unit := 'day';
            n := v_d::int;
        END IF;
    ELSIF v_m % 12 = 0 THEN
        IF v_m / 12 > 1000 THEN
            RAISE EXCEPTION 'invalid partition_every "%"', p_every
                USING ERRCODE = '22023', HINT = 'At most 1000 years.';
        END IF;
        unit := 'year';
        n := (v_m / 12)::int;
    ELSIF 12 % v_m = 0 THEN
        unit := 'month';
        n := v_m::int;
    ELSE
        RAISE EXCEPTION 'invalid partition_every "%"', p_every
            USING ERRCODE = '22023',
                  HINT = 'Months must divide a year: 1, 2, 3, 4, 6 or 12.';
    END IF;
END;
$$;

-- The time zone must be a name from pg_timezone_names: an offset or an
-- abbreviation has no daylight-saving rules and would make the bounds depend
-- on a setting nobody can see.
CREATE FUNCTION kingres.timepart__check_tz(p_tz text)
RETURNS void
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    IF p_tz IS NULL OR NOT EXISTS (SELECT 1 FROM pg_timezone_names n
                                   WHERE n.name = p_tz) THEN
        RAISE EXCEPTION 'unknown time zone "%"', p_tz
            USING ERRCODE = '22023',
                  HINT = 'Use a name from pg_timezone_names, for example UTC or Europe/Berlin.';
    END IF;
END;
$$;

-- The start of the cell number k of the grid.  Hours are absolute lengths
-- counted from 2000-01-01 00:00 of the zone, so a daylight-saving change
-- never makes a cell shorter or longer than N hours.  Days, weeks, months
-- and years follow the calendar of the zone: the cell starts at local
-- midnight, so a day of a change is 23 or 25 hours long.  Weeks start on
-- Monday; N days count from 2000-01-01.  Every cell ends where the next one
-- starts, because both come from this one function.
CREATE FUNCTION kingres.timepart_cell_start(p_every interval, p_tz text,
                                            p_k bigint)
RETURNS timestamptz
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_unit text;
    v_n    integer;
BEGIN
    SELECT u.unit, u.n INTO v_unit, v_n
      FROM kingres.timepart_interval_parts(p_every) u;
    IF v_unit = 'hour' THEN
        RETURN (timestamp '2000-01-01 00:00:00' AT TIME ZONE p_tz)
               + (p_k * v_n)::float8 * interval '1 hour';
    ELSIF v_unit = 'day' THEN
        RETURN ((date '2000-01-01' + (p_k * v_n)::int)::timestamp)
               AT TIME ZONE p_tz;
    ELSIF v_unit = 'week' THEN
        RETURN ((date '2000-01-03' + (p_k * 7)::int)::timestamp)
               AT TIME ZONE p_tz;
    ELSIF v_unit = 'month' THEN
        RETURN (timestamp '2000-01-01'
                + (p_k * v_n)::float8 * interval '1 month')
               AT TIME ZONE p_tz;
    ELSE
        RETURN (timestamp '2000-01-01'
                + (p_k * v_n)::float8 * interval '1 year')
               AT TIME ZONE p_tz;
    END IF;
END;
$$;

-- The number of the cell that contains the instant p_t.
CREATE FUNCTION kingres.timepart_cell_of(p_every interval, p_tz text,
                                         p_t timestamptz)
RETURNS bigint
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_unit  text;
    v_n     integer;
    v_local timestamp;
    v_k     bigint;
    v_mi    integer;
BEGIN
    IF p_t IS NULL OR p_t IN ('infinity', '-infinity') THEN
        RAISE EXCEPTION 'time value must be finite'
            USING ERRCODE = '22008';
    END IF;
    SELECT u.unit, u.n INTO v_unit, v_n
      FROM kingres.timepart_interval_parts(p_every) u;
    v_local := p_t AT TIME ZONE p_tz;
    IF v_unit = 'hour' THEN
        v_k := floor((extract(epoch FROM p_t)
                      - extract(epoch FROM (timestamp '2000-01-01 00:00:00'
                                            AT TIME ZONE p_tz)))
                     / (v_n * 3600))::bigint;
    ELSIF v_unit = 'day' THEN
        v_k := floor(((v_local::date - date '2000-01-01')::numeric) / v_n)::bigint;
    ELSIF v_unit = 'week' THEN
        v_k := floor(((v_local::date - date '2000-01-03')::numeric) / 7)::bigint;
    ELSIF v_unit = 'month' THEN
        v_mi := (extract(year FROM v_local)::int - 2000) * 12
                + extract(month FROM v_local)::int - 1;
        v_k := floor(v_mi::numeric / v_n)::bigint;
    ELSE
        v_k := floor((extract(year FROM v_local)::int - 2000)::numeric / v_n)::bigint;
    END IF;
    -- A zone whose local midnight does not exist on a day of change can put
    -- the start of a cell a little after the local date says; settle it.
    WHILE kingres.timepart_cell_start(p_every, p_tz, v_k) > p_t LOOP
        v_k := v_k - 1;
    END LOOP;
    WHILE kingres.timepart_cell_start(p_every, p_tz, v_k + 1) <= p_t LOOP
        v_k := v_k + 1;
    END LOOP;
    RETURN v_k;
END;
$$;

-- Is p_t the start of a cell?
CREATE FUNCTION kingres.timepart__on_grid(p_every interval, p_tz text,
                                          p_t timestamptz)
RETURNS boolean
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    IF p_t IN ('infinity', '-infinity') THEN
        RETURN false;
    END IF;
    RETURN kingres.timepart_cell_start(
               p_every, p_tz,
               kingres.timepart_cell_of(p_every, p_tz, p_t)) = p_t;
END;
$$;

-- Local calendar arithmetic: p_t plus (p_sign = 1) or minus (p_sign = -1) an
-- interval, counted in the wall clock of the zone.
CREATE FUNCTION kingres.timepart__add(p_t timestamptz, p_i interval,
                                      p_tz text, p_sign integer)
RETURNS timestamptz
LANGUAGE sql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
    SELECT ((p_t AT TIME ZONE p_tz) + p_i * p_sign) AT TIME ZONE p_tz
$$;

-- The instant that stands for p_t on the grid of a key.  A timestamptz key
-- is an instant and is used as it is.  A timestamp or date key holds wall
-- clock values: p_t is read in the policy's zone and the wall clock value is
-- then treated as a UTC instant, so the grid has no daylight-saving change.
CREATE FUNCTION kingres.timepart__eff(p_t timestamptz, p_keytype text,
                                      p_tz text)
RETURNS timestamptz
LANGUAGE sql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
    SELECT CASE WHEN p_keytype = 'timestamptz' THEN p_t
                ELSE (p_t AT TIME ZONE p_tz) AT TIME ZONE 'UTC' END
$$;

-- The text of a partition bound for the key type: an ISO literal that does
-- not depend on DateStyle or TimeZone.
CREATE FUNCTION kingres.timepart__bound_literal(p_keytype text,
                                                p_b timestamptz)
RETURNS text
LANGUAGE sql IMMUTABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
    SELECT CASE p_keytype
        WHEN 'timestamptz' THEN
            to_char(p_b AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
        WHEN 'timestamp' THEN
            to_char(p_b AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US')
        ELSE
            to_char(p_b AT TIME ZONE 'UTC', 'YYYY-MM-DD')
    END
$$;

-- The generated name of a partition: <table>_p<suffix> with the suffix
-- YYYYMMDDHH24 (hours, in UTC), YYYYMMDD (days and weeks, the first day, in
-- the zone), YYYYMM (months) or YYYY (years).  The table's name is cut,
-- character by character, until the whole name fits in 63 bytes.
CREATE FUNCTION kingres.timepart_part_name(p_base name, p_every interval,
                                           p_tz text, p_start timestamptz)
RETURNS name
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_unit   text;
    v_n      integer;
    v_tail   text;
    v_base   text := p_base::text;
BEGIN
    SELECT u.unit, u.n INTO v_unit, v_n
      FROM kingres.timepart_interval_parts(p_every) u;
    v_tail := '_p' || CASE v_unit
        WHEN 'hour'  THEN to_char(p_start AT TIME ZONE 'UTC', 'YYYYMMDDHH24')
        WHEN 'day'   THEN to_char(p_start AT TIME ZONE p_tz, 'YYYYMMDD')
        WHEN 'week'  THEN to_char(p_start AT TIME ZONE p_tz, 'YYYYMMDD')
        WHEN 'month' THEN to_char(p_start AT TIME ZONE p_tz, 'YYYYMM')
        ELSE              to_char(p_start AT TIME ZONE p_tz, 'YYYY')
    END;
    WHILE octet_length(v_base) + octet_length(v_tail) > 63 LOOP
        v_base := left(v_base, char_length(v_base) - 1);
    END LOOP;
    RETURN (v_base || v_tail)::name;
END;
$$;

-- An integer setting of the extension with a default and a range.  The
-- values are plain integers so that a test or an operator can bound every
-- wait; a value out of range is an error, not a silent clamp.
CREATE FUNCTION kingres.timepart__setting_int(p_name text, p_default integer,
                                              p_min integer, p_max integer)
RETURNS integer
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_text text := nullif(pg_catalog.current_setting(p_name, true), '');
    v_val  integer;
BEGIN
    IF v_text IS NULL THEN
        RETURN p_default;
    END IF;
    BEGIN
        v_val := v_text::integer;
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RAISE EXCEPTION 'invalid value "%" for "%"', v_text, p_name
            USING ERRCODE = '22023', HINT = 'The value is an integer.';
    END;
    IF v_val < p_min OR v_val > p_max THEN
        RAISE EXCEPTION 'value % of "%" is out of range', v_val, p_name
            USING ERRCODE = '22023',
                  HINT = format('The range is %s to %s.', p_min, p_max);
    END IF;
    RETURN v_val;
END;
$$;

-- The lock_timeout, as the text of a setting, from the settings
-- kingres_timepart.create_lock_timeout_ms (default 5000) or
-- kingres_timepart.retire_lock_timeout_ms (default 2000).  The caller applies
-- it with set_config('lock_timeout', ..., true) itself: a function that has a
-- SET clause gives back every setting it changed when it returns, so the
-- setting has to be made by a function that runs the statements.  The callers
-- have a SET clause too, so lock_timeout is back to what it was when they
-- return.
CREATE FUNCTION kingres.timepart__lock_timeout(p_what text)
RETURNS text
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    IF p_what = 'create' THEN
        RETURN kingres.timepart__setting_int(
                   'kingres_timepart.create_lock_timeout_ms', 5000, 1, 60000)::text || 'ms';
    END IF;
    RETURN kingres.timepart__setting_int(
               'kingres_timepart.retire_lock_timeout_ms', 2000, 1, 60000)::text || 'ms';
END;
$$;

------------------------------------------------------------------------
-- Who is calling
------------------------------------------------------------------------

-- The OID of the relation of that name, by a catalog lookup that, unlike
-- to_regclass, does not check the caller's right on the schema: the names come
-- from the policy and history tables, which name tables of other roles.
CREATE FUNCTION kingres.timepart__oid(p_schema name, p_table name)
RETURNS oid
LANGUAGE sql STABLE
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname = p_schema AND c.relname = p_table
$$;

-- The check PostgreSQL makes for ALTER TABLE: the role has the privileges of
-- the owner (it is the owner, a member that inherits, or a superuser).
CREATE FUNCTION kingres.timepart__require_owner(p_who name, p_owner oid,
                                                p_table text)
RETURNS void
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    IF NOT pg_has_role(p_who, p_owner, 'USAGE') THEN
        RAISE EXCEPTION 'must be owner of table %', p_table
            USING ERRCODE = '42501';
    END IF;
END;
$$;

CREATE FUNCTION kingres.timepart__require_superuser()
RETURNS void
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles r
                   WHERE r.rolname = current_user AND r.rolsuper) THEN
        RAISE EXCEPTION 'permission denied: only a superuser may call this function'
            USING ERRCODE = '42501';
    END IF;
END;
$$;

-- Who is driving a run.  The functions that a table owner can drive for its own
-- tables (begin, finish, the steps of an action) are SECURITY DEFINER, so the
-- extension owner's rights write the history; inside them current_user is the
-- definer, and the caller is judged twice: by session_user, which no SQL changes
-- without superuser rights, and by the role that the invoking function says it
-- runs as (current_user there), so that a role switched to with SET ROLE in a
-- superuser session is judged as the role it set.  Both must be a superuser or
-- the owner of the table itself.
CREATE FUNCTION kingres.timepart__require_driver(p_owner oid, p_caller_oid oid,
                                                 p_caller_super boolean)
RETURNS void
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles r
                WHERE r.rolname = session_user
                  AND (r.rolsuper OR r.oid = p_owner))
       AND (coalesce(p_caller_super, false) OR p_caller_oid = p_owner) THEN
        RETURN;
    END IF;
    RAISE EXCEPTION 'permission denied: only a superuser or the owner of the table may drive its maintenance'
        USING ERRCODE = '42501';
END;
$$;

-- The acknowledgement that the code of table owners may run in this session:
-- the setting kingres_timepart.trust_table_owners (see timepart__exec_as).
CREATE FUNCTION kingres.timepart__trust_owners()
RETURNS boolean
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    RETURN coalesce(pg_catalog.current_setting('kingres_timepart.trust_table_owners', true)::boolean,
                    false);
EXCEPTION WHEN invalid_text_representation THEN
    RETURN false;
END;
$$;

-- The role that a recorded role is, now: by OID for a row written here, by name
-- for a row from a backup (see "Identity"); null when there is none (the role
-- was dropped, or the backup names a role this cluster does not have).
CREATE FUNCTION kingres.timepart__role_oid(p_stamp uuid, p_oid oid, p_name name)
RETURNS oid
LANGUAGE sql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
    SELECT CASE WHEN p_stamp = kingres.timepart__stamp()
                THEN (SELECT r.oid FROM pg_roles r WHERE r.oid = p_oid)
                ELSE (SELECT r.oid FROM pg_roles r WHERE r.rolname = p_name)
           END
$$;

-- The name of a recorded role, from the catalog (a renamed role shows its new
-- name); the name as recorded when the role is gone.
CREATE FUNCTION kingres.timepart__role_name(p_stamp uuid, p_oid oid, p_name name)
RETURNS name
LANGUAGE sql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
    SELECT coalesce((SELECT r.rolname FROM pg_roles r
                      WHERE r.oid = kingres.timepart__role_oid(p_stamp, p_oid, p_name)),
                    p_name)
$$;

-- The table a run was made for, if it still exists: by OID for a run recorded
-- here (null once the table is dropped, also when the name is used again), by
-- schema, name and owner for a run restored from a backup.
CREATE FUNCTION kingres.timepart__run_table(
    p_stamp uuid, p_table_oid oid, p_schema name, p_table name,
    p_owner_oid oid, p_owner name)
RETURNS oid
LANGUAGE sql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
    SELECT CASE WHEN p_stamp = kingres.timepart__stamp()
                THEN (SELECT c.oid FROM pg_class c
                       WHERE c.oid = p_table_oid AND c.relkind = 'p')
                ELSE (SELECT c.oid FROM pg_class c
                        JOIN pg_namespace n ON n.oid = c.relnamespace
                       WHERE n.nspname = p_schema AND c.relname = p_table
                         AND c.relkind = 'p'
                         AND c.relowner = kingres.timepart__role_oid(p_stamp, p_owner_oid, p_owner))
           END
$$;

-- What the history views show to the calling role: the runs of tables that it
-- owned (has the privileges of the owner of) when the run began, whether the
-- table is still there, was renamed, was dropped, or was dropped and made
-- again by another role; a superuser sees every run.  The role judged is the
-- one recorded in the run, so an owner that was dropped leaves runs that only
-- a superuser sees.  Judges current_user, as the other views do.
CREATE FUNCTION kingres.timepart__run_visible(p_stamp uuid, p_owner_oid oid,
                                              p_owner name)
RETURNS boolean
LANGUAGE sql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
    SELECT coalesce((SELECT r.rolsuper FROM pg_roles r
                      WHERE r.rolname = current_user), false)
           OR coalesce(pg_has_role(
                  current_user,
                  kingres.timepart__role_oid(p_stamp, p_owner_oid, p_owner),
                  'USAGE'), false)
$$;

------------------------------------------------------------------------
-- The seal of a policy (see the table timepart_policy_seal)
------------------------------------------------------------------------

-- What a policy says, as one string: the fields that decide what the
-- maintenance does to the table, and the owner it was set for.  Not the names
-- (they are the key of the seal and a rename moves both), not the OID hint,
-- the schedule or the time stamps, which the extension itself changes later.
-- The settings of the function fix the text of intervals and dates.
CREATE FUNCTION kingres.timepart__policy_fp(p kingres.timepart_policy_data)
RETURNS text
LANGUAGE sql STABLE
SET search_path = pg_catalog, pg_temp
SET intervalstyle = 'iso_8601'
SET datestyle = 'ISO, MDY'
AS $$
    SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        pg_catalog.format('%L|%L|%L|%L|%L|%L|%L|%L|%L|%L|%L|%L',
            p.partition_every, p.timezone, p.create_ahead, p.retention,
            p.retention_action, p.columnar_after, p.columnar_sort,
            p.columnar_options, p.run_every, p.enabled, p.table_owner_oid,
            p.table_owner), 'UTF8')), 'hex')
$$;

-- Is the policy of the table one that was written or adopted here and has not
-- been changed since?  SECURITY DEFINER because the seals are not readable by
-- roles; it answers for the one policy that is named.
CREATE FUNCTION kingres.timepart__is_sealed(p_schema name, p_table name)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, kingres, pg_temp
AS $$
    SELECT EXISTS (
        SELECT 1
          FROM kingres.timepart_policy_data p
          JOIN kingres.timepart_policy_seal s
            ON s.schema_name = p.schema_name AND s.table_name = p.table_name
         WHERE p.schema_name = p_schema AND p.table_name = p_table
           AND s.fingerprint = kingres.timepart__policy_fp(p))
$$;

-- The stamp that a policy row is to be trusted with: its own when it is
-- sealed and made here, else the nil stamp, which no installation has, so
-- that its OIDs mean nothing and its names are the identity.
CREATE FUNCTION kingres.timepart__policy_stamp(p_schema name, p_table name,
                                               p_stamp uuid)
RETURNS uuid
LANGUAGE sql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
    SELECT CASE WHEN p_stamp = kingres.timepart__stamp()
                     AND kingres.timepart__is_sealed(p_schema, p_table)
                THEN p_stamp
                ELSE '00000000-0000-0000-0000-000000000000'::pg_catalog.uuid END
$$;

-- A write that the checks of the extension have passed asks for its seal: the
-- key goes into a setting of the transaction, which the trigger that runs
-- after the write reads.  A role can set the setting too, and gains nothing:
-- it can write a policy row only through the view, which the trigger has
-- checked, and only for tables it owns.
CREATE FUNCTION kingres.timepart__mark_seal(p_schema name, p_table name)
RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    PERFORM pg_catalog.set_config(
        'kingres_timepart.sealing',
        coalesce(pg_catalog.current_setting('kingres_timepart.sealing', true), '')
        || pg_catalog.md5(p_schema::text || E'\x01' || p_table::text) || ',',
        true);
END;
$$;

CREATE FUNCTION kingres.timepart__policy_seal_trg()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_marks text := coalesce(pg_catalog.current_setting('kingres_timepart.sealing', true), '');
BEGIN
    IF TG_OP = 'DELETE' THEN
        DELETE FROM kingres.timepart_policy_seal s
         WHERE s.schema_name = OLD.schema_name AND s.table_name = OLD.table_name;
        RETURN NULL;
    END IF;
    IF TG_OP = 'UPDATE'
       AND (OLD.schema_name, OLD.table_name) IS DISTINCT FROM (NEW.schema_name, NEW.table_name) THEN
        -- a policy that moved with its table (a rename) takes its seal along,
        -- if it was sealed and says the same
        DELETE FROM kingres.timepart_policy_seal s
         WHERE s.schema_name = NEW.schema_name AND s.table_name = NEW.table_name;
        UPDATE kingres.timepart_policy_seal s
           SET schema_name = NEW.schema_name, table_name = NEW.table_name
         WHERE s.schema_name = OLD.schema_name AND s.table_name = OLD.table_name
           AND s.fingerprint = kingres.timepart__policy_fp(OLD)
           AND s.fingerprint = kingres.timepart__policy_fp(NEW);
        DELETE FROM kingres.timepart_policy_seal s
         WHERE s.schema_name = OLD.schema_name AND s.table_name = OLD.table_name;
    END IF;
    IF pg_catalog.strpos(v_marks, pg_catalog.md5(NEW.schema_name::text || E'\x01'
                                                 || NEW.table_name::text) || ',') > 0 THEN
        INSERT INTO kingres.timepart_policy_seal (schema_name, table_name, fingerprint)
        VALUES (NEW.schema_name, NEW.table_name, kingres.timepart__policy_fp(NEW))
        ON CONFLICT (schema_name, table_name)
            DO UPDATE SET fingerprint = EXCLUDED.fingerprint;
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION kingres.timepart__policy_seal_truncate()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    DELETE FROM kingres.timepart_policy_seal;
    RETURN NULL;
END;
$$;

CREATE TRIGGER timepart_policy_seal
    AFTER INSERT OR UPDATE OR DELETE ON kingres.timepart_policy_data
    FOR EACH ROW EXECUTE FUNCTION kingres.timepart__policy_seal_trg();
CREATE TRIGGER timepart_policy_seal_truncate
    AFTER TRUNCATE ON kingres.timepart_policy_data
    FOR EACH STATEMENT EXECUTE FUNCTION kingres.timepart__policy_seal_truncate();

------------------------------------------------------------------------
-- What a table must be, and what it holds now
------------------------------------------------------------------------

-- Check a table against 10.2 and return what the other functions need.
-- Reads the system catalogs only.
CREATE FUNCTION kingres.timepart__key_info(
    p_rel oid,
    OUT r_schema name, OUT r_table name, OUT r_owner_oid oid,
    OUT r_owner name, OUT r_keycol name, OUT r_keytype text,
    OUT r_persistence "char", OUT r_am oid, OUT r_default name)
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_c    record;
    v_pt   record;
    v_att  record;
    v_name text;
BEGIN
    SELECT c.relkind, c.relpersistence, c.relowner, c.relam, n.nspname,
           c.relname, pg_get_userbyid(c.relowner) AS ownername
      INTO v_c
      FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE c.oid = p_rel;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'relation with OID % does not exist', p_rel
            USING ERRCODE = '42P01';
    END IF;
    v_name := format('%I.%I', v_c.nspname, v_c.relname);
    IF v_c.relkind <> 'p' THEN
        RAISE EXCEPTION '% is not a partitioned table', v_name
            USING ERRCODE = '42809';
    END IF;
    IF v_c.relpersistence = 't' THEN
        RAISE EXCEPTION 'temporary table "%" is not supported', v_c.relname
            USING ERRCODE = '0A000';
    END IF;
    SELECT pt.partstrat, pt.partnatts, pt.partattrs[0] AS attnum
      INTO v_pt FROM pg_partitioned_table pt WHERE pt.partrelid = p_rel;
    IF v_pt.partstrat <> 'r' THEN
        RAISE EXCEPTION '% is not partitioned by RANGE', v_name
            USING ERRCODE = '0A000';
    END IF;
    IF v_pt.partnatts <> 1 OR v_pt.attnum = 0 THEN
        RAISE EXCEPTION '% must be partitioned by exactly one column, which is not an expression', v_name
            USING ERRCODE = '0A000';
    END IF;
    SELECT a.attname, a.atttypid INTO v_att
      FROM pg_attribute a
     WHERE a.attrelid = p_rel AND a.attnum = v_pt.attnum;
    r_keytype := CASE v_att.atttypid
        WHEN 'pg_catalog.timestamptz'::regtype THEN 'timestamptz'
        WHEN 'pg_catalog.timestamp'::regtype THEN 'timestamp'
        WHEN 'pg_catalog.date'::regtype THEN 'date'
    END;
    IF r_keytype IS NULL THEN
        RAISE EXCEPTION 'partition column "%" of % must be of type date, timestamp or timestamptz',
            v_att.attname, v_name USING ERRCODE = '0A000';
    END IF;
    r_schema := v_c.nspname;
    r_table := v_c.relname;
    r_owner_oid := v_c.relowner;
    r_owner := v_c.ownername;
    r_keycol := v_att.attname;
    r_persistence := v_c.relpersistence;
    r_am := v_c.relam;
    SELECT c2.relname INTO r_default
      FROM pg_inherits i JOIN pg_class c2 ON c2.oid = i.inhrelid
     WHERE i.inhparent = p_rel AND pg_get_expr(c2.relpartbound, c2.oid) = 'DEFAULT';
END;
$$;

-- The partitions of a table with their bounds as instants of the grid (see
-- timepart__eff).  MINVALUE and MAXVALUE become -infinity and infinity; a
-- DEFAULT partition has null bounds.  Sorted by lower bound, default last.
CREATE FUNCTION kingres.timepart__children(p_parent oid)
RETURNS TABLE (part_oid oid, part_schema name, part_name name,
               lo timestamptz, hi timestamptz, is_default boolean,
               am_name name)
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
SET DateStyle = 'ISO, MDY'
AS $$
DECLARE
    v_keytype text;
    r         record;
    v_m       text[];
    v_lo      timestamptz;
    v_hi      timestamptz;
BEGIN
    SELECT k.r_keytype INTO v_keytype FROM kingres.timepart__key_info(p_parent) k;
    FOR r IN
        SELECT c.oid AS o, n.nspname AS s, c.relname AS nm,
               pg_get_expr(c.relpartbound, c.oid) AS b, a.amname AS am
          FROM pg_inherits i
          JOIN pg_class c ON c.oid = i.inhrelid
          JOIN pg_namespace n ON n.oid = c.relnamespace
          LEFT JOIN pg_am a ON a.oid = c.relam
         WHERE i.inhparent = p_parent
    LOOP
        part_oid := r.o;
        part_schema := r.s;
        part_name := r.nm;
        am_name := r.am;
        IF r.b = 'DEFAULT' THEN
            lo := NULL;
            hi := NULL;
            is_default := true;
            RETURN NEXT;
            CONTINUE;
        END IF;
        v_m := regexp_match(r.b, '^FOR VALUES FROM \((.*)\) TO \((.*)\)$');
        IF v_m IS NULL THEN
            RAISE EXCEPTION 'cannot read the bound of partition %.%: %',
                r.s, r.nm, r.b USING ERRCODE = '0A000';
        END IF;
        FOR i IN 1..2 LOOP
            DECLARE
                v_lit text := (regexp_match(v_m[i], '^''([^'']*)'''))[1];
                v_val timestamptz;
            BEGIN
                IF v_lit IS NULL THEN
                    v_val := CASE WHEN v_m[i] LIKE 'MINVALUE%' THEN '-infinity'
                                  ELSE 'infinity' END;
                ELSIF v_keytype = 'timestamptz' THEN
                    v_val := v_lit::timestamptz;
                ELSIF v_keytype = 'timestamp' THEN
                    v_val := v_lit::timestamp AT TIME ZONE 'UTC';
                ELSE
                    v_val := v_lit::date::timestamp AT TIME ZONE 'UTC';
                END IF;
                IF i = 1 THEN v_lo := v_val; ELSE v_hi := v_val; END IF;
            END;
        END LOOP;
        lo := v_lo;
        hi := v_hi;
        is_default := false;
        RETURN NEXT;
    END LOOP;
END;
$$;

-- The cells from k_from to k_to that no partition touches, as partitions to
-- create.  Every cell ends where the next starts, so the partitions created
-- never overlap each other; a cell that overlaps an existing partition (one
-- of the same bounds, a wider one, or one with other bounds made by hand) is
-- left out.  At most 10000 cells in one call.
CREATE FUNCTION kingres.timepart__create_rows(p_parent oid, p_every interval,
                                              p_tz text, p_k_from bigint,
                                              p_k_to bigint)
RETURNS TABLE (part_schema name, part_name name,
               lo timestamptz, hi timestamptz)
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_info record;
    v_los  timestamptz[];
    v_his  timestamptz[];
    v_cnt  integer;
    j      integer := 1;
    k      bigint;
    v_s    timestamptz;
    v_e    timestamptz;
BEGIN
    IF p_k_to - p_k_from + 1 > 10000 THEN
        RAISE EXCEPTION 'too many partitions in one call: % cells',
            p_k_to - p_k_from + 1
            USING ERRCODE = '54000',
                  HINT = 'Create at most 10000 partitions per call; use a wider partition_every or a shorter range.';
    END IF;
    SELECT * INTO v_info FROM kingres.timepart__key_info(p_parent);
    SELECT coalesce(array_agg(c.lo ORDER BY c.lo), '{}'),
           coalesce(array_agg(c.hi ORDER BY c.lo), '{}')
      INTO v_los, v_his
      FROM kingres.timepart__children(p_parent) c
     WHERE NOT c.is_default;
    v_cnt := coalesce(cardinality(v_los), 0);
    v_s := kingres.timepart_cell_start(p_every, p_tz, p_k_from);
    FOR k IN p_k_from..p_k_to LOOP
        v_e := kingres.timepart_cell_start(p_every, p_tz, k + 1);
        -- Existing partitions do not overlap each other, so they are sorted
        -- by upper bound too; the first one whose upper bound is after the
        -- start of the cell is the only one that can touch it.
        WHILE j <= v_cnt AND v_his[j] <= v_s LOOP
            j := j + 1;
        END LOOP;
        -- A zone that skipped a whole local day gives a cell that starts and
        -- ends at one instant: there is nothing to create for it.
        IF v_e > v_s AND NOT (j <= v_cnt AND v_los[j] < v_e) THEN
            part_schema := v_info.r_schema;
            part_name := kingres.timepart_part_name(v_info.r_table, p_every,
                                                    p_tz, v_s);
            lo := v_s;
            hi := v_e;
            RETURN NEXT;
        END IF;
        v_s := v_e;
    END LOOP;
END;
$$;

------------------------------------------------------------------------
-- The plan: what a run would do at a given time
------------------------------------------------------------------------

-- The partitions whose bounds are not on the grid (an unbounded side counts as
-- off the grid).  p_tz is the zone of the grid as the key type uses it.
CREATE FUNCTION kingres.timepart__misaligned(p_parent oid, p_every interval,
                                             p_tz text)
RETURNS TABLE (part_oid oid, part_schema name, part_name name,
               lo timestamptz, hi timestamptz)
LANGUAGE sql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
    SELECT c.part_oid, c.part_schema, c.part_name, c.lo, c.hi
      FROM kingres.timepart__children(p_parent) c
     WHERE NOT c.is_default
       AND NOT (kingres.timepart__on_grid(p_every, p_tz, c.lo)
                AND kingres.timepart__on_grid(p_every, p_tz, c.hi))
     ORDER BY c.lo
$$;

-- The actions of a run at p_as_of (10.1), in this order: misaligned
-- partitions found, partitions to create, partitions to convert, partitions
-- to drop or detach.  Pure in the catalog state and p_as_of.
--
--   create:  every cell from the first existing partition (or the cell that
--            holds p_as_of when there is none) to the last cell whose start
--            is before p_as_of + create_ahead, always including the cell of
--            p_as_of; cells entirely older than the retention boundary are
--            not created (they would be dropped in the same run).
--   convert: partitions that are not columnar and end at or before
--            p_as_of - columnar_after, unless they are about to be retired.
--   retire:  partitions that end at or before p_as_of - retention.
--
-- Partitions whose bounds are not on the grid are not the policy's own: they
-- are reported as misaligned and never converted, dropped or detached by a
-- run (drop_old_time_partitions, called by hand, takes any partition).
CREATE FUNCTION kingres.timepart__plan_rows(
    p_parent oid, p_every interval, p_tz text, p_ahead interval,
    p_retention interval, p_retention_action text,
    p_columnar_after interval, p_as_of timestamptz)
RETURNS TABLE (seq integer, kind text, part_oid oid, part_schema name,
               part_name name, range_from timestamptz, range_to timestamptz,
               reason text)
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_info    record;
    v_tz      text;
    v_asof    timestamptz;
    v_cur_k   bigint;
    v_first_k bigint;
    v_last_k  bigint;
    v_min_lo  timestamptz;
    v_thr_ret timestamptz;
    v_thr_col timestamptz;
    r         record;
    v_seq     integer := 0;
BEGIN
    IF p_as_of IS NULL OR p_as_of IN ('infinity', '-infinity') THEN
        RAISE EXCEPTION 'as_of must be a finite time' USING ERRCODE = '22008';
    END IF;
    SELECT * INTO v_info FROM kingres.timepart__key_info(p_parent);
    v_tz := CASE WHEN v_info.r_keytype = 'timestamptz' THEN p_tz ELSE 'UTC' END;
    v_asof := kingres.timepart__eff(p_as_of, v_info.r_keytype, p_tz);
    v_thr_ret := CASE WHEN p_retention IS NULL THEN NULL
                      ELSE kingres.timepart__add(v_asof, p_retention, v_tz, -1) END;
    v_thr_col := CASE WHEN p_columnar_after IS NULL THEN NULL
                      ELSE kingres.timepart__add(v_asof, p_columnar_after, v_tz, -1) END;

    -- Partitions whose bounds are not on the grid are reported and left alone.
    FOR r IN SELECT * FROM kingres.timepart__misaligned(p_parent, p_every, v_tz) c
    LOOP
        v_seq := v_seq + 1;
        seq := v_seq; kind := 'misaligned';
        part_oid := r.part_oid; part_schema := r.part_schema;
        part_name := r.part_name;
        range_from := r.lo; range_to := r.hi;
        reason := 'bounds are not on the grid of the policy';
        RETURN NEXT;
    END LOOP;

    -- Partitions to create.
    SELECT min(c.lo) INTO v_min_lo
      FROM kingres.timepart__children(p_parent) c
     WHERE NOT c.is_default AND c.lo > '-infinity';
    v_cur_k := kingres.timepart_cell_of(p_every, v_tz, v_asof);
    v_first_k := v_cur_k;
    IF v_min_lo IS NOT NULL THEN
        v_first_k := least(v_cur_k,
                           kingres.timepart_cell_of(p_every, v_tz, v_min_lo));
    END IF;
    IF v_thr_ret IS NOT NULL THEN
        v_first_k := greatest(v_first_k,
                              kingres.timepart_cell_of(p_every, v_tz, v_thr_ret));
    END IF;
    v_last_k := greatest(
        v_cur_k,
        kingres.timepart_cell_of(
            p_every, v_tz,
            kingres.timepart__add(v_asof, p_ahead, v_tz, 1)
            - interval '1 microsecond'));
    FOR r IN SELECT * FROM kingres.timepart__create_rows(
                 p_parent, p_every, v_tz, v_first_k, v_last_k) c
    LOOP
        v_seq := v_seq + 1;
        seq := v_seq; kind := 'create';
        part_oid := NULL; part_schema := r.part_schema;
        part_name := r.part_name;
        range_from := r.lo; range_to := r.hi;
        reason := 'missing partition';
        RETURN NEXT;
    END LOOP;

    -- Partitions to convert.
    IF v_thr_col IS NOT NULL THEN
        FOR r IN SELECT * FROM kingres.timepart__children(p_parent) c
                  WHERE NOT c.is_default AND c.hi < 'infinity'
                    AND c.hi <= v_thr_col
                    AND kingres.timepart__on_grid(p_every, v_tz, c.lo)
                    AND kingres.timepart__on_grid(p_every, v_tz, c.hi)
                    AND c.am_name IS DISTINCT FROM 'columnar'
                    AND NOT (v_thr_ret IS NOT NULL AND c.hi <= v_thr_ret)
                  ORDER BY c.hi
        LOOP
            v_seq := v_seq + 1;
            seq := v_seq; kind := 'convert';
            part_oid := r.part_oid; part_schema := r.part_schema;
            part_name := r.part_name;
            range_from := r.lo; range_to := r.hi;
            reason := 'older than columnar_after';
            RETURN NEXT;
        END LOOP;
    END IF;

    -- Partitions to retire.
    IF v_thr_ret IS NOT NULL THEN
        FOR r IN SELECT * FROM kingres.timepart__children(p_parent) c
                  WHERE NOT c.is_default AND c.hi < 'infinity'
                    AND c.hi <= v_thr_ret
                    AND kingres.timepart__on_grid(p_every, v_tz, c.lo)
                    AND kingres.timepart__on_grid(p_every, v_tz, c.hi)
                  ORDER BY c.hi
        LOOP
            v_seq := v_seq + 1;
            seq := v_seq;
            kind := CASE WHEN p_retention_action = 'detach' THEN 'detach'
                         ELSE 'drop' END;
            part_oid := r.part_oid; part_schema := r.part_schema;
            part_name := r.part_name;
            range_from := r.lo; range_to := r.hi;
            reason := 'older than retention';
            RETURN NEXT;
        END LOOP;
    END IF;
END;
$$;

------------------------------------------------------------------------
-- The two DDL steps (SECURITY INVOKER: PostgreSQL checks the privileges)
------------------------------------------------------------------------

-- Create one partition: a separate table made with CREATE TABLE ... (LIKE
-- parent), then ATTACH PARTITION.  CREATE TABLE ... PARTITION OF would take
-- ACCESS EXCLUSIVE on the parent; LIKE reads it with ACCESS SHARE and ATTACH
-- PARTITION takes SHARE UPDATE EXCLUSIVE, which blocks neither readers nor
-- writers.  The table is empty, so the attach scans nothing and no helper
-- CHECK constraint is needed.  One transaction: a failure leaves nothing.
-- The caller sets lock_timeout.
--
-- The statements are built by timepart__create_stmts and executed by the
-- caller, so that a run can execute them as the owner of the table (see
-- timepart__exec_as) without that role needing any right on this schema.
CREATE FUNCTION kingres.timepart__create_stmts(
    p_parent oid, p_schema name, p_name name, p_from text, p_to text,
    p_am name DEFAULT NULL)
RETURNS text[]
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_info   record;
    v_parent text;
    v_part   text := format('%I.%I', p_schema, p_name);
BEGIN
    SELECT * INTO v_info FROM kingres.timepart__key_info(p_parent);
    v_parent := format('%I.%I', v_info.r_schema, v_info.r_table);
    IF kingres.timepart__oid(p_schema, p_name) IS NOT NULL THEN
        RAISE EXCEPTION 'name_conflict: relation % already exists and is not the expected partition of %',
            v_part, v_parent USING ERRCODE = '42P07';
    END IF;
    RETURN ARRAY[
        format('CREATE TABLE %s (LIKE %s INCLUDING DEFAULTS INCLUDING CONSTRAINTS '
               'INCLUDING INDEXES INCLUDING STORAGE INCLUDING COMMENTS '
               'INCLUDING GENERATED INCLUDING COMPRESSION)%s',
               v_part, v_parent,
               CASE WHEN p_am IS NULL THEN '' ELSE format(' USING %I', p_am) END),
        format('ALTER TABLE %s ATTACH PARTITION %s FOR VALUES FROM (%L) TO (%L)',
               v_parent, v_part, p_from, p_to)];
END;
$$;

CREATE FUNCTION kingres.timepart_create_one(p_parent oid, p_schema name,
                                            p_name name, p_from text,
                                            p_to text, p_am name DEFAULT NULL)
RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_stmt text;
BEGIN
    FOREACH v_stmt IN ARRAY kingres.timepart__create_stmts(
                 p_parent, p_schema, p_name, p_from, p_to, p_am) LOOP
        EXECUTE v_stmt;
    END LOOP;
END;
$$;

-- Retire one partition: detach it and, unless p_detach_only, drop it, in the
-- caller's transaction.  DETACH PARTITION needs ACCESS EXCLUSIVE on the
-- parent (DETACH ... CONCURRENTLY cannot run inside a function or procedure).
-- The caller sets lock_timeout.  As for creation, the statements are built
-- apart and executed by the caller.
CREATE FUNCTION kingres.timepart__retire_stmts(p_parent oid, p_part oid,
                                               p_detach_only boolean)
RETURNS text[]
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_info   record;
    v_parent text;
    v_part   text;
BEGIN
    SELECT * INTO v_info FROM kingres.timepart__key_info(p_parent);
    v_parent := format('%I.%I', v_info.r_schema, v_info.r_table);
    SELECT format('%I.%I', n.nspname, c.relname) INTO v_part
      FROM pg_inherits i
      JOIN pg_class c ON c.oid = i.inhrelid
      JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE i.inhparent = p_parent AND i.inhrelid = p_part;
    IF v_part IS NULL THEN
        RAISE EXCEPTION 'relation with OID % is not a partition of %',
            p_part, v_parent USING ERRCODE = '42P01';
    END IF;
    RETURN CASE WHEN p_detach_only
        THEN ARRAY[format('ALTER TABLE %s DETACH PARTITION %s', v_parent, v_part)]
        ELSE ARRAY[format('ALTER TABLE %s DETACH PARTITION %s', v_parent, v_part),
                   format('DROP TABLE %s', v_part)] END;
END;
$$;

CREATE FUNCTION kingres.timepart_retire_one(p_parent oid, p_part oid,
                                            p_detach_only boolean)
RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_stmt text;
BEGIN
    FOREACH v_stmt IN ARRAY kingres.timepart__retire_stmts(
                 p_parent, p_part, p_detach_only) LOOP
        EXECUTE v_stmt;
    END LOOP;
END;
$$;

------------------------------------------------------------------------
-- create_time_partitions and drop_old_time_partitions
------------------------------------------------------------------------

CREATE FUNCTION kingres.create_time_partitions(
    rel regclass, partition_every interval, end_at timestamptz,
    start_from timestamptz DEFAULT now(), access_method name DEFAULT NULL,
    timezone text DEFAULT 'UTC')
RETURNS integer
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_info   record;
    v_parts  record;
    v_tz     text;
    v_first  bigint;
    v_last   bigint;
    v_n      integer := 0;
    v_am     name := access_method;
    r        record;
BEGIN
    -- Reading the bounds of the partitions takes a lock on them, so the wait
    -- is bounded from the first statement on.
    PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
    SELECT * INTO v_info FROM kingres.timepart__key_info(rel::oid);
    PERFORM kingres.timepart__require_owner(
        current_user, v_info.r_owner_oid,
        format('%I.%I', v_info.r_schema, v_info.r_table));
    IF v_info.r_default IS NOT NULL THEN
        RAISE EXCEPTION 'table %.% has a default partition "%"',
            quote_ident(v_info.r_schema), quote_ident(v_info.r_table),
            v_info.r_default
            USING ERRCODE = '0A000',
                  HINT = 'ATTACH PARTITION scans the default partition under a strong lock; create partitions far enough ahead instead.';
    END IF;
    PERFORM kingres.timepart__check_tz(timezone);
    SELECT * INTO v_parts FROM kingres.timepart_interval_parts(partition_every);
    IF v_info.r_keytype = 'date' AND v_parts.unit = 'hour' THEN
        RAISE EXCEPTION 'partition_every in hours needs a timestamp or timestamptz column, not date'
            USING ERRCODE = '22023';
    END IF;
    IF end_at IS NULL OR start_from IS NULL
       OR end_at IN ('infinity', '-infinity')
       OR start_from IN ('infinity', '-infinity') THEN
        RAISE EXCEPTION 'start_from and end_at must be finite times'
            USING ERRCODE = '22008';
    END IF;
    v_tz := CASE WHEN v_info.r_keytype = 'timestamptz' THEN timezone ELSE 'UTC' END;
    v_first := kingres.timepart_cell_of(
        partition_every, v_tz,
        kingres.timepart__eff(start_from, v_info.r_keytype, timezone));
    v_last := kingres.timepart_cell_of(
        partition_every, v_tz,
        kingres.timepart__eff(end_at, v_info.r_keytype, timezone));
    IF v_last < v_first THEN
        RAISE EXCEPTION 'end_at is before start_from' USING ERRCODE = '22023';
    END IF;
    IF v_am IS NULL THEN
        SELECT a.amname INTO v_am FROM pg_am a WHERE a.oid = v_info.r_am;
    END IF;
    FOR r IN SELECT * FROM kingres.timepart__create_rows(
                 rel::oid, partition_every, v_tz, v_first, v_last) c
    LOOP
        PERFORM kingres.timepart_create_one(
            rel::oid, r.part_schema, r.part_name,
            kingres.timepart__bound_literal(v_info.r_keytype, r.lo),
            kingres.timepart__bound_literal(v_info.r_keytype, r.hi), v_am);
        v_n := v_n + 1;
    END LOOP;
    RETURN v_n;
END;
$$;

CREATE FUNCTION kingres.drop_old_time_partitions(
    rel regclass, older_than timestamptz, detach_only boolean DEFAULT false,
    timezone text DEFAULT 'UTC')
RETURNS integer
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_info   record;
    v_limit  timestamptz;
    v_n      integer := 0;
    r        record;
BEGIN
    PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('retire'), true);
    SELECT * INTO v_info FROM kingres.timepart__key_info(rel::oid);
    PERFORM kingres.timepart__require_owner(
        current_user, v_info.r_owner_oid,
        format('%I.%I', v_info.r_schema, v_info.r_table));
    PERFORM kingres.timepart__check_tz(timezone);
    IF older_than IS NULL OR older_than IN ('infinity', '-infinity') THEN
        RAISE EXCEPTION 'older_than must be a finite time' USING ERRCODE = '22008';
    END IF;
    v_limit := kingres.timepart__eff(older_than, v_info.r_keytype, timezone);
    FOR r IN SELECT * FROM kingres.timepart__children(rel::oid) c
              WHERE NOT c.is_default AND c.hi < 'infinity' AND c.hi <= v_limit
              ORDER BY c.hi
    LOOP
        PERFORM kingres.timepart_retire_one(rel::oid, r.part_oid,
                                            coalesce(detach_only, false));
        v_n := v_n + 1;
    END LOOP;
    RETURN v_n;
END;
$$;

------------------------------------------------------------------------
-- Policies
------------------------------------------------------------------------

-- Is the table named by a policy row one that the calling role owns (has the
-- privileges of the owner of)?  Used by the views of the policy
-- and history tables, so it judges current_user, the role whose privileges
-- PostgreSQL is applying, and not the role that logged in.
CREATE FUNCTION kingres.timepart__owns(p_schema name, p_table name)
RETURNS boolean
LANGUAGE sql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
    SELECT coalesce(
        (SELECT pg_has_role(current_user, c.relowner, 'USAGE')
           FROM pg_class c
          WHERE c.oid = kingres.timepart__oid(p_schema, p_table)
            AND c.relkind = 'p'), false)
$$;

-- What the views of the policy and the history show to the calling role: the
-- rows of the tables it owns; a superuser sees every row (the policy of a
-- table that is gone too: timepart_check reports it).
CREATE FUNCTION kingres.timepart__visible(p_schema name, p_table name)
RETURNS boolean
LANGUAGE sql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
    SELECT coalesce((SELECT r.rolsuper FROM pg_roles r
                      WHERE r.rolname = current_user), false)
           OR kingres.timepart__owns(p_schema, p_table)
$$;

-- The checks on the values of a policy that do not depend on who sets it.
CREATE FUNCTION kingres.timepart__validate_policy(
    p_keytype text, p_every interval, p_tz text, p_ahead interval,
    p_retention interval, p_action text, p_col_after interval,
    p_col_sort text[], p_col_options jsonb, p_run_every interval)
RETURNS void
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_parts record;
BEGIN
    PERFORM kingres.timepart__check_tz(p_tz);
    SELECT * INTO v_parts FROM kingres.timepart_interval_parts(p_every);
    IF p_keytype = 'date' AND v_parts.unit = 'hour' THEN
        RAISE EXCEPTION 'partition_every in hours needs a timestamp or timestamptz column, not date'
            USING ERRCODE = '22023';
    END IF;
    IF p_ahead IS NULL OR p_ahead < interval '0' THEN
        RAISE EXCEPTION 'create_ahead must not be negative' USING ERRCODE = '22023';
    END IF;
    IF p_run_every IS NULL OR p_run_every <= interval '0' THEN
        RAISE EXCEPTION 'run_every must be positive' USING ERRCODE = '22023';
    END IF;
    IF p_action IS NULL OR p_action NOT IN ('drop', 'detach') THEN
        RAISE EXCEPTION 'retention_action must be drop or detach'
            USING ERRCODE = '22023';
    END IF;
    IF p_retention IS NOT NULL AND p_retention < p_every THEN
        RAISE EXCEPTION 'retention must be at least one partition_every'
            USING ERRCODE = '22023',
                  HINT = 'Retention drops whole partitions only.';
    END IF;
    IF p_col_after IS NOT NULL AND p_col_after < interval '0' THEN
        RAISE EXCEPTION 'columnar_after must not be negative' USING ERRCODE = '22023';
    END IF;
    IF p_col_after IS NOT NULL AND p_retention IS NOT NULL
       AND p_col_after > p_retention THEN
        RAISE EXCEPTION 'columnar_after must not be longer than retention'
            USING ERRCODE = '22023';
    END IF;
    IF p_col_options IS NOT NULL
       AND jsonb_typeof(p_col_options) <> 'object' THEN
        RAISE EXCEPTION 'columnar_options must be a JSON object'
            USING ERRCODE = '22023';
    END IF;
    PERFORM kingres.timepart__columnar_options(p_col_options);
    IF p_col_sort IS NOT NULL
       AND (cardinality(p_col_sort) = 0
            OR array_position(p_col_sort, NULL::text) IS NOT NULL) THEN
        RAISE EXCEPTION 'columnar_sort must be a non-empty list of column names'
            USING ERRCODE = '22023';
    END IF;
END;
$$;

-- The rows of the policy table can be written directly by the role that owns
-- the table (through the view), so what only the extension may decide is
-- pinned here, for every role that is not a superuser: the stamp and the OID
-- hint, the owner recorded for the owner_changed check (renewed only when the
-- policy is written again by a role that owns the table now), who created the
-- policy and when; and the values of the policy are checked.  A superuser
-- (the extension's own code, a restore) is trusted with what it writes: what
-- it leaves out is filled in, what it gives is kept.  That does not make the
-- row trusted by the maintenance: only a row with a seal is (see the table
-- timepart_policy_seal).  A role's write that passes the checks below asks
-- for the seal; a superuser's does not, unless an interface function says so.
CREATE FUNCTION kingres.timepart__policy_trg()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_oid  oid;
    v_info record;
    v_set  boolean;
    v_me   oid;
BEGIN
    SELECT r.oid INTO v_me FROM pg_roles r WHERE r.rolname = current_user;
    IF EXISTS (SELECT 1 FROM pg_roles r WHERE r.rolname = current_user AND r.rolsuper) THEN
        IF NEW.table_owner_oid IS NULL OR NEW.table_owner IS NULL THEN
            SELECT c.relowner, pg_get_userbyid(c.relowner) INTO NEW.table_owner_oid, NEW.table_owner
              FROM pg_class c WHERE c.oid = kingres.timepart__oid(NEW.schema_name, NEW.table_name);
        END IF;
        IF NEW.created_by IS NULL THEN
            NEW.created_by := current_user;
            NEW.created_by_oid := v_me;
        END IF;
        RETURN NEW;
    END IF;
    v_oid := kingres.timepart__oid(NEW.schema_name, NEW.table_name);
    IF v_oid IS NULL THEN
        RAISE EXCEPTION 'table %.% does not exist',
            quote_ident(NEW.schema_name), quote_ident(NEW.table_name)
            USING ERRCODE = '42P01';
    END IF;
    SELECT * INTO v_info FROM kingres.timepart__key_info(v_oid);
    PERFORM kingres.timepart__require_owner(
        current_user, v_info.r_owner_oid,
        format('%I.%I', v_info.r_schema, v_info.r_table));
    PERFORM kingres.timepart__validate_policy(
        v_info.r_keytype, NEW.partition_every, NEW.timezone, NEW.create_ahead,
        NEW.retention, NEW.retention_action, NEW.columnar_after,
        NEW.columnar_sort, NEW.columnar_options, NEW.run_every);
    NEW.parent_oid := v_oid;
    NEW.stamp := kingres.timepart__stamp();
    IF TG_OP = 'INSERT' THEN
        NEW.table_owner := v_info.r_owner;
        NEW.table_owner_oid := v_info.r_owner_oid;
        NEW.created_by := current_user;
        NEW.created_by_oid := v_me;
        NEW.created_at := now();
        NEW.updated_at := now();
    ELSE
        NEW.created_by := OLD.created_by;
        NEW.created_by_oid := OLD.created_by_oid;
        NEW.created_at := OLD.created_at;
        v_set := (NEW.schema_name, NEW.table_name,
                  NEW.partition_every, NEW.timezone, NEW.create_ahead,
                  NEW.retention, NEW.retention_action, NEW.columnar_after,
                  NEW.columnar_sort, NEW.columnar_options, NEW.run_every,
                  NEW.enabled, NEW.updated_at)
                 IS DISTINCT FROM
                 (OLD.schema_name, OLD.table_name,
                  OLD.partition_every, OLD.timezone, OLD.create_ahead,
                  OLD.retention, OLD.retention_action, OLD.columnar_after,
                  OLD.columnar_sort, OLD.columnar_options, OLD.run_every,
                  OLD.enabled, OLD.updated_at);
        IF v_set THEN
            NEW.table_owner := v_info.r_owner;
            NEW.table_owner_oid := v_info.r_owner_oid;
            NEW.updated_at := now();
        ELSE
            NEW.table_owner := OLD.table_owner;
            NEW.table_owner_oid := OLD.table_owner_oid;
            NEW.stamp := OLD.stamp;
        END IF;
    END IF;
    -- every check has passed: the row is the interface's own, and gets its seal
    PERFORM kingres.timepart__mark_seal(NEW.schema_name, NEW.table_name);
    RETURN NEW;
END;
$$;

CREATE TRIGGER timepart_policy_pin
    BEFORE INSERT OR UPDATE ON kingres.timepart_policy_data
    FOR EACH ROW EXECUTE FUNCTION kingres.timepart__policy_trg();

-- What a role may see and change of the three tables is decided by views, not
-- by row-level security.  Row-level security would make pg_dump fail for
-- every role that is not a superuser, not the owner and without BYPASSRLS,
-- also a role with pg_read_all_data, because pg_dump runs with
-- row_security = off.  The base tables grant nothing to PUBLIC, so pg_dump
-- (a superuser, or a role that reads every table) reads them as they are.
-- Everybody else reaches them through these views.  A view is checked
-- against the privileges of its owner (the extension owner) for the table it
-- reads, while the condition of the view calls timepart__visible, which judges
-- current_user: the role whose privileges PostgreSQL is applying, also inside
-- a SECURITY DEFINER function of another role.  security_barrier keeps a
-- function of the caller in a WHERE clause from seeing a row before the
-- condition of the view has hidden it, and the CASCADED CHECK OPTION keeps a
-- write from making a row the view would not show (a policy for a table the
-- role does not own).  The views are not security_invoker: that would check
-- the privileges of the caller on the base tables, which has none.
-- The roles are shown by their names in the catalog now (table_owner and
-- created_by are computed, so they cannot be written; the trigger decides
-- them).  A policy is shown to the roles that own its table now.  A run is
-- shown to the roles that owned the table when the run began (see
-- timepart__run_visible), so the history of a dropped table stays with the
-- owner it had and is not shown to whoever makes a table of that name later;
-- table_oid is the table the run was made for, null when it is gone.
CREATE VIEW kingres.timepart_policy WITH (security_barrier = true) AS
SELECT p.schema_name, p.table_name, p.parent_oid, p.partition_every,
       p.timezone, p.create_ahead, p.retention, p.retention_action,
       p.columnar_after, p.columnar_sort, p.columnar_options, p.run_every,
       p.enabled, p.next_run_at,
       kingres.timepart__role_name(
           kingres.timepart__policy_stamp(p.schema_name, p.table_name, p.stamp),
           p.table_owner_oid, p.table_owner)
           AS table_owner,
       kingres.timepart__role_name(
           kingres.timepart__policy_stamp(p.schema_name, p.table_name, p.stamp),
           p.created_by_oid, p.created_by)
           AS created_by,
       p.created_at, p.updated_at
  FROM kingres.timepart_policy_data p
 WHERE kingres.timepart__visible(p.schema_name, p.table_name)
WITH CASCADED CHECK OPTION;

CREATE VIEW kingres.timepart_run WITH (security_barrier = true) AS
SELECT r.run_id, r.schema_name, r.table_name,
       kingres.timepart__run_table(r.stamp, r.table_oid, r.schema_name,
                                   r.table_name, r.table_owner_oid,
                                   r.table_owner) AS table_oid,
       kingres.timepart__role_name(r.stamp, r.table_owner_oid, r.table_owner)
           AS table_owner,
       r.as_of, r.trigger, r.state, r.started_at, r.finished_at,
       kingres.timepart__role_name(r.stamp, r.started_by_oid, r.started_by)
           AS started_by,
       r.error, r.backend_pid, r.backend_start
  FROM kingres.timepart_run_data r
 WHERE kingres.timepart__run_visible(r.stamp, r.table_owner_oid, r.table_owner);

CREATE VIEW kingres.timepart_run_action WITH (security_barrier = true) AS
SELECT a.* FROM kingres.timepart_run_action_data a
 WHERE EXISTS (SELECT 1 FROM kingres.timepart_run_data r
                WHERE r.run_id = a.run_id
                  AND kingres.timepart__run_visible(r.stamp, r.table_owner_oid,
                                                    r.table_owner));

CREATE FUNCTION kingres.timepart_set_policy(
    rel regclass, partition_every interval,
    create_ahead interval DEFAULT '7 days',
    retention interval DEFAULT NULL,
    retention_action text DEFAULT 'drop',
    columnar_after interval DEFAULT NULL,
    columnar_sort text[] DEFAULT NULL,
    columnar_options jsonb DEFAULT NULL,
    timezone text DEFAULT 'UTC',
    run_every interval DEFAULT '1 hour',
    enabled boolean DEFAULT true)
RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_info   record;
BEGIN
    SELECT * INTO v_info FROM kingres.timepart__key_info(rel::oid);
    PERFORM kingres.timepart__require_owner(
        current_user, v_info.r_owner_oid,
        format('%I.%I', v_info.r_schema, v_info.r_table));
    IF v_info.r_default IS NOT NULL THEN
        RAISE EXCEPTION 'table %.% has a default partition "%"',
            quote_ident(v_info.r_schema), quote_ident(v_info.r_table),
            v_info.r_default
            USING ERRCODE = '0A000',
                  HINT = 'ATTACH PARTITION scans the default partition under a strong lock, and DETACH ... CONCURRENTLY is refused; create partitions far enough ahead instead.';
    END IF;
    PERFORM kingres.timepart__validate_policy(
        v_info.r_keytype, partition_every, timezone, create_ahead, retention,
        retention_action, columnar_after, columnar_sort, columnar_options,
        run_every);

    -- A role writes through the view, and the trigger pins what it must not
    -- choose (the owner, the stamp, who made the policy).  A superuser, which
    -- the trigger trusts, writes the table itself, with the same values.
    IF EXISTS (SELECT 1 FROM pg_roles r
                WHERE r.rolname = current_user AND r.rolsuper) THEN
        -- the one write of a superuser that asks for a seal: this function is
        -- the documented interface
        PERFORM kingres.timepart__mark_seal(v_info.r_schema, v_info.r_table);
        INSERT INTO kingres.timepart_policy_data AS p (
            schema_name, table_name, parent_oid, partition_every, timezone,
            create_ahead, retention, retention_action, columnar_after,
            columnar_sort, columnar_options, run_every, enabled, table_owner,
            table_owner_oid, created_by, created_by_oid, stamp)
        VALUES (
            v_info.r_schema, v_info.r_table, rel::oid, partition_every, timezone,
            create_ahead, retention, retention_action, columnar_after,
            columnar_sort, columnar_options, run_every, enabled, v_info.r_owner,
            v_info.r_owner_oid, current_user,
            (SELECT r.oid FROM pg_roles r WHERE r.rolname = current_user),
            kingres.timepart__stamp())
        ON CONFLICT (schema_name, table_name) DO UPDATE SET
            parent_oid = EXCLUDED.parent_oid,
            partition_every = EXCLUDED.partition_every,
            timezone = EXCLUDED.timezone,
            create_ahead = EXCLUDED.create_ahead,
            retention = EXCLUDED.retention,
            retention_action = EXCLUDED.retention_action,
            columnar_after = EXCLUDED.columnar_after,
            columnar_sort = EXCLUDED.columnar_sort,
            columnar_options = EXCLUDED.columnar_options,
            run_every = EXCLUDED.run_every,
            enabled = EXCLUDED.enabled,
            table_owner = EXCLUDED.table_owner,
            table_owner_oid = EXCLUDED.table_owner_oid,
            stamp = EXCLUDED.stamp,
            updated_at = clock_timestamp();
    ELSE
        INSERT INTO kingres.timepart_policy AS p (
            schema_name, table_name, parent_oid, partition_every, timezone,
            create_ahead, retention, retention_action, columnar_after,
            columnar_sort, columnar_options, run_every, enabled)
        VALUES (
            v_info.r_schema, v_info.r_table, rel::oid, partition_every, timezone,
            create_ahead, retention, retention_action, columnar_after,
            columnar_sort, columnar_options, run_every, enabled)
        ON CONFLICT (schema_name, table_name) DO UPDATE SET
            parent_oid = EXCLUDED.parent_oid,
            partition_every = EXCLUDED.partition_every,
            timezone = EXCLUDED.timezone,
            create_ahead = EXCLUDED.create_ahead,
            retention = EXCLUDED.retention,
            retention_action = EXCLUDED.retention_action,
            columnar_after = EXCLUDED.columnar_after,
            columnar_sort = EXCLUDED.columnar_sort,
            columnar_options = EXCLUDED.columnar_options,
            run_every = EXCLUDED.run_every,
            enabled = EXCLUDED.enabled,
            updated_at = clock_timestamp();
    END IF;
END;
$$;

CREATE FUNCTION kingres.timepart_unset_policy(rel regclass)
RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_info   record;
BEGIN
    SELECT * INTO v_info FROM kingres.timepart__key_info(rel::oid);
    PERFORM kingres.timepart__require_owner(
        current_user, v_info.r_owner_oid,
        format('%I.%I', v_info.r_schema, v_info.r_table));
    DELETE FROM kingres.timepart_policy p
     WHERE p.schema_name = v_info.r_schema AND p.table_name = v_info.r_table;
END;
$$;

CREATE FUNCTION kingres.timepart_plan(rel regclass,
                                      as_of timestamptz DEFAULT now())
RETURNS TABLE (seq integer, kind text, partition_name name,
               range_from timestamptz, range_to timestamptz, reason text)
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_info   record;
    v_pol    kingres.timepart_policy%ROWTYPE;
BEGIN
    -- Reading the bounds of the partitions takes locks: bound the wait, so that
    -- a long transaction on the table cannot hold a monitor up.
    PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
    SELECT * INTO v_info FROM kingres.timepart__key_info(rel::oid);
    PERFORM kingres.timepart__require_owner(
        current_user, v_info.r_owner_oid,
        format('%I.%I', v_info.r_schema, v_info.r_table));
    SELECT p.* INTO v_pol FROM kingres.timepart_policy p
     WHERE p.schema_name = v_info.r_schema AND p.table_name = v_info.r_table;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'table %.% has no time partitioning policy',
            quote_ident(v_info.r_schema), quote_ident(v_info.r_table)
            USING ERRCODE = '42704';
    END IF;
    RETURN QUERY
    SELECT pr.seq, pr.kind, pr.part_name, pr.range_from, pr.range_to, pr.reason
      FROM kingres.timepart__plan_rows(
               rel::oid, v_pol.partition_every, v_pol.timezone,
               v_pol.create_ahead, v_pol.retention, v_pol.retention_action,
               v_pol.columnar_after, as_of) pr
     ORDER BY pr.seq;
END;
$$;

------------------------------------------------------------------------
-- A run: begin, phases, finish
------------------------------------------------------------------------

-- Runs of a table are kept for 90 days (counted from p_as_of) and at most
-- 1000 of them.  Returns the number deleted.
CREATE FUNCTION kingres.timepart_prune_runs(
    p_schema name, p_table name, p_as_of timestamptz DEFAULT now())
RETURNS bigint
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_n bigint;
BEGIN
    PERFORM kingres.timepart__require_superuser();
    WITH doomed AS (
        SELECT r.run_id
          FROM kingres.timepart_run_data r
         WHERE r.schema_name = p_schema AND r.table_name = p_table
           AND r.state <> 'running'
           AND (r.as_of < p_as_of - interval '90 days'
                OR r.run_id NOT IN (
                    SELECT r2.run_id FROM kingres.timepart_run_data r2
                     WHERE r2.schema_name = p_schema AND r2.table_name = p_table
                     ORDER BY r2.run_id DESC LIMIT 1000))
    ), d AS (
        DELETE FROM kingres.timepart_run_data r USING doomed
         WHERE r.run_id = doomed.run_id RETURNING 1
    )
    SELECT count(*) INTO v_n FROM d;
    RETURN v_n;
END;
$$;

-- Give the rows that a backup carried here the identity of this installation
-- (see "Identity" and the seal).  A policy row that has no seal is inert:
-- nothing acts on it.  It is adopted, and only when p_policies says so (that
-- is the explicit call of a superuser, timepart_adopt; the maintenance never
-- adopts a policy by itself, because a dump is data and any data can be put in
-- one), if all of these hold: the row does not carry the stamp of this
-- installation (a row that does was not written by a restore, which brings the
-- stamp of the installation that made the backup; unless p_own_stamp says that
-- the caller knows better), the table of its name exists, the role that the
-- row names as the owner is the role that owns that table now, and the values
-- of the policy pass the checks of timepart_set_policy.  Then it gets the OIDs
-- of this cluster, the stamp of this installation and its seal.  A row that
-- fails a check is not adopted and says so with a WARNING, and each row that is
-- adopted says so with a NOTICE.  The rows of the history get the OIDs of the
-- roles and tables of their names; that is only information, and happens on
-- every begin of a run and every timepart_due.  p_schema and p_table, when
-- given, restrict it to one table.  Returns the number of rows changed.
CREATE FUNCTION kingres.timepart__adopt(p_schema name, p_table name,
                                        p_policies boolean, p_own_stamp boolean)
RETURNS bigint
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_n     bigint := 0;
    v_k     bigint;
    v_r     kingres.timepart_policy_data%ROWTYPE;
    v_oid   oid;
    v_owner oid;
    v_role  oid;
    v_info  record;
BEGIN
    PERFORM kingres.timepart__require_superuser();
    FOR v_r IN SELECT p.* FROM kingres.timepart_policy_data p
              WHERE p_policies
                AND (p_schema IS NULL
                     OR (p.schema_name = p_schema AND p.table_name = p_table))
                AND NOT kingres.timepart__is_sealed(p.schema_name, p.table_name)
              ORDER BY p.schema_name, p.table_name
    LOOP
        IF v_r.stamp = kingres.timepart__stamp() AND NOT p_own_stamp THEN
            RAISE WARNING 'policy of %.% is not adopted: it carries the stamp of this installation but was not written by it',
                quote_ident(v_r.schema_name), quote_ident(v_r.table_name)
                USING HINT = 'Set the policy again with timepart_set_policy, or call timepart_adopt(true) if the row is known to come from this installation.';
            CONTINUE;
        END IF;
        SELECT c.oid, c.relowner INTO v_oid, v_owner
          FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
         WHERE n.nspname = v_r.schema_name AND c.relname = v_r.table_name
           AND c.relkind = 'p';
        IF v_oid IS NULL THEN
            CONTINUE;           -- no such table: timepart_check reports the orphan
        END IF;
        SELECT ro.oid INTO v_role FROM pg_roles ro WHERE ro.rolname = v_r.table_owner;
        IF v_role IS DISTINCT FROM v_owner THEN
            RAISE WARNING 'policy of %.% is not adopted: it names "%" as the owner of the table, which is owned by "%"',
                quote_ident(v_r.schema_name), quote_ident(v_r.table_name),
                v_r.table_owner, pg_get_userbyid(v_owner);
            CONTINUE;
        END IF;
        BEGIN
            SELECT * INTO v_info FROM kingres.timepart__key_info(v_oid);
            IF v_info.r_default IS NOT NULL THEN
                RAISE EXCEPTION 'the table has a default partition "%"', v_info.r_default;
            END IF;
            PERFORM kingres.timepart__validate_policy(
                v_info.r_keytype, v_r.partition_every, v_r.timezone, v_r.create_ahead,
                v_r.retention, v_r.retention_action, v_r.columnar_after,
                v_r.columnar_sort, v_r.columnar_options, v_r.run_every);
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'policy of %.% is not adopted: %',
                quote_ident(v_r.schema_name), quote_ident(v_r.table_name), SQLERRM;
            CONTINUE;
        END;
        PERFORM kingres.timepart__mark_seal(v_r.schema_name, v_r.table_name);
        UPDATE kingres.timepart_policy_data p
           SET stamp = kingres.timepart__stamp(),
               table_owner_oid = v_owner,
               created_by_oid = (SELECT c.oid FROM pg_roles c WHERE c.rolname = p.created_by),
               parent_oid = v_oid
         WHERE p.schema_name = v_r.schema_name AND p.table_name = v_r.table_name;
        RAISE NOTICE 'policy of %.% adopted: partition_every %, retention %, retention_action %, owner "%"',
            quote_ident(v_r.schema_name), quote_ident(v_r.table_name),
            v_r.partition_every, coalesce(v_r.retention::text, 'none'),
            v_r.retention_action, v_r.table_owner;
        v_n := v_n + 1;
    END LOOP;
    UPDATE kingres.timepart_run_data r
       SET stamp = kingres.timepart__stamp(),
           table_owner_oid = o.oid,
           started_by_oid = (SELECT c.oid FROM pg_roles c WHERE c.rolname = r.started_by),
           table_oid = (SELECT t.oid FROM pg_class t JOIN pg_namespace n ON n.oid = t.relnamespace
                         WHERE n.nspname = r.schema_name AND t.relname = r.table_name
                           AND t.relkind = 'p' AND t.relowner = o.oid)
      FROM pg_roles o
     WHERE r.stamp <> kingres.timepart__stamp() AND o.rolname = r.table_owner
       AND (p_schema IS NULL
            OR (r.schema_name = p_schema AND r.table_name = p_table));
    GET DIAGNOSTICS v_k = ROW_COUNT;
    RETURN v_n + v_k;
END;
$$;

-- The explicit adoption of what a restore carried here, for every table:
-- superuser only.  A policy row whose stamp is the stamp of this installation
-- is adopted only with p_own_stamp = true, which says that the caller knows the
-- row comes from this installation (see timepart__adopt).
CREATE FUNCTION kingres.timepart_adopt(p_own_stamp boolean DEFAULT false)
RETURNS bigint
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    PERFORM kingres.timepart__require_superuser();
    RETURN kingres.timepart__adopt(NULL, NULL, true, coalesce(p_own_stamp, false));
END;
$$;

-- Record a run and claim the table (10.7).  The claim is a row lock on the
-- table's row of kingres.timepart_lock, which only the extension owner can
-- touch (FOR UPDATE NOWAIT, held to the end of this transaction, so it
-- serialises concurrent begins), and the run row itself: it records the
-- backend that made it.  A run whose row says "running" and whose backend
-- (pid and start time) is still alive in pg_stat_activity is live, and a new
-- begin raises 55P03; when the backend is gone the run is marked failed with
-- error 'interrupted'.  A begin in the session that made the live run takes
-- it over.  A run that cannot start (the owner changed, the table is no
-- longer a suitable table, the policy is not sealed) is recorded as failed at
-- once and its id returned.  Called by a superuser, or by the owner of the
-- table for its own table; this is the SECURITY DEFINER half that does the
-- work, timepart_begin_run below tells it who the caller is (see
-- timepart__require_driver).
CREATE FUNCTION kingres.timepart__begin_run(
    rel regclass, as_of timestamptz, trigger text,
    p_caller_oid oid, p_caller_super boolean)
RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_info   record;
    v_schema name;
    v_table  name;
    v_pol    kingres.timepart_policy_data%ROWTYPE;
    r        record;
    v_run    bigint;
    v_error  text;
    v_owner_oid oid;
BEGIN
    -- Reading the partitions of the table takes locks: bound the wait.
    PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
    IF as_of IS NULL OR as_of IN ('infinity', '-infinity') THEN
        RAISE EXCEPTION 'as_of must be a finite time' USING ERRCODE = '22008';
    END IF;
    IF trigger IS NULL OR trigger NOT IN ('schedule', 'manual', 'sql') THEN
        RAISE EXCEPTION 'trigger must be schedule, manual or sql'
            USING ERRCODE = '22023';
    END IF;
    SELECT n.nspname, cl.relname, cl.relowner INTO v_schema, v_table, v_owner_oid
      FROM pg_class cl JOIN pg_namespace n ON n.oid = cl.relnamespace
     WHERE cl.oid = rel::oid;
    PERFORM kingres.timepart__require_driver(v_owner_oid, p_caller_oid, p_caller_super);
    -- The policy row of this table, if a backup carried it here, gets the
    -- OIDs of this cluster first, after the checks of the catalog.
    PERFORM kingres.timepart__adopt(v_schema, v_table, false, false);
    SELECT p.* INTO v_pol FROM kingres.timepart_policy_data p
     WHERE p.schema_name = v_schema AND p.table_name = v_table;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'table %.% has no time partitioning policy',
            quote_ident(v_schema), quote_ident(v_table)
            USING ERRCODE = '42704';
    END IF;

    PERFORM kingres.timepart__claim(v_schema, v_table, 'another run of table %.% is in progress');
    FOR r IN SELECT x.run_id, x.backend_pid
               FROM kingres.timepart_run_data x
              WHERE x.schema_name = v_schema AND x.table_name = v_table
                AND x.state = 'running'
                AND x.backend_pid IS DISTINCT FROM pg_backend_pid()
                AND EXISTS (SELECT 1 FROM pg_stat_activity a
                             WHERE a.pid = x.backend_pid
                               AND a.backend_start = x.backend_start)
    LOOP
        RAISE EXCEPTION 'another run of table %.% is in progress (backend %)',
            quote_ident(v_schema), quote_ident(v_table), r.backend_pid
            USING ERRCODE = '55P03';
    END LOOP;
    UPDATE kingres.timepart_run_data x
       SET state = 'failed', finished_at = now(), error = 'interrupted'
     WHERE x.schema_name = v_schema AND x.table_name = v_table
       AND x.state = 'running';

    -- The policy is bound to the table by name; refresh the OID hint.
    IF v_pol.parent_oid <> rel::oid THEN
        UPDATE kingres.timepart_policy_data p SET parent_oid = rel::oid
         WHERE p.schema_name = v_pol.schema_name AND p.table_name = v_pol.table_name;
    END IF;

    v_error := NULL;
    BEGIN
        IF NOT kingres.timepart__is_sealed(v_pol.schema_name, v_pol.table_name) THEN
            RAISE EXCEPTION 'policy_unverified: the policy of %.% was neither set nor adopted in this installation; nothing acts on it',
                quote_ident(v_schema), quote_ident(v_table)
                USING ERRCODE = '42501',
                      HINT = 'The owner of the table sets the policy again, or a superuser runs timepart_adopt() and reads its warnings.';
        END IF;
        SELECT * INTO v_info FROM kingres.timepart__key_info(rel::oid);
        -- the owner is the role of the policy, by OID: a role that was renamed
        -- is the same owner
        IF v_info.r_owner_oid IS DISTINCT FROM v_pol.table_owner_oid THEN
            RAISE EXCEPTION 'owner_changed: the owner of %.% is now "%", the policy was set for "%"',
                quote_ident(v_info.r_schema), quote_ident(v_info.r_table),
                v_info.r_owner,
                kingres.timepart__role_name(v_pol.stamp, v_pol.table_owner_oid,
                                            v_pol.table_owner)
                USING ERRCODE = '42501';
        END IF;
    EXCEPTION WHEN OTHERS THEN
        v_error := SQLSTATE || ': ' || SQLERRM;
    END;

    -- The run belongs to this table and to the owner it has now, whoever the
    -- policy was set for (a run that fails on owner_changed is the new
    -- owner's to read).
    INSERT INTO kingres.timepart_run_data (schema_name, table_name, as_of, trigger,
                                      state, started_by, started_by_oid,
                                      finished_at, error,
                                      backend_pid, backend_start,
                                      table_oid, table_owner_oid, table_owner)
    VALUES (v_pol.schema_name, v_pol.table_name, as_of, trigger,
            CASE WHEN v_error IS NULL THEN 'running' ELSE 'failed' END,
            session_user,
            (SELECT sr.oid FROM pg_roles sr WHERE sr.rolname = session_user),
            CASE WHEN v_error IS NULL THEN NULL ELSE now() END, v_error,
            pg_backend_pid(),
            (SELECT a.backend_start FROM pg_stat_activity a
              WHERE a.pid = pg_backend_pid()),
            rel::oid, v_owner_oid, pg_get_userbyid(v_owner_oid))
    RETURNING run_id INTO v_run;
    RETURN v_run;
END;
$$;

CREATE FUNCTION kingres.timepart_begin_run(
    rel regclass, as_of timestamptz DEFAULT now(),
    trigger text DEFAULT 'sql')
RETURNS bigint
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_self  oid;
    v_super boolean;
BEGIN
    SELECT r.oid, r.rolsuper INTO v_self, v_super
      FROM pg_roles r WHERE r.rolname = current_user;
    RETURN kingres.timepart__begin_run(rel, as_of, trigger, v_self, v_super);
END;
$$;

-- Lock the row of the table in kingres.timepart_lock, making it if needed,
-- without waiting.  The lock lasts to the end of the transaction.
CREATE FUNCTION kingres.timepart__claim(p_schema name, p_table name,
                                        p_message text)
RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    INSERT INTO kingres.timepart_lock (schema_name, table_name)
    VALUES (p_schema, p_table) ON CONFLICT DO NOTHING;
    PERFORM 1 FROM kingres.timepart_lock l
     WHERE l.schema_name = p_schema AND l.table_name = p_table
       FOR UPDATE NOWAIT;
EXCEPTION WHEN lock_not_available THEN
    RAISE EXCEPTION '%', format(p_message, quote_ident(p_schema),
                                quote_ident(p_table))
        USING ERRCODE = '55P03';
END;
$$;

-- Execute statements as the owner of a table.  The statements are DDL on the
-- owner's table, and DDL makes PostgreSQL run code that the owner wrote: an
-- index expression is evaluated while a partition is attached, a default or a
-- check expression when a table is made.
--
-- Where that code runs decides what the owner can do.  There are two ways to
-- run it, and no third:
--
--   1. The caller IS the owner (timepart__exec_direct): the owner drives the
--      maintenance of its own table from its own session, which is the only
--      way that is isolated.  Nothing of the owner's can outlive its own
--      session, and the session has no rights the owner does not have.
--   2. The caller is a superuser and the code runs in the superuser's
--      session, in a SECURITY DEFINER function owned by the table owner
--      (this function).  PostgreSQL refuses SET ROLE, RESET ROLE and SET
--      SESSION AUTHORIZATION inside such a function, which stops the code
--      from returning to the superuser at once (the test timepart_privilege).
--      That is all it does.  The function runs inside the superuser's session
--      and transaction, and the owner's code can leave things behind in it that
--      run later with the superuser's rights or change what the superuser's
--      next statements mean: an object in the temporary schema (a view that
--      shadows a catalog view), a deferred trigger (it fires at commit as the
--      superuser), a cursor WITH HOLD (it runs its query at commit as the
--      superuser), a prepared statement, a setting changed with
--      set_config(..., false), LISTEN, a session level advisory lock.
--      Cleaning up after the fact cannot be complete from SQL (a LISTEN or a
--      plan cache entry cannot be seen, a setting cannot be told from the
--      superuser's own), and a function that looks like an isolation and is
--      not is worse than none.  So this way is refused for a table whose owner
--      is not a superuser, unless the driver says that it trusts the owners of
--      its tables as it trusts itself, with kingres_timepart.trust_table_owners
--      = on in the session; the README says what that gives away.
CREATE FUNCTION kingres.timepart__exec_direct(p_stmts text[])
RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    s text;
BEGIN
    FOREACH s IN ARRAY p_stmts LOOP
        EXECUTE s;
    END LOOP;
END;
$$;

CREATE FUNCTION kingres.timepart__exec_as(p_owner oid, p_stmts text[])
RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_name  name := pg_get_userbyid(p_owner);
    v_fn    text;
    v_super boolean;
BEGIN
    SELECT r.rolsuper INTO v_super FROM pg_roles r WHERE r.oid = p_owner;
    IF v_super IS NULL THEN
        RAISE EXCEPTION 'role with OID % does not exist', p_owner
            USING ERRCODE = '42704';
    END IF;
    IF p_owner = (SELECT r.oid FROM pg_roles r WHERE r.rolname = current_user) THEN
        PERFORM kingres.timepart__exec_direct(p_stmts);
        RETURN;
    END IF;
    IF NOT v_super AND NOT kingres.timepart__trust_owners() THEN
        RAISE EXCEPTION 'owner_code_not_trusted: the code of "%" would run in the session of "%"',
            v_name, current_user
            USING ERRCODE = '42501',
                  HINT = 'Drive the maintenance of this table as its owner, or set kingres_timepart.trust_table_owners = on in this session if the owners of the tables are trusted as the superuser is.';
    END IF;
    -- a name nobody can know, so that a function of the owner's in the
    -- temporary schema cannot be in the way
    v_fn := 'timepart_exec_' || pg_catalog.replace(pg_catalog.gen_random_uuid()::text, '-', '');
    EXECUTE pg_catalog.format($def$
        CREATE FUNCTION pg_temp.%I(p_stmts pg_catalog.text[])
        RETURNS pg_catalog.void LANGUAGE plpgsql SECURITY DEFINER
        SET search_path = pg_catalog, pg_temp
        AS 'DECLARE s pg_catalog.text; BEGIN FOREACH s IN ARRAY p_stmts LOOP EXECUTE s; END LOOP; END'
    $def$, v_fn);
    EXECUTE pg_catalog.format('ALTER FUNCTION pg_temp.%I(pg_catalog.text[]) OWNER TO %I', v_fn, v_name);
    EXECUTE pg_catalog.format('SELECT pg_temp.%I($1)', v_fn) USING p_stmts;
    EXECUTE pg_catalog.format('DROP FUNCTION pg_temp.%I(pg_catalog.text[])', v_fn);
END;
$$;

-- The first half of an action, SECURITY DEFINER: the checks, the claim of the
-- table, the plan from the catalog at the run's as_of, and the actions that
-- need no DDL (misaligned partitions, the conversion when kingres_columnar is
-- not installed), which it records.  It returns what the caller needs to run the DDL: the
-- action to take and who runs it (o_mode: "direct" when the caller is the owner
-- and drives from its own session, "frame" when a superuser runs the owner's
-- code in its session and trusts that, "recorded" when the action was recorded
-- here and there is nothing to run, "none" when the phase has nothing left).
-- What the caller is (p_caller_oid, p_caller_super, p_caller_plain: it has not
-- changed role) comes from the caller; a caller that lies about it can only
-- be told to run statements it could run anyway.  The caller is judged by
-- session_user: a superuser, or the owner of the table.
CREATE FUNCTION kingres.timepart__step_begin(
    p_run bigint, p_phase text,
    p_caller_oid oid, p_caller_super boolean, p_caller_plain boolean,
    OUT o_more boolean, OUT o_mode text, OUT o_kind text,
    OUT o_owner_oid oid, OUT o_parent oid, OUT o_keytype text, OUT o_am name,
    OUT o_part_schema name, OUT o_part_name name, OUT o_part_oid oid,
    OUT o_from timestamptz, OUT o_to timestamptz, OUT o_bytes bigint,
    OUT o_retries integer, OUT o_sleep_min integer, OUT o_sleep_max integer)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, kingres, pg_temp
SET DateStyle = 'ISO, MDY'
AS $$
DECLARE
    v_run     kingres.timepart_run_data%ROWTYPE;
    v_pol     kingres.timepart_policy_data%ROWTYPE;
    v_info    record;
    v_row     record;
    v_kinds   text[];
    v_seq     integer;
    v_ncols   integer;
    v_have    boolean;
    v_owner_super boolean;
BEGIN
    o_more := false; o_mode := 'none';
    IF p_phase IS NULL OR p_phase NOT IN ('create', 'convert', 'retire') THEN
        RAISE EXCEPTION 'phase must be create, convert or retire'
            USING ERRCODE = '22023';
    END IF;
    -- A key share lock only: the claim of the table orders the steps of its runs,
    -- and a rename or a drop of the table has its event trigger change the rows
    -- of the run, which a stronger lock of this step would hold up (a deadlock
    -- with the DDL that waits for the table that this step is about to read).
    SELECT r.* INTO v_run FROM kingres.timepart_run_data r
     WHERE r.run_id = p_run FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'run % does not exist', p_run USING ERRCODE = '42704';
    END IF;
    -- the owner recorded in the run is meant by its OID when the run was made
    -- here; a run from a backup is a superuser's to drive
    PERFORM kingres.timepart__require_driver(
        CASE WHEN v_run.stamp = kingres.timepart__stamp()
             THEN v_run.table_owner_oid ELSE 0::pg_catalog.oid END,
        p_caller_oid, p_caller_super);
    IF v_run.state <> 'running' THEN
        RETURN;
    END IF;
    -- One step per table at a time, whatever session runs it: a scheduler may
    -- use another connection for each step.  Steps re-plan from the catalog, so
    -- steps of two runs that follow each other are safe; they must not overlap.
    PERFORM kingres.timepart__claim(v_run.schema_name, v_run.table_name,
                                    'another step of a run of table %.% is in progress');
    o_retries := kingres.timepart__setting_int(
                     'kingres_timepart.lock_retries', 5, 1, 20);
    o_sleep_min := kingres.timepart__setting_int(
                     'kingres_timepart.retry_sleep_min_ms', 200, 0, 60000);
    o_sleep_max := kingres.timepart__setting_int(
                     'kingres_timepart.retry_sleep_max_ms', 2000, 0, 60000);
    IF o_sleep_max < o_sleep_min THEN
        o_sleep_max := o_sleep_min;
    END IF;

    BEGIN
        -- Reading the bounds of the partitions takes a lock on them: the wait is
        -- bounded from the first statement on.
        PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout(
            CASE WHEN p_phase = 'retire' THEN 'retire' ELSE 'create' END), true);
        o_parent := kingres.timepart__oid(v_run.schema_name, v_run.table_name)::oid;
        IF o_parent IS NULL THEN
            RAISE EXCEPTION 'table %.% does not exist',
                quote_ident(v_run.schema_name), quote_ident(v_run.table_name)
                USING ERRCODE = '42P01';
        END IF;
        SELECT p.* INTO v_pol FROM kingres.timepart_policy_data p
         WHERE p.schema_name = v_run.schema_name
           AND p.table_name = v_run.table_name;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'table %.% has no time partitioning policy',
                quote_ident(v_run.schema_name), quote_ident(v_run.table_name)
                USING ERRCODE = '42704';
        END IF;
        -- the policy is acted on only if it was set or adopted here, and is as
        -- it was then (see the seal)
        IF NOT kingres.timepart__is_sealed(v_pol.schema_name, v_pol.table_name) THEN
            RAISE EXCEPTION 'policy_unverified: the policy of %.% was neither set nor adopted in this installation; nothing acts on it',
                quote_ident(v_run.schema_name), quote_ident(v_run.table_name)
                USING ERRCODE = '42501';
        END IF;
        SELECT * INTO v_info FROM kingres.timepart__key_info(o_parent);
        IF v_info.r_owner_oid IS DISTINCT FROM v_pol.table_owner_oid THEN
            RAISE EXCEPTION 'owner_changed: the owner of %.% is now "%", the policy was set for "%"',
                quote_ident(v_run.schema_name), quote_ident(v_run.table_name),
                v_info.r_owner,
                kingres.timepart__role_name(v_pol.stamp, v_pol.table_owner_oid,
                                            v_pol.table_owner)
                USING ERRCODE = '42501';
        END IF;
        IF v_pol.parent_oid <> o_parent THEN
            UPDATE kingres.timepart_policy_data p SET parent_oid = o_parent
             WHERE p.schema_name = v_pol.schema_name
               AND p.table_name = v_pol.table_name;
        END IF;
        o_owner_oid := v_info.r_owner_oid;
        o_keytype := v_info.r_keytype;
        SELECT a.amname INTO o_am FROM pg_am a WHERE a.oid = v_info.r_am;

        SELECT coalesce(max(a.seq), 0) + 1 INTO v_seq
          FROM kingres.timepart_run_action_data a WHERE a.run_id = p_run;

        -- The conversion needs kingres_columnar: without it the step says so
        -- once per run and goes on (the run is not failed).
        IF p_phase = 'convert'
           AND NOT EXISTS (SELECT 1 FROM pg_extension e
                            WHERE e.extname = 'kingres_columnar') THEN
            SELECT count(*) INTO v_ncols
              FROM kingres.timepart__plan_rows(
                       o_parent, v_pol.partition_every, v_pol.timezone,
                       v_pol.create_ahead, v_pol.retention,
                       v_pol.retention_action, v_pol.columnar_after,
                       v_run.as_of) pr
             WHERE pr.kind = 'convert';
            SELECT EXISTS (SELECT 1 FROM kingres.timepart_run_action_data a
                            WHERE a.run_id = p_run AND a.kind = 'convert')
              INTO v_have;
            IF v_ncols = 0 OR v_have THEN
                RETURN;
            END IF;
            INSERT INTO kingres.timepart_run_action_data (
                run_id, seq, kind, partition_schema, partition_name, state,
                detail, finished_at)
            VALUES (p_run, v_seq, 'convert', v_run.schema_name,
                    v_run.table_name, 'skipped',
                    format('conversion needs kingres_columnar, which is not installed; %s partition(s) older than columnar_after were not converted', v_ncols),
                    now());
            o_more := true; o_mode := 'recorded';
            RETURN;
        END IF;

        v_kinds := CASE p_phase WHEN 'create' THEN ARRAY['misaligned', 'create']
                                WHEN 'convert' THEN ARRAY['convert']
                                ELSE ARRAY['drop', 'detach'] END;
        SELECT pr.* INTO v_row
          FROM kingres.timepart__plan_rows(
                   o_parent, v_pol.partition_every, v_pol.timezone,
                   v_pol.create_ahead, v_pol.retention, v_pol.retention_action,
                   v_pol.columnar_after, v_run.as_of) pr
         WHERE pr.kind = ANY (v_kinds)
           AND NOT EXISTS (SELECT 1 FROM kingres.timepart_run_action_data a
                            WHERE a.run_id = p_run AND a.kind = pr.kind
                              AND a.partition_schema = pr.part_schema
                              AND a.partition_name = pr.part_name)
         ORDER BY pr.seq LIMIT 1;
        IF NOT FOUND THEN
            RETURN;
        END IF;

        IF v_row.kind = 'misaligned' THEN
            INSERT INTO kingres.timepart_run_action_data (
                run_id, seq, kind, partition_schema, partition_name,
                range_from, range_to, state, detail, finished_at)
            VALUES (p_run, v_seq, 'misaligned', v_row.part_schema,
                    v_row.part_name, v_row.range_from, v_row.range_to,
                    'skipped', v_row.reason || '; left alone', now());
            o_more := true; o_mode := 'recorded';
            RETURN;
        END IF;

        -- Who runs the owner's code, and where (see timepart__exec_as).
        SELECT r.rolsuper INTO v_owner_super FROM pg_roles r WHERE r.oid = o_owner_oid;
        IF p_caller_plain AND p_caller_oid = o_owner_oid THEN
            o_mode := 'direct';
        ELSIF p_caller_super AND (coalesce(v_owner_super, false)
                                  OR kingres.timepart__trust_owners()) THEN
            o_mode := 'frame';
        ELSE
            RAISE EXCEPTION 'owner_code_not_trusted: the code of the owner of %.% would run in the session of "%"',
                quote_ident(v_run.schema_name), quote_ident(v_run.table_name),
                pg_get_userbyid(p_caller_oid)
                USING ERRCODE = '42501',
                      HINT = 'Drive the maintenance of this table as its owner, or set kingres_timepart.trust_table_owners = on in the session of a superuser if the owners of the tables are trusted as the superuser is.';
        END IF;

        o_kind := v_row.kind;
        o_part_schema := v_row.part_schema;
        o_part_name := v_row.part_name;
        o_part_oid := v_row.part_oid;
        o_from := v_row.range_from;
        o_to := v_row.range_to;
        o_bytes := CASE WHEN v_row.part_oid IS NULL THEN NULL
                        ELSE pg_total_relation_size(v_row.part_oid) END;
        o_more := true;
        RETURN;
    EXCEPTION WHEN OTHERS THEN
        -- The run itself failed (not one action): record it.
        UPDATE kingres.timepart_run_data r
           SET state = 'failed', finished_at = now(),
               error = SQLSTATE || ': ' || SQLERRM
         WHERE r.run_id = p_run;
        o_more := false; o_mode := 'none';
        RETURN;
    END;
END;
$$;

-- The second half: record what one action came to.
CREATE FUNCTION kingres.timepart__step_end(
    p_run bigint, p_kind text, p_part_schema name, p_part_name name,
    p_from timestamptz, p_to timestamptz, p_state text, p_detail text,
    p_bytes bigint,
    p_caller_oid oid, p_caller_super boolean)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_run kingres.timepart_run_data%ROWTYPE;
BEGIN
    SELECT r.* INTO v_run FROM kingres.timepart_run_data r
     WHERE r.run_id = p_run FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'run % does not exist', p_run USING ERRCODE = '42704';
    END IF;
    PERFORM kingres.timepart__require_driver(
        CASE WHEN v_run.stamp = kingres.timepart__stamp()
             THEN v_run.table_owner_oid ELSE 0::pg_catalog.oid END,
        p_caller_oid, p_caller_super);
    IF v_run.state <> 'running' THEN
        RAISE EXCEPTION 'run % is not running', p_run USING ERRCODE = '55000';
    END IF;
    INSERT INTO kingres.timepart_run_action_data (
        run_id, seq, kind, partition_schema, partition_name, range_from,
        range_to, state, detail, bytes_before, finished_at)
    SELECT p_run, coalesce(max(a.seq), 0) + 1, p_kind, p_part_schema,
           p_part_name, p_from, p_to, p_state, p_detail,
           CASE WHEN p_kind IN ('drop', 'detach', 'convert') THEN p_bytes END,
           CASE WHEN p_kind = 'convert' THEN clock_timestamp() ELSE now() END
      FROM kingres.timepart_run_action_data a WHERE a.run_id = p_run;
END;
$$;

-- Execute the next outstanding action of one phase and record it; return
-- false when the phase has nothing left.  A driver that wants a time limit for
-- an action issues each call as a statement of its own after SET
-- statement_timeout (see timepart_action_timeout): when the limit strikes while
-- the action runs, the action is recorded as failed with detail
-- statement_timeout and the run goes on.  (A timer cannot be started from
-- inside a running statement, so timepart_run and timepart_run_phase, which
-- are one statement, can only be bounded as a whole.)  It re-plans from the
-- catalog at the run's as_of every time, so it is idempotent: after an
-- interruption the same call does what is left.  An action that failed or was
-- skipped in this run is not tried again in it.  Each call is one transaction
-- of the caller (timepart_run_phase commits after each).  The DDL runs as the
-- owner of the table: directly when the caller is the owner, else in the
-- session of the superuser that calls, see timepart__exec_as.  Lock waits are
-- bounded by the settings kingres_timepart.create_lock_timeout_ms /
-- retire_lock_timeout_ms with up to kingres_timepart.lock_retries attempts
-- separated by a random sleep between retry_sleep_min_ms and
-- retry_sleep_max_ms.  SECURITY INVOKER, because the DDL must run as the
-- caller; the records are written by timepart__step_begin and
-- timepart__step_end.
CREATE FUNCTION kingres.timepart_run_action(p_run bigint, p_phase text)
RETURNS boolean
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
SET DateStyle = 'ISO, MDY'
AS $$
DECLARE
    v_s       record;
    v_self    oid;
    v_super   boolean;
    v_stmts   text[];
    v_state   text;
    v_detail  text;
    v_attempt integer;
    v_tries   integer;
    v_info    record;
    v_sort    text[];
    v_opts    jsonb;
BEGIN
    SELECT r.oid, r.rolsuper INTO v_self, v_super
      FROM pg_roles r WHERE r.rolname = current_user;
    SELECT * INTO v_s FROM kingres.timepart__step_begin(
        p_run, p_phase, v_self, v_super, session_user = current_user);
    IF NOT v_s.o_more THEN
        RETURN false;
    END IF;
    IF v_s.o_mode = 'recorded' THEN
        RETURN true;
    END IF;

    v_state := 'failed';
    -- A conversion copies a whole partition: it is tried once in a run (a
    -- lock that is not granted in time is tried again by the next run, not
    -- by a second copy).
    v_tries := CASE WHEN v_s.o_kind = 'convert' THEN 1 ELSE v_s.o_retries END;
    FOR v_attempt IN 1..v_tries LOOP
        BEGIN
            -- The statements and the lock timeout are prepared here; only the
            -- DDL runs as the table's owner.
            IF v_s.o_kind = 'create' THEN
                PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
                v_stmts := kingres.timepart__create_stmts(
                    v_s.o_parent, v_s.o_part_schema, v_s.o_part_name,
                    kingres.timepart__bound_literal(v_s.o_keytype, v_s.o_from),
                    kingres.timepart__bound_literal(v_s.o_keytype, v_s.o_to),
                    v_s.o_am);
            ELSIF v_s.o_kind = 'convert' THEN
                -- The sort and the options are the policy's; the checks, the
                -- statements and the lock waits of the conversion are
                -- timepart__convert_stmts's.
                PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
                SELECT * INTO v_info FROM kingres.timepart__key_info(v_s.o_parent);
                SELECT p.columnar_sort, p.columnar_options INTO v_sort, v_opts
                  FROM kingres.timepart_policy p
                 WHERE p.schema_name = v_info.r_schema
                   AND p.table_name = v_info.r_table;
                v_stmts := kingres.timepart__convert_stmts(
                    v_s.o_parent, v_s.o_part_oid, 'columnar'::name, v_sort, v_opts);
            ELSE
                PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('retire'), true);
                v_stmts := kingres.timepart__retire_stmts(
                    v_s.o_parent, v_s.o_part_oid, v_s.o_kind = 'detach');
            END IF;
            IF v_s.o_mode = 'direct' THEN
                PERFORM kingres.timepart__exec_direct(v_stmts);
            ELSE
                PERFORM kingres.timepart__exec_as(v_s.o_owner_oid, v_stmts);
            END IF;
            v_state := 'done';
            v_detail := CASE WHEN v_s.o_kind = 'convert' THEN 'converted to columnar' END;
            EXIT;
        EXCEPTION
            WHEN lock_not_available THEN
                v_state := 'failed';
                IF v_s.o_kind = 'convert' AND (SQLERRM LIKE 'swap_lock_timeout:%'
                                               OR SQLERRM LIKE 'schema_changed:%') THEN
                    v_detail := SQLERRM;
                ELSE
                    v_detail := 'lock_timeout: ' || SQLERRM
                                || format(' (attempt %s of %s)', v_attempt, v_tries);
                END IF;
            WHEN query_canceled THEN
                -- The statement_timeout of the driver's statement, or a
                -- cancel by an operator: only the first is an action's
                -- failure.
                IF NOT kingres.timepart__timed_out() THEN
                    RAISE;
                END IF;
                v_state := 'failed';
                v_detail := 'statement_timeout: ' || SQLERRM;
                EXIT;
            WHEN OTHERS THEN
                IF v_s.o_kind = 'convert' AND SQLERRM LIKE 'conversion_refused:%' THEN
                    -- Not a failure of the run: the partition cannot be
                    -- converted as it is (timepart_check reports it).
                    v_state := 'skipped';
                    v_detail := SQLERRM;
                ELSE
                    v_state := 'failed';
                    v_detail := SQLSTATE || ': ' || SQLERRM;
                END IF;
                EXIT;
        END;
        IF v_attempt < v_tries THEN
            PERFORM pg_sleep((v_s.o_sleep_min + random() * (v_s.o_sleep_max - v_s.o_sleep_min)) / 1000.0);
        END IF;
    END LOOP;

    PERFORM kingres.timepart__step_end(
        p_run, v_s.o_kind, v_s.o_part_schema, v_s.o_part_name, v_s.o_from,
        v_s.o_to, v_state, v_detail, v_s.o_bytes, v_self, v_super);
    RETURN true;
END;
$$;

-- Run one phase of a run: create, convert or retire.  One transaction per
-- action; it cannot run inside a transaction block.  Nothing here may be
-- redirected by the caller's search_path: the first statement, and the first
-- after every COMMIT, sets the path of the transaction (a procedure with a SET
-- clause cannot COMMIT), and every function called is schema-qualified.
CREATE PROCEDURE kingres.timepart_run_phase(run_id bigint, phase text)
LANGUAGE plpgsql
AS $$
DECLARE
    v_more boolean;
BEGIN
    PERFORM pg_catalog.set_config('search_path', 'pg_catalog, pg_temp', true);
    LOOP
        v_more := kingres.timepart_run_action(run_id, phase);
        COMMIT;
        PERFORM pg_catalog.set_config('search_path', 'pg_catalog, pg_temp', true);
        -- After a conversion has committed: its result in the history and
        -- the ANALYZE of the new partition, in a transaction of their own.
        IF phase OPERATOR(pg_catalog.=) 'convert' THEN
            PERFORM kingres.timepart__convert_after(run_id);
            COMMIT;
            PERFORM pg_catalog.set_config('search_path', 'pg_catalog, pg_temp', true);
        END IF;
        EXIT WHEN NOT v_more;
    END LOOP;
END;
$$;

-- Close a run: the final state, the next run time and the pruning of old runs.  The state is "failed" when the
-- run itself failed, "partial" when an action failed, otherwise "done"
-- (skipped actions are not failures).  next_run_at is as_of + run_every, or
-- as_of + least(run_every, 5 minutes) when an action failed on a lock
-- timeout.
CREATE FUNCTION kingres.timepart__finish_run(run_id bigint, p_caller_oid oid,
                                          p_caller_super boolean)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_run     kingres.timepart_run_data%ROWTYPE;
    v_nfailed integer;
    v_locked  boolean;
    v_state   text;
BEGIN
    PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
    SELECT r.* INTO v_run FROM kingres.timepart_run_data r
     WHERE r.run_id = timepart__finish_run.run_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'run % does not exist', run_id USING ERRCODE = '42704';
    END IF;
    PERFORM kingres.timepart__require_driver(
        CASE WHEN v_run.stamp = kingres.timepart__stamp()
             THEN v_run.table_owner_oid ELSE 0::pg_catalog.oid END,
        p_caller_oid, p_caller_super);
    SELECT count(*) FILTER (WHERE a.state = 'failed'),
           coalesce(bool_or(a.state = 'failed'
                            AND (a.detail LIKE 'lock_timeout%'
                                 OR a.detail LIKE 'swap_lock_timeout%'
                                 OR a.detail LIKE 'schema_changed%')), false)
      INTO v_nfailed, v_locked
      FROM kingres.timepart_run_action_data a
     WHERE a.run_id = timepart__finish_run.run_id;
    -- A run that could not even read the partitions because of a lock (55P03)
    -- is retried soon, like an action that timed out.
    v_locked := v_locked OR coalesce(v_run.error LIKE '55P03:%', false);
    v_state := CASE WHEN v_run.state = 'failed' THEN 'failed'
                    WHEN v_nfailed > 0 THEN 'partial'
                    ELSE 'done' END;
    UPDATE kingres.timepart_run_data r
       SET state = v_state, finished_at = coalesce(r.finished_at, now())
     WHERE r.run_id = timepart__finish_run.run_id;
    -- The owner of the table can hold a lock on its policy row: then the
    -- policy stays due, and the run is closed all the same.
    BEGIN
        UPDATE kingres.timepart_policy_data p
           SET next_run_at = kingres.timepart__add(
                   v_run.as_of,
                   CASE WHEN v_locked THEN least(p.run_every, interval '5 minutes')
                        ELSE p.run_every END,
                   'UTC', 1)
         WHERE p.schema_name = v_run.schema_name AND p.table_name = v_run.table_name;
    EXCEPTION WHEN lock_not_available THEN
        NULL;
    END;
    PERFORM kingres.timepart_prune_runs(v_run.schema_name, v_run.table_name,
                                        v_run.as_of);
END;
$$;

CREATE FUNCTION kingres.timepart_finish_run(run_id bigint)
RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_self  oid;
    v_super boolean;
BEGIN
    SELECT r.oid, r.rolsuper INTO v_self, v_super
      FROM pg_roles r WHERE r.rolname = current_user;
    PERFORM kingres.timepart__finish_run(run_id, v_self, v_super);
END;
$$;

-- begin, the phases and finish in sequence, for use from psql.  The
-- run's id comes back in run_id.  It commits between actions, so it cannot
-- run inside a transaction block.  Search path: see timepart_run_phase.
CREATE PROCEDURE kingres.timepart_run(
    rel regclass, as_of timestamptz DEFAULT now(),
    phases text[] DEFAULT '{create,convert,retire}',
    INOUT run_id bigint DEFAULT NULL)
LANGUAGE plpgsql
AS $$
DECLARE
    v_ph text;
BEGIN
    PERFORM pg_catalog.set_config('search_path', 'pg_catalog, pg_temp', true);
    -- Refuse a transaction block before anything is done.
    COMMIT;
    PERFORM pg_catalog.set_config('search_path', 'pg_catalog, pg_temp', true);
    PERFORM kingres.timepart__check_phases(phases);
    run_id := kingres.timepart_begin_run(rel, as_of, 'sql');
    COMMIT;
    PERFORM pg_catalog.set_config('search_path', 'pg_catalog, pg_temp', true);
    FOREACH v_ph IN ARRAY ARRAY['create', 'convert', 'retire'] LOOP
        IF v_ph OPERATOR(pg_catalog.=) ANY (phases) THEN
            CALL kingres.timepart_run_phase(run_id, v_ph);
            PERFORM pg_catalog.set_config('search_path', 'pg_catalog, pg_temp', true);
        END IF;
    END LOOP;
    PERFORM kingres.timepart_finish_run(run_id);
    COMMIT;
END;
$$;

CREATE FUNCTION kingres.timepart__check_phases(p_phases text[])
RETURNS void
LANGUAGE plpgsql IMMUTABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    IF p_phases IS NULL OR EXISTS (SELECT 1 FROM unnest(p_phases) u(x)
                                    WHERE u.x IS NULL
                                       OR u.x NOT IN ('create', 'convert', 'retire')) THEN
        RAISE EXCEPTION 'phases must be a list of create, convert and retire'
            USING ERRCODE = '22023';
    END IF;
END;
$$;

-- True when the statement_timeout of the current statement has run out: the
-- session's setting is above zero and the statement has lasted at least 90
-- percent of it.  Tells the timeout from a cancel by an operator.
CREATE FUNCTION kingres.timepart__timed_out()
RETURNS boolean
LANGUAGE sql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
    SELECT s.setting::bigint > 0
           AND clock_timestamp() - statement_timestamp()
               >= (s.setting::bigint * 0.9) * interval '1 millisecond'
      FROM pg_settings s WHERE s.name = 'statement_timeout'
$$;

-- The statement_timeout, in milliseconds, that a driver sets before it calls
-- timepart_run_action: the setting kingres_timepart.action_timeout_ms (default
-- 300000, 5 minutes).
CREATE FUNCTION kingres.timepart_action_timeout()
RETURNS integer
LANGUAGE sql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
    SELECT kingres.timepart__setting_int(
               'kingres_timepart.action_timeout_ms', 300000, 1, 86400000)
$$;

------------------------------------------------------------------------
-- Reading: due policies, partitions, checks, the policy view
------------------------------------------------------------------------

-- The input is called as_of_time, not as_of, because PostgreSQL does not
-- allow an input and an output column of one function to share a name.
--
-- What is due, for the caller: a superuser gets every enabled policy that is
-- due, after the rows that a backup carried here have been adopted (that is
-- the side effect, which is why the function is VOLATILE: it is the one
-- reader that writes, and only a superuser's call does); any other role gets
-- the policies of the tables it owns, as the view shows them, and changes
-- nothing.  A policy without a seal is never listed: the maintenance does not
-- act on it.
CREATE FUNCTION kingres.timepart_due(as_of_time timestamptz DEFAULT now())
RETURNS TABLE (schema_name name, table_name name, as_of timestamptz)
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles r WHERE r.rolname = current_user AND r.rolsuper) THEN
        -- the scheduler asks what is due before it runs anything: rows that a
        -- backup carried here are given the roles and tables of this cluster
        -- now, after the checks of the catalog
        PERFORM kingres.timepart__adopt(NULL, NULL, false, false);
        RETURN QUERY
        SELECT p.schema_name, p.table_name, as_of_time
          FROM kingres.timepart_policy_data p
         WHERE p.enabled AND p.next_run_at <= as_of_time
           AND kingres.timepart__is_sealed(p.schema_name, p.table_name)
         ORDER BY p.next_run_at, p.schema_name, p.table_name;
    ELSE
        RETURN QUERY
        SELECT p.schema_name, p.table_name, as_of_time
          FROM kingres.timepart_policy p
         WHERE p.enabled AND p.next_run_at <= as_of_time
           AND kingres.timepart__is_sealed(p.schema_name, p.table_name)
         ORDER BY p.next_run_at, p.schema_name, p.table_name;
    END IF;
END;
$$;

-- The partitions of a table with bounds, size and format.  Also lists the
-- partitions that a retention policy detached and kept, with attached =
-- false (to the owner of the table only, and only those that the caller can
-- read).  Needs ownership of the table or SELECT on it.
CREATE FUNCTION kingres.timepart_partitions(rel regclass)
RETURNS TABLE (partition regclass, range_from timestamptz,
               range_to timestamptz, access_method name, size_bytes bigint,
               row_estimate bigint, compression_ratio float8,
               attached boolean)
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_info   record;
BEGIN
    -- Reading the bounds of the partitions takes locks: bound the wait, so that
    -- a long transaction on the table cannot hold a monitor up.
    PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
    SELECT * INTO v_info FROM kingres.timepart__key_info(rel::oid);
    IF NOT (pg_has_role(current_user, v_info.r_owner_oid, 'USAGE')
            OR has_table_privilege(current_user, rel::oid, 'SELECT')) THEN
        RAISE EXCEPTION 'permission denied for table %',
            format('%I.%I', v_info.r_schema, v_info.r_table)
            USING ERRCODE = '42501';
    END IF;
    RETURN QUERY
    SELECT format('%I.%I', c.part_schema, c.part_name)::regclass,
           c.lo, c.hi, c.am_name,
           pg_total_relation_size(c.part_oid),
           (SELECT CASE WHEN cl.reltuples < 0 THEN NULL
                        ELSE cl.reltuples::bigint END
              FROM pg_class cl WHERE cl.oid = c.part_oid),
           NULL::float8, true
      FROM kingres.timepart__children(rel::oid) c
     WHERE NOT c.is_default
     ORDER BY c.lo;
    RETURN QUERY
    SELECT DISTINCT ON (a.partition_schema, a.partition_name)
           kingres.timepart__oid(a.partition_schema, a.partition_name)::regclass,
           a.range_from, a.range_to,
           (SELECT am.amname FROM pg_class cl JOIN pg_am am ON am.oid = cl.relam
             WHERE cl.oid = kingres.timepart__oid(a.partition_schema, a.partition_name)),
           pg_total_relation_size(kingres.timepart__oid(a.partition_schema, a.partition_name)),
           (SELECT CASE WHEN cl.reltuples < 0 THEN NULL
                        ELSE cl.reltuples::bigint END
              FROM pg_class cl
             WHERE cl.oid = kingres.timepart__oid(a.partition_schema, a.partition_name)),
           NULL::float8, false
      FROM kingres.timepart_run_action a
      JOIN kingres.timepart_run r ON r.run_id = a.run_id
     WHERE r.table_oid = rel::oid
       AND a.kind = 'detach' AND a.state = 'done'
       AND kingres.timepart__oid(a.partition_schema, a.partition_name) IS NOT NULL
       AND has_table_privilege(current_user,
                               kingres.timepart__oid(a.partition_schema, a.partition_name)::oid, 'SELECT')
       AND NOT EXISTS (
           SELECT 1 FROM pg_inherits i
            WHERE i.inhrelid = kingres.timepart__oid(a.partition_schema, a.partition_name)::oid)
     ORDER BY a.partition_schema, a.partition_name, a.run_id DESC;
END;
$$;

-- Problems of the tables that have a policy: ahead_low, last_run_failed,
-- retire_blocked, convert_blocked, policy_orphan, policy_unverified,
-- default_partition_present, misaligned and lock_timeout.  A superuser sees
-- every table, another role sees the tables it owns.  p_as_of is the time
-- "ahead" is measured from.
CREATE FUNCTION kingres.timepart_check(
    min_ahead interval DEFAULT NULL, as_of timestamptz DEFAULT now())
RETURNS TABLE (schema_name name, table_name name, problem text, detail text)
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_super  boolean;
    v_pol    kingres.timepart_policy%ROWTYPE;
    v_oid    oid;
    v_info   record;
    v_ok     boolean;
    v_tz     text;
    v_last   timestamptz;
    v_need   timestamptz;
    v_run    kingres.timepart_run%ROWTYPE;
    v_mis    text;
BEGIN
    -- Reading the bounds of the partitions takes locks: bound the wait, so that
    -- a long transaction on the table cannot hold a monitor up.
    PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
    SELECT coalesce(bool_or(r.rolsuper), false) INTO v_super
      FROM pg_roles r WHERE r.rolname = current_user;
    FOR v_pol IN SELECT p.* FROM kingres.timepart_policy p
                  ORDER BY p.schema_name, p.table_name
    LOOP
        BEGIN
            v_oid := kingres.timepart__oid(v_pol.schema_name, v_pol.table_name)::oid;
            v_ok := false;
            IF v_oid IS NOT NULL THEN
                BEGIN
                    SELECT * INTO v_info FROM kingres.timepart__key_info(v_oid);
                    v_ok := true;
                EXCEPTION WHEN lock_not_available THEN
                    RAISE;
                WHEN OTHERS THEN
                    v_ok := false;
                END;
            END IF;
            IF NOT v_ok THEN
                IF v_super THEN
                    schema_name := v_pol.schema_name; table_name := v_pol.table_name;
                    problem := 'policy_orphan';
                    detail := 'the table does not exist or is no longer a suitable partitioned table';
                    RETURN NEXT;
                END IF;
                CONTINUE;
            END IF;
            IF NOT pg_has_role(current_user, v_info.r_owner_oid, 'USAGE') THEN
                CONTINUE;
            END IF;

            IF NOT kingres.timepart__is_sealed(v_pol.schema_name, v_pol.table_name) THEN
                schema_name := v_pol.schema_name; table_name := v_pol.table_name;
                problem := 'policy_unverified';
                detail := 'the policy was neither set nor adopted in this installation; nothing acts on it';
                RETURN NEXT;
                CONTINUE;
            END IF;

            IF v_info.r_default IS NOT NULL THEN
                schema_name := v_pol.schema_name; table_name := v_pol.table_name;
                problem := 'default_partition_present';
                detail := format('default partition %I', v_info.r_default);
                RETURN NEXT;
            END IF;

            v_tz := CASE WHEN v_info.r_keytype = 'timestamptz'
                         THEN v_pol.timezone ELSE 'UTC' END;
            SELECT max(c.hi) INTO v_last
              FROM kingres.timepart__children(v_oid) c WHERE NOT c.is_default;
            v_need := kingres.timepart__add(
                kingres.timepart__eff(as_of, v_info.r_keytype, v_pol.timezone),
                coalesce(min_ahead, v_pol.create_ahead / 2), v_tz, 1);
            IF v_last IS NULL OR v_last < v_need THEN
                schema_name := v_pol.schema_name; table_name := v_pol.table_name;
                problem := 'ahead_low';
                detail := CASE WHEN v_last IS NULL THEN 'the table has no partitions'
                               ELSE format('the last partition ends at %s, before %s',
                                           v_last, v_need) END;
                RETURN NEXT;
            END IF;

            SELECT string_agg(format('%I', m.part_name), ', ' ORDER BY m.lo)
              INTO v_mis
              FROM kingres.timepart__misaligned(v_oid, v_pol.partition_every, v_tz) m;
            IF v_mis IS NOT NULL THEN
                schema_name := v_pol.schema_name; table_name := v_pol.table_name;
                problem := 'misaligned';
                detail := 'partitions with bounds off the grid: ' || v_mis;
                RETURN NEXT;
            END IF;

            SELECT r.* INTO v_run FROM kingres.timepart_run r
             WHERE r.table_oid = v_oid
               AND r.state <> 'running'
             ORDER BY r.run_id DESC LIMIT 1;
            IF FOUND AND v_run.state IN ('failed', 'partial') THEN
                schema_name := v_pol.schema_name; table_name := v_pol.table_name;
                problem := 'last_run_failed';
                detail := format('the last run (as of %s) ended %s%s', v_run.as_of,
                                 v_run.state, coalesce(': ' || v_run.error, ''));
                RETURN NEXT;
                -- Actions of that run that could not retire a partition: a view or
                -- a foreign key that needs it, a role that does not own it.
                SELECT string_agg(format('%I (%s)', a.partition_name, left(a.detail, 60)),
                                  '; ' ORDER BY a.seq)
                  INTO v_mis
                  FROM kingres.timepart_run_action a
                 WHERE a.run_id = v_run.run_id AND a.state = 'failed'
                   AND a.kind IN ('drop', 'detach');
                IF v_mis IS NOT NULL THEN
                    schema_name := v_pol.schema_name; table_name := v_pol.table_name;
                    problem := 'retire_blocked';
                    detail := 'partitions that could not be retired: ' || v_mis;
                    RETURN NEXT;
                END IF;
            END IF;
            -- Partitions that the last run could not convert: refused (a
            -- foreign key, an index, a trigger ...), failed (a lock that was
            -- not granted in time, a writer that kept the parent busy), or
            -- not tried because kingres_columnar is not installed.
            IF v_run.run_id IS NOT NULL THEN
                SELECT string_agg(format('%I (%s)', a.partition_name, left(a.detail, 80)),
                                  '; ' ORDER BY a.seq)
                  INTO v_mis
                  FROM kingres.timepart_run_action a
                 WHERE a.run_id = v_run.run_id AND a.kind = 'convert'
                   AND a.state IN ('failed', 'skipped');
                IF v_mis IS NOT NULL THEN
                    schema_name := v_pol.schema_name; table_name := v_pol.table_name;
                    problem := 'convert_blocked';
                    detail := 'partitions that could not be converted: ' || v_mis;
                    RETURN NEXT;
                END IF;
            END IF;
        EXCEPTION WHEN lock_not_available THEN
            schema_name := v_pol.schema_name; table_name := v_pol.table_name;
            problem := 'lock_timeout';
            detail := 'the partitions could not be read before the lock timeout';
            RETURN NEXT;
        WHEN OTHERS THEN
            schema_name := v_pol.schema_name; table_name := v_pol.table_name;
            problem := 'check_failed';
            detail := left(SQLSTATE || ': ' || SQLERRM, 200);
            RETURN NEXT;
        END;
    END LOOP;
END;
$$;

CREATE VIEW kingres.timepart_policies WITH (security_invoker = true) AS
SELECT p.schema_name, p.table_name, p.parent_oid, p.partition_every,
       p.timezone, p.create_ahead, p.retention, p.retention_action,
       p.columnar_after, p.columnar_sort, p.columnar_options, p.run_every,
       p.enabled, p.next_run_at, p.table_owner, p.created_by, p.created_at,
       p.updated_at,
       lr.run_id AS last_run_id, lr.state AS last_run_state,
       lr.as_of AS last_run_as_of, lr.finished_at AS last_run_finished_at,
       lr.error AS last_run_error
  FROM kingres.timepart_policy p
  LEFT JOIN LATERAL (
        SELECT r.run_id, r.state, r.as_of, r.finished_at, r.error
          FROM kingres.timepart_run r
         WHERE r.table_oid = kingres.timepart__oid(p.schema_name, p.table_name)
         ORDER BY r.run_id DESC LIMIT 1) lr ON true;

-- The policy and the history are readable by every role through the views,
-- which show the rows of the tables the role owns.  A role changes a policy
-- through timepart_set_policy and timepart_unset_policy, or directly through
-- the view: the trigger timepart_policy_pin and the check option keep a
-- direct write to the tables the role owns, with the values pinned by the
-- extension.  The history is read only.
GRANT SELECT, INSERT, UPDATE, DELETE ON kingres.timepart_policy TO PUBLIC;
GRANT SELECT ON kingres.timepart_run, kingres.timepart_run_action,
    kingres.timepart_policies TO PUBLIC;

------------------------------------------------------------------------
-- Conversion of a partition (10.4): checks, statements, what follows the commit
------------------------------------------------------------------------

-- The options of a policy or of a call, as the arguments of
-- kingres.columnar_set_options, checked.  Null gives four nulls (the table
-- keeps the settings of the session that makes it).  The keys are the
-- arguments of columnar_set_options; the ranges are those of the settings
-- kingres_columnar.* (columnar_set_options itself checks again).
CREATE FUNCTION kingres.timepart__columnar_options(
    p_opts jsonb,
    OUT o_compression text, OUT o_level integer, OUT o_stripe integer,
    OUT o_chunk integer)
LANGUAGE plpgsql IMMUTABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_key  text;
    v_val  jsonb;
    v_num  numeric;
    v_lo   numeric;
    v_hi   numeric;
BEGIN
    IF p_opts IS NULL THEN
        RETURN;
    END IF;
    IF jsonb_typeof(p_opts) <> 'object' THEN
        RAISE EXCEPTION 'columnar_options must be a JSON object'
            USING ERRCODE = '22023';
    END IF;
    FOR v_key, v_val IN SELECT e.key, e.value FROM jsonb_each(p_opts) e
    LOOP
        IF v_key = 'compression' THEN
            IF jsonb_typeof(v_val) <> 'string'
               OR (v_val #>> '{}') NOT IN ('none', 'pglz', 'lz4', 'zstd', 'auto') THEN
                RAISE EXCEPTION 'columnar_options: compression must be one of none, pglz, lz4, zstd, auto'
                    USING ERRCODE = '22023';
            END IF;
            o_compression := v_val #>> '{}';
        ELSIF v_key IN ('compression_level', 'stripe_row_count', 'chunk_row_count') THEN
            IF jsonb_typeof(v_val) <> 'number' THEN
                RAISE EXCEPTION 'columnar_options: % must be a number', v_key
                    USING ERRCODE = '22023';
            END IF;
            v_num := (v_val #>> '{}')::numeric;
            v_lo := CASE v_key WHEN 'compression_level' THEN 1
                               WHEN 'stripe_row_count' THEN 1000 ELSE 100 END;
            v_hi := CASE v_key WHEN 'compression_level' THEN 19
                               WHEN 'stripe_row_count' THEN 10000000 ELSE 100000 END;
            IF v_num <> trunc(v_num) OR v_num < v_lo OR v_num > v_hi THEN
                RAISE EXCEPTION 'columnar_options: % is out of range', v_key
                    USING ERRCODE = '22023',
                          HINT = 'compression_level 1 to 19, stripe_row_count 1000 to 10000000, chunk_row_count 100 to 100000, all whole numbers.';
            END IF;
            IF v_key = 'compression_level' THEN
                o_level := v_num::integer;
            ELSIF v_key = 'stripe_row_count' THEN
                o_stripe := v_num::integer;
            ELSE
                o_chunk := v_num::integer;
            END IF;
        ELSE
            RAISE EXCEPTION 'columnar_options: unknown option "%"', v_key
                USING ERRCODE = '22023',
                      HINT = 'The options are compression, compression_level, stripe_row_count and chunk_row_count.';
        END IF;
    END LOOP;
END;
$$;

-- What kind of table access method a name is: 'heap', 'columnar' (by its
-- handler, as kingres_columnar itself decides, never by the name), 'other', or
-- null when there is no table access method of that name.
CREATE FUNCTION kingres.timepart__am_kind(p_am name)
RETURNS text
LANGUAGE sql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
    SELECT CASE
             WHEN a.amhandler = 'pg_catalog.heap_tableam_handler'::pg_catalog.regproc
                  THEN 'heap'
             WHEN EXISTS (SELECT 1 FROM pg_catalog.pg_proc p
                           WHERE p.oid = a.amhandler
                             AND p.prosrc = 'kingres_columnar_handler'
                             AND p.probin LIKE '%kingres_columnar')
                  THEN 'columnar'
             ELSE 'other' END
      FROM pg_catalog.pg_am a
     WHERE a.amname = p_am AND a.amtype = 't'
$$;

-- Is the table, or its partition, one that another extension owns: a ledger
-- table (kingres_ledger) or a distributed table (kingres_shard)?  SECURITY
-- DEFINER because the catalogs of those extensions are private to them; it
-- decides nothing about the caller and returns a word, or null.  It answers
-- only about a table of the caller: the login role (session_user, which no
-- SQL changes without superuser rights) must be a superuser or have the
-- privileges of the owner of the table, so that a role cannot use it to ask
-- the private catalogs of the other extensions about any table.
CREATE FUNCTION kingres.timepart__special_table(p_parent oid, p_part oid)
RETURNS text
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_hit boolean;
BEGIN
    -- The second argument is the table or a partition of it: it is not a way
    -- to ask about a table of another role.
    IF p_part IS DISTINCT FROM p_parent
       AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_inherits i
                        WHERE i.inhparent = p_parent AND i.inhrelid = p_part) THEN
        RETURN NULL;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles r WHERE r.rolname = session_user AND r.rolsuper)
       AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_class c
                        WHERE c.oid = p_parent
                          AND pg_catalog.pg_has_role(session_user, c.relowner, 'USAGE')) THEN
        RAISE EXCEPTION 'permission denied: only the owner of the table or a superuser may ask'
            USING ERRCODE = '42501';
    END IF;
    IF pg_catalog.to_regclass('kingres.ledger_table') IS NOT NULL THEN
        EXECUTE 'SELECT EXISTS (SELECT 1 FROM kingres.ledger_table t WHERE t.relid::pg_catalog.oid IN ($1, $2))'
            INTO v_hit USING p_parent, p_part;
        IF v_hit THEN
            RETURN 'ledger';
        END IF;
    END IF;
    IF pg_catalog.to_regclass('kingres.dist_table') IS NOT NULL THEN
        EXECUTE 'SELECT EXISTS (SELECT 1 FROM kingres.dist_table t WHERE t.relid::pg_catalog.oid IN ($1, $2))'
            INTO v_hit USING p_parent, p_part;
        IF v_hit THEN
            RETURN 'distributed';
        END IF;
    END IF;
    RETURN NULL;
END;
$$;

-- The reason a partition cannot be converted to the access method p_target, or
-- null when it can (10.4 step 1).  Reads the catalogs only and changes
-- nothing; the first reason found is returned, as a sentence that names the
-- object.  The conversion copies the rows and drops the old partition, so
-- everything that would be lost with it, or that the new table cannot carry,
-- is a reason: the user's objects are never dropped silently.
CREATE FUNCTION kingres.timepart__convert_refusal(
    p_parent oid, p_part oid, p_target name, p_sort text[], p_options jsonb)
RETURNS text
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
SET DateStyle = 'ISO, MDY'
AS $$
DECLARE
    v_kind   text;
    v_cur    text;
    v_c      record;
    v_powner oid;
    v_pn     text := p_part::pg_catalog.regclass::text;
    v_parn   text := p_parent::pg_catalog.regclass::text;
    v_x      text;
    v_s      text;
    v_enf    boolean;
BEGIN
    v_kind := kingres.timepart__am_kind(p_target);
    IF v_kind IS NULL THEN
        RETURN format('"%s" is not a table access method', p_target);
    END IF;
    IF v_kind = 'other' THEN
        RETURN format('access method "%s" is not supported: convert to columnar or to heap', p_target);
    END IF;

    SELECT c.relkind, c.relpersistence, c.relowner, c.relhassubclass, c.relreplident,
           c.relrowsecurity, c.relnamespace, a.amname,
           pg_get_expr(c.relpartbound, c.oid) AS bound
      INTO v_c
      FROM pg_inherits i
      JOIN pg_class c ON c.oid = i.inhrelid
      LEFT JOIN pg_am a ON a.oid = c.relam
     WHERE i.inhparent = p_parent AND i.inhrelid = p_part;
    IF NOT FOUND THEN
        RETURN format('%s is not a partition of %s', v_pn, v_parn);
    END IF;
    IF v_c.relkind = 'p' THEN
        RETURN format('%s is a partitioned table: only leaf partitions are converted', v_pn);
    END IF;
    IF v_c.relkind <> 'r' THEN
        RETURN format('%s is not an ordinary table', v_pn);
    END IF;
    IF v_c.bound = 'DEFAULT' THEN
        RETURN format('%s is the default partition', v_pn);
    END IF;
    v_cur := kingres.timepart__am_kind(v_c.amname);
    IF v_cur = v_kind THEN
        RETURN format('%s is already stored with the access method "%s"', v_pn, v_c.amname);
    END IF;
    IF v_c.relreplident = 'i' THEN
        RETURN format('%s uses an index as its replica identity', v_pn);
    END IF;
    IF v_c.relpersistence <> 'p' THEN
        RETURN format('%s is a temporary or unlogged table', v_pn);
    END IF;
    -- The copy reads the partition after it has locked it; under REPEATABLE
    -- READ or SERIALIZABLE the snapshot of the transaction can be older than
    -- the lock, and a row committed in between would be left behind and
    -- dropped with the old partition.
    IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
        RETURN format('a conversion needs the transaction isolation level read committed, not %s',
                      pg_catalog.current_setting('transaction_isolation'));
    END IF;
    SELECT c.relowner INTO v_powner FROM pg_class c WHERE c.oid = p_parent;
    IF v_c.relowner <> v_powner THEN
        RETURN format('%s is owned by "%s", the table by "%s"; the owner of a partition must be the owner of the table',
                      v_pn, pg_get_userbyid(v_c.relowner), pg_get_userbyid(v_powner));
    END IF;
    v_x := kingres.timepart__special_table(p_parent, p_part);
    IF v_x = 'ledger' THEN
        RETURN format('%s belongs to a ledger table', v_pn);
    ELSIF v_x = 'distributed' THEN
        RETURN format('%s belongs to a distributed table, which this version does not convert', v_pn);
    END IF;

    -- What would be lost with the old partition.
    SELECT t.tgname INTO v_x FROM pg_trigger t
     WHERE t.tgrelid = p_part AND NOT t.tgisinternal AND t.tgparentid = 0
     ORDER BY t.tgname LIMIT 1;
    IF v_x IS NOT NULL THEN
        RETURN format('%s has the trigger "%s" of its own, which the copy would not carry', v_pn, v_x);
    END IF;
    SELECT r.rulename INTO v_x FROM pg_rewrite r
     WHERE r.ev_class = p_part AND r.rulename <> '_RETURN'
     ORDER BY r.rulename LIMIT 1;
    IF v_x IS NOT NULL THEN
        RETURN format('%s has the rule "%s"', v_pn, v_x);
    END IF;
    IF v_c.relrowsecurity OR EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid = p_part) THEN
        RETURN format('%s has row-level security', v_pn);
    END IF;
    SELECT pb.pubname INTO v_x FROM pg_publication_rel r
      JOIN pg_publication pb ON pb.oid = r.prpubid
     WHERE r.prrelid = p_part ORDER BY pb.pubname LIMIT 1;
    IF v_x IS NOT NULL THEN
        RETURN format('%s is in the publication "%s"', v_pn, v_x);
    END IF;
    SELECT string_agg(DISTINCT format('%I.%I', n.nspname, vc.relname), ', ') INTO v_x
      FROM pg_depend d
      JOIN pg_rewrite rw ON rw.oid = d.objid
      JOIN pg_class vc ON vc.oid = rw.ev_class
      JOIN pg_namespace n ON n.oid = vc.relnamespace
     WHERE d.classid = 'pg_rewrite'::pg_catalog.regclass
       AND d.refclassid = 'pg_class'::pg_catalog.regclass
       AND d.refobjid = p_part AND vc.oid <> p_part;
    IF v_x IS NOT NULL THEN
        RETURN format('%s is used by the view or rule of %s', v_pn, v_x);
    END IF;
    SELECT format('%I on %s', k.conname, k.conrelid::pg_catalog.regclass::text) INTO v_x
      FROM pg_constraint k
     WHERE k.contype = 'f' AND k.confrelid = p_part AND k.conparentid = 0
     ORDER BY k.conname LIMIT 1;
    IF v_x IS NOT NULL THEN
        RETURN format('%s is referenced by the foreign key %s', v_pn, v_x);
    END IF;
    SELECT format('%I', s.relname) INTO v_x
      FROM pg_depend d JOIN pg_class s ON s.oid = d.objid AND s.relkind = 'S'
     WHERE d.classid = 'pg_class'::pg_catalog.regclass AND d.refclassid = 'pg_class'::pg_catalog.regclass
       AND d.refobjid = p_part AND d.deptype = 'a'
     ORDER BY s.relname LIMIT 1;
    IF v_x IS NOT NULL THEN
        RETURN format('%s owns the sequence %s, which the drop of the old partition would remove', v_pn, v_x);
    END IF;
    SELECT format('%I', e.stxname) INTO v_x FROM pg_statistic_ext e
     WHERE e.stxrelid = p_part ORDER BY e.stxname LIMIT 1;
    IF v_x IS NOT NULL THEN
        RETURN format('%s has the extended statistics object %s', v_pn, v_x);
    END IF;
    SELECT a.attname INTO v_x FROM pg_attribute a
     WHERE a.attrelid = p_part AND a.attnum > 0 AND NOT a.attisdropped
       AND a.attidentity <> ''
     ORDER BY a.attnum LIMIT 1;
    IF v_x IS NOT NULL THEN
        RETURN format('%s has the identity column "%s"', v_pn, v_x);
    END IF;
    -- A constraint that is not validated would be made on the empty new table,
    -- where it is valid, and checked against every row of the copy.
    -- A check that is NOT ENFORCED (PostgreSQL 18 and later, the column
    -- conenforced) is not validated either, but the new table has it as it is,
    -- not enforced, and no row can fail on it: it is carried, not refused.  The
    -- column is looked for in the catalog, not decided by the version.
    SELECT EXISTS (SELECT 1 FROM pg_attribute a
                    WHERE a.attrelid = 'pg_catalog.pg_constraint'::pg_catalog.regclass
                      AND a.attname = 'conenforced' AND NOT a.attisdropped) INTO v_enf;
    IF v_enf THEN
        EXECUTE 'SELECT k.conname FROM pg_catalog.pg_constraint k '
                'WHERE k.conrelid = $1 AND NOT k.convalidated AND k.conenforced '
                'AND k.contype IN (''c'', ''n'') ORDER BY k.conname LIMIT 1'
            INTO v_x USING p_part;
    ELSE
        SELECT k.conname INTO v_x FROM pg_constraint k
         WHERE k.conrelid = p_part AND NOT k.convalidated AND k.contype IN ('c', 'n')
         ORDER BY k.conname LIMIT 1;
    END IF;
    IF v_x IS NOT NULL THEN
        RETURN format('%s has the constraint "%s" that is not validated (NOT VALID): the new table would have it validated, and a row that violates it would fail the copy', v_pn, v_x);
    END IF;
    -- A privilege that another role than the owner granted (a role with GRANT
    -- OPTION that passed it on) would be granted by the owner on the new table.
    SELECT format('%s granted to %s by "%s"', x.privilege_type,
                  CASE WHEN x.grantee = 0 THEN 'PUBLIC' ELSE '"' || pg_get_userbyid(x.grantee) || '"' END,
                  pg_get_userbyid(x.grantor)) INTO v_x
      FROM pg_class c, LATERAL aclexplode(c.relacl) x
     WHERE c.oid = p_part AND x.grantor <> c.relowner
     ORDER BY x.grantor, x.grantee, x.privilege_type LIMIT 1;
    IF v_x IS NULL THEN
        SELECT format('%s (%s) granted to %s by "%s"', x.privilege_type, a.attname,
                      CASE WHEN x.grantee = 0 THEN 'PUBLIC' ELSE '"' || pg_get_userbyid(x.grantee) || '"' END,
                      pg_get_userbyid(x.grantor)) INTO v_x
          FROM pg_attribute a, LATERAL aclexplode(a.attacl) x
         WHERE a.attrelid = p_part AND a.attnum > 0 AND NOT a.attisdropped
           AND x.grantor <> v_c.relowner
         ORDER BY a.attnum, x.grantor, x.grantee, x.privilege_type LIMIT 1;
    END IF;
    IF v_x IS NOT NULL THEN
        RETURN format('%s has a privilege that the owner did not grant (%s): the new table would have the owner as the grantor', v_pn, v_x);
    END IF;
    -- Objects that depend on the partition, or on its row type, without
    -- being a view, a rule, a foreign key or an owned sequence (found above):
    -- a function with the row type as an argument, an SQL function that reads
    -- it, a policy of another table, a default that names it.  DROP TABLE
    -- would fail on the first of them after the whole copy.
    SELECT pg_describe_object(d.classid, d.objid, d.objsubid) INTO v_x
      FROM pg_depend d
     WHERE d.deptype = 'n'
       AND ((d.refclassid = 'pg_class'::pg_catalog.regclass AND d.refobjid = p_part)
            OR (d.refclassid = 'pg_type'::pg_catalog.regclass
                AND d.refobjid IN (SELECT t.oid FROM pg_type t
                                    WHERE t.typrelid = p_part
                                       OR t.oid = (SELECT t2.typarray FROM pg_type t2
                                                    WHERE t2.typrelid = p_part))))
       AND NOT (d.classid = 'pg_class'::pg_catalog.regclass AND d.objid = p_part)
       -- the partition's own objects that name its columns (the expression of
       -- a generated column, a constraint, a trigger, a policy, an index)
       AND NOT (d.classid = 'pg_attrdef'::pg_catalog.regclass
                AND EXISTS (SELECT 1 FROM pg_attrdef ad WHERE ad.oid = d.objid AND ad.adrelid = p_part))
       AND NOT (d.classid = 'pg_constraint'::pg_catalog.regclass
                AND EXISTS (SELECT 1 FROM pg_constraint k WHERE k.oid = d.objid AND k.conrelid = p_part))
       AND NOT (d.classid = 'pg_trigger'::pg_catalog.regclass
                AND EXISTS (SELECT 1 FROM pg_trigger t WHERE t.oid = d.objid AND t.tgrelid = p_part))
       AND NOT (d.classid = 'pg_policy'::pg_catalog.regclass
                AND EXISTS (SELECT 1 FROM pg_policy po WHERE po.oid = d.objid AND po.polrelid = p_part))
       AND NOT (d.classid = 'pg_class'::pg_catalog.regclass
                AND EXISTS (SELECT 1 FROM pg_index i WHERE i.indexrelid = d.objid AND i.indrelid = p_part))
     ORDER BY d.classid, d.objid, d.objsubid LIMIT 1;
    IF v_x IS NOT NULL THEN
        RETURN format('%s is used by %s, which the drop of the old partition would stop', v_pn, v_x);
    END IF;
    -- The attach scans the default partition, under ACCESS EXCLUSIVE on the
    -- table, for rows of the new range: refuse when it is large.
    -- A default partition that is itself partitioned has no storage of its
    -- own: the size is that of its leaves (table, TOAST table, free space and
    -- visibility maps; the indexes are not read by the attach).
    SELECT format('%s of %s', d.oid::pg_catalog.regclass::text,
                  pg_size_pretty(s.bytes)) INTO v_x
      FROM pg_inherits i JOIN pg_class d ON d.oid = i.inhrelid,
           LATERAL (SELECT coalesce(sum(pg_table_size(t.relid)), 0)::bigint AS bytes
                      FROM pg_partition_tree(d.oid) t WHERE t.isleaf) s
     WHERE i.inhparent = p_parent AND d.oid <> p_part
       AND pg_get_expr(d.relpartbound, d.oid) = 'DEFAULT'
       AND s.bytes > kingres.timepart__setting_int(
               'kingres_timepart.convert_default_max_mb', 256, 0, 1048576)::bigint * 1048576;
    IF v_x IS NOT NULL THEN
        RETURN format('the default partition %s of %s would be scanned by the attach under ACCESS EXCLUSIVE on the table (kingres_timepart.convert_default_max_mb is %s)',
                      v_x, v_parn,
                      kingres.timepart__setting_int('kingres_timepart.convert_default_max_mb', 256, 0, 1048576));
    END IF;
    -- A publication of all tables or of the schema takes in the new table, which
    -- the copy fills under its temporary name (a publication of the partition
    -- itself was refused above; for columnar every publication is refused below).
    IF v_kind = 'heap' THEN
        SELECT pb.pubname INTO v_x FROM pg_publication pb
         WHERE pb.puballtables
            OR EXISTS (SELECT 1 FROM pg_publication_namespace pn
                        WHERE pn.pnpubid = pb.oid AND pn.pnnspid = v_c.relnamespace)
         ORDER BY pb.pubname LIMIT 1;
        IF v_x IS NOT NULL THEN
            RETURN format('the publication "%s" would publish every row of the copy under the temporary name of the new table', v_x);
        END IF;
    END IF;

    IF v_kind = 'columnar' THEN
        -- What a columnar table cannot have (kingres_columnar README, "What
        -- is refused"), found before the attach would fail on it.
        -- Indexes: a B-tree with immediate checking can be on a columnar
        -- table (kingres_columnar 0.2: plain, multi-column, expression,
        -- partial, INCLUDE, DESC, NULLS FIRST, unique, primary key, unique
        -- constraint); the parent's indexes are looked at first, then the
        -- partition's own.
        FOR v_s IN SELECT unnest(ARRAY[p_parent, p_part])::text LOOP
            SELECT format('%s (%s)', i.indexrelid::pg_catalog.regclass::text,
                          CASE WHEN am.amname <> 'btree'
                                    THEN 'access method ' || am.amname || ': columnar tables have B-tree indexes only'
                               WHEN i.indisexclusion
                                    THEN 'an exclusion constraint: columnar tables cannot have one'
                               WHEN NOT i.indimmediate
                                    THEN 'deferrable: a columnar table checks a unique key when the row goes in'
                               ELSE 'not valid: it is not complete' END)
              INTO v_x
              FROM pg_index i
              JOIN pg_class ic ON ic.oid = i.indexrelid
              JOIN pg_am am ON am.oid = ic.relam
             WHERE i.indrelid = v_s::pg_catalog.oid
               AND (am.amname <> 'btree' OR i.indisexclusion OR NOT i.indimmediate
                    OR NOT i.indisvalid OR NOT i.indisready)
             ORDER BY i.indexrelid LIMIT 1;
            IF v_x IS NOT NULL THEN
                RETURN format('%s has the index %s', v_s::pg_catalog.oid::pg_catalog.regclass::text, v_x);
            END IF;
        END LOOP;
        IF EXISTS (SELECT 1 FROM pg_index i WHERE i.indrelid IN (p_parent, p_part)) THEN
            -- A new table made by an extension still at 0.1 is of file format
            -- 2, which cannot have an index.
            SELECT e.extversion INTO v_x FROM pg_extension e WHERE e.extname = 'kingres_columnar';
            IF string_to_array(coalesce(v_x, '0.1'), '.')::int[] < ARRAY[0, 2] THEN
                RETURN format('the table has indexes and the new partition would be made by kingres_columnar %s (file format 2, written by 0.1), which cannot have an index: run ALTER EXTENSION kingres_columnar UPDATE', coalesce(v_x, '0.1'));
            END IF;
        END IF;
        SELECT format('%I on %s', k.conname, k.conrelid::pg_catalog.regclass::text) INTO v_x
          FROM pg_constraint k
         WHERE k.contype = 'f'
           AND (k.conrelid IN (p_part, p_parent) OR k.confrelid IN (p_part, p_parent))
         ORDER BY k.conparentid <> 0, k.conname LIMIT 1;
        IF v_x IS NOT NULL THEN
            RETURN format('the foreign key %s concerns %s or %s: columnar tables have no foreign keys', v_x, v_pn, v_parn);
        END IF;
        SELECT format('"%s" on %s', t.tgname, t.tgrelid::pg_catalog.regclass::text) INTO v_x
          FROM pg_trigger t
         WHERE t.tgrelid IN (p_part, p_parent) AND NOT t.tgisinternal
           AND (t.tgtype & 1) <> 0 AND (t.tgtype & 2) = 0 AND (t.tgtype & 64) = 0
         ORDER BY t.tgparentid <> 0, t.tgname LIMIT 1;
        IF v_x IS NOT NULL THEN
            RETURN format('the AFTER ROW trigger %s cannot be on a columnar table', v_x);
        END IF;
        SELECT pb.pubname INTO v_x FROM pg_publication pb
         WHERE pb.puballtables
            OR EXISTS (SELECT 1 FROM pg_publication_rel r
                        WHERE r.prpubid = pb.oid AND r.prrelid = p_parent)
            OR EXISTS (SELECT 1 FROM pg_publication_namespace pn
                        WHERE pn.pnpubid = pb.oid AND pn.pnnspid = v_c.relnamespace)
         ORDER BY pb.pubname LIMIT 1;
        IF v_x IS NOT NULL THEN
            RETURN format('the publication "%s" would include the columnar partition: columnar tables are not replicated logically yet', v_x);
        END IF;
    END IF;

    -- What the copy reads and sorts by.
    IF NOT EXISTS (SELECT 1 FROM pg_attribute a
                    WHERE a.attrelid = p_part AND a.attnum > 0
                      AND NOT a.attisdropped AND a.attgenerated = '') THEN
        RETURN format('%s has no column that can be copied', v_pn);
    END IF;
    IF p_sort IS NOT NULL THEN
        IF cardinality(p_sort) = 0 THEN
            RETURN 'sort_by must name at least one column';
        END IF;
        FOREACH v_s IN ARRAY p_sort LOOP
            IF v_s IS NULL OR NOT EXISTS (
                   SELECT 1 FROM pg_attribute a
                    WHERE a.attrelid = p_part AND a.attname = v_s
                      AND a.attnum > 0 AND NOT a.attisdropped) THEN
                RETURN format('the sort column "%s" is not a column of %s', coalesce(v_s, 'NULL'), v_pn);
            END IF;
        END LOOP;
    END IF;
    IF p_options IS NOT NULL THEN
        IF v_kind <> 'columnar' THEN
            RETURN 'options apply to columnar tables only';
        END IF;
        BEGIN
            PERFORM kingres.timepart__columnar_options(p_options);
        EXCEPTION WHEN invalid_parameter_value THEN
            RETURN SQLERRM;
        END;
    END IF;
    RETURN NULL;
END;
$$;

-- What the partition carries that a change does not need a lock on the table
-- for, as one document: the privileges (table and column level), and, of every
-- index, the name, the tablespace, the storage parameters, the comment, the
-- clustering mark, the name and the comment of its constraint and the statistics
-- targets of its columns, and the comment, options and tablespace of the table.
-- GRANT, REVOKE, ALTER INDEX ... RENAME, COMMENT ON INDEX and ALTER INDEX ... SET
-- take no lock that the SHARE ROW EXCLUSIVE lock of the conversion keeps out, so
-- they can commit while the copy runs, or while the swap waits for its lock; the
-- block that converts reads this document when it has locked the partition and
-- again, with the parent locked, just before it detaches the partition, and
-- gives way (schema_changed) when the two differ, instead of dropping the
-- change with the old partition.  VOLATILE on purpose, SECURITY INVOKER: it
-- reads the catalogs as the caller.
CREATE FUNCTION kingres.timepart__convert_fp(p_part oid)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_tbl  jsonb;
    v_cols jsonb;
    v_ix   jsonb;
BEGIN
    SELECT jsonb_build_object('acl', c.relacl::text, 'owner', c.relowner,
                              'tblspc', c.reltablespace, 'opts', c.reloptions::text,
                              'ident', c.relreplident::text,
                              'desc', obj_description(c.oid, 'pg_class'))
      INTO v_tbl FROM pg_class c WHERE c.oid = p_part;
    SELECT coalesce(jsonb_agg(jsonb_build_array(a.attnum, a.attname::text, a.attacl::text,
                                                a.attstattarget, a.attoptions::text)
                              ORDER BY a.attnum), '[]')
      INTO v_cols
      FROM pg_attribute a
     WHERE a.attrelid = p_part AND a.attnum > 0 AND NOT a.attisdropped;
    SELECT coalesce(jsonb_agg(jsonb_build_array(
                        ic.relname::text, ic.reltablespace, ic.reloptions::text,
                        obj_description(ic.oid, 'pg_class'), i.indisclustered,
                        k.conname::text, obj_description(k.oid, 'pg_constraint'),
                        (SELECT jsonb_agg(jsonb_build_array(a.attnum, a.attstattarget) ORDER BY a.attnum)
                           FROM pg_attribute a WHERE a.attrelid = ic.oid AND a.attnum > 0))
                    ORDER BY ic.oid), '[]')
      INTO v_ix
      FROM pg_index i
      JOIN pg_class ic ON ic.oid = i.indexrelid
      LEFT JOIN pg_constraint k ON k.conindid = i.indexrelid AND k.conrelid = p_part
                               AND k.contype IN ('p', 'u')
     WHERE i.indrelid = p_part;
    RETURN jsonb_build_object('table', v_tbl, 'columns', v_cols, 'indexes', v_ix);
END;
$$;

-- What the conversion reads from the catalog, as one document: the checks of
-- timepart__convert_refusal, the names, the bound, the column list of the copy,
-- the sort, the tablespace and the statements for the indexes.  Called twice by
-- every conversion: by timepart__convert_stmts, before any lock, to refuse
-- early; and by the block that those statements make, right after it holds its
-- lock on the partition, whose result is the one it uses.  The first reading can
-- be stale by the time the lock is granted (a session that held a lock on the
-- partition may have added a column, an index or a constraint, or dropped one,
-- before it committed), so nothing read before the lock is used to copy rows or
-- to make an index.  VOLATILE on purpose: every statement of it takes a new
-- snapshot.  SECURITY INVOKER: it reads the catalogs only, as the caller.
--
-- The result has the keys schema, old (the name of the partition), new (the
-- temporary name of the new table), part, newq and parent (the qualified,
-- quoted names), cols, order, bound_cl, bound, check, tblspc, ix (an array
-- of the statements and names for the indexes) and fp (timepart__convert_fp).
CREATE FUNCTION kingres.timepart__convert_plan(
    p_parent oid, p_part oid, p_target name, p_sort text[], p_options jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
SET DateStyle = 'ISO, MDY'
AS $$
DECLARE
    v_info    record;
    v_reason  text;
    v_kind    text;
    v_c       record;
    v_pname   name;
    v_base    text;
    v_tmp     text;
    v_schema  name;
    v_m       text[];
    v_lit     text;
    v_parts   text[] := '{}';
    v_side    text[] := ARRAY['', ''];
    v_bound   text;
    v_bound_cl text := '';
    v_check   text := 'timepart_convert_bound';
    v_cols    text;
    v_order   text := '';
    v_tblspc  text := '';
    v_ix      jsonb := '[]';
    v_ixr     record;
    v_ixn     integer := 0;
    v_ixtmp   text;
    v_ixpre   text;
    v_ixstmt  text;
    v_ixspc   text;
    v_stats   jsonb;
    i         integer;
BEGIN
    SELECT * INTO v_info FROM kingres.timepart__key_info(p_parent);
    PERFORM kingres.timepart__require_owner(
        current_user, v_info.r_owner_oid,
        format('%I.%I', v_info.r_schema, v_info.r_table));
    v_reason := kingres.timepart__convert_refusal(
        p_parent, p_part, p_target, p_sort, p_options);
    IF v_reason IS NOT NULL THEN
        RAISE EXCEPTION 'conversion_refused: %', v_reason
            USING ERRCODE = '0A000';
    END IF;
    v_kind := kingres.timepart__am_kind(p_target);

    SELECT n.nspname, c.relname, pg_get_expr(c.relpartbound, c.oid) AS bound,
           c.reltablespace INTO v_c
      FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE c.oid = p_part;
    v_schema := v_c.nspname;
    v_pname := v_c.relname;

    -- The name of the new table: the old name and "__kc", cut to fit.
    v_base := v_pname;
    WHILE octet_length(v_base) > 59 LOOP
        v_base := left(v_base, char_length(v_base) - 1);
    END LOOP;
    v_tmp := v_base || '__kc';
    IF kingres.timepart__oid(v_schema, v_tmp::name) IS NOT NULL THEN
        RAISE EXCEPTION 'name_conflict: relation %.% already exists and is not the expected partition of %.%',
            quote_ident(v_schema), quote_ident(v_tmp),
            quote_ident(v_info.r_schema), quote_ident(v_info.r_table)
            USING ERRCODE = '42P07';
    END IF;

    -- The bound of the partition, as literals; the check of the new table is
    -- made from them.  (MINVALUE and MAXVALUE leave their side unchecked.)
    v_m := regexp_match(v_c.bound, '^FOR VALUES FROM \((.*)\) TO \((.*)\)$');
    IF v_m IS NULL THEN
        RAISE EXCEPTION 'conversion_refused: cannot read the bound of %: %',
            p_part::pg_catalog.regclass::text, v_c.bound USING ERRCODE = '0A000';
    END IF;
    FOR i IN 1..2 LOOP
        IF v_m[i] IN ('MINVALUE', 'MAXVALUE') THEN
            v_side[i] := v_m[i];
        ELSE
            v_lit := (regexp_match(v_m[i], '^''([^'']*)''$'))[1];
            IF v_lit IS NULL THEN
                RAISE EXCEPTION 'conversion_refused: cannot read the bound of %: %',
                    p_part::pg_catalog.regclass::text, v_c.bound USING ERRCODE = '0A000';
            END IF;
            v_side[i] := quote_literal(v_lit);
            v_parts := v_parts || CASE WHEN i = 1
                THEN format('%I >= %s', v_info.r_keycol, v_side[i])
                ELSE format('%I < %s', v_info.r_keycol, v_side[i]) END;
        END IF;
    END LOOP;
    v_bound := format('FOR VALUES FROM (%s) TO (%s)', v_side[1], v_side[2]);
    IF cardinality(v_parts) > 0 THEN
        v_bound_cl := format(', CONSTRAINT %I CHECK (%s)', v_check,
                             array_to_string(v_parts, ' AND '));
    END IF;

    SELECT string_agg(quote_ident(a.attname), ', ' ORDER BY a.attnum) INTO v_cols
      FROM pg_attribute a
     WHERE a.attrelid = p_part AND a.attnum > 0 AND NOT a.attisdropped
       AND a.attgenerated = '';
    IF p_sort IS NOT NULL THEN
        SELECT ' ORDER BY ' || string_agg(quote_ident(s.x), ', ' ORDER BY s.n) INTO v_order
          FROM unnest(p_sort) WITH ORDINALITY s(x, n);
    ELSIF v_kind = 'columnar' THEN
        v_order := ' ORDER BY ' || quote_ident(v_info.r_keycol);
    END IF;
    IF v_c.reltablespace <> 0 THEN
        SELECT ' TABLESPACE ' || quote_ident(t.spcname) INTO v_tblspc
          FROM pg_tablespace t WHERE t.oid = v_c.reltablespace;
    END IF;
    -- The indexes of the partition, as statements for the new table.  The
    -- temporary names are made from a digest of the name of the partition and a
    -- counter, so that they are short whatever the name of the partition is (a
    -- name cut to 63 bytes could make two of them equal), and the same every time.
    FOR v_ixr IN
        SELECT i.indexrelid, ic.relname AS iname, i.indisunique, i.indisclustered,
               k.oid AS conoid, k.conname, ic.reltablespace AS ixspc,
               pg_get_indexdef(i.indexrelid) AS d,
               obj_description(i.indexrelid, 'pg_class') AS idesc,
               obj_description(k.oid, 'pg_constraint') AS cdesc
          FROM pg_index i
          JOIN pg_class ic ON ic.oid = i.indexrelid
          LEFT JOIN pg_constraint k ON k.conindid = i.indexrelid AND k.conrelid = p_part
                                   AND k.contype IN ('p', 'u')
         WHERE i.indrelid = p_part
         ORDER BY i.indexrelid
    LOOP
        v_ixn := v_ixn + 1;
        v_ixtmp := 'kc_' || substr(md5(v_pname), 1, 12) || '_' || v_ixn;
        IF kingres.timepart__oid(v_schema, v_ixtmp::name) IS NOT NULL THEN
            RAISE EXCEPTION 'name_conflict: relation %.% already exists',
                quote_ident(v_schema), quote_ident(v_ixtmp) USING ERRCODE = '42P07';
        END IF;
        IF v_ixr.conoid IS NULL THEN
            v_ixpre := 'CREATE ' || CASE WHEN v_ixr.indisunique THEN 'UNIQUE ' ELSE '' END
                       || 'INDEX ' || quote_ident(v_ixr.iname) || ' ON '
                       || format('%I.%I', v_schema, v_pname) || ' USING ';
            IF left(v_ixr.d, length(v_ixpre)) <> v_ixpre THEN
                RAISE EXCEPTION 'conversion_refused: cannot read the definition of the index %: %',
                    quote_ident(v_ixr.iname), v_ixr.d USING ERRCODE = '0A000';
            END IF;
            v_ixstmt := 'CREATE ' || CASE WHEN v_ixr.indisunique THEN 'UNIQUE ' ELSE '' END
                        || 'INDEX ' || quote_ident(v_ixtmp) || ' ON '
                        || format('%I.%I', v_schema, v_tmp) || ' USING '
                        || substr(v_ixr.d, length(v_ixpre) + 1);
        ELSE
            v_ixstmt := 'ALTER TABLE ' || format('%I.%I', v_schema, v_tmp) || ' ADD CONSTRAINT '
                        || quote_ident(v_ixtmp) || ' ' || pg_get_constraintdef(v_ixr.conoid);
        END IF;
        -- the statistics targets of the index columns (set on expressions only)
        SELECT coalesce(jsonb_agg(jsonb_build_object('n', a.attnum, 't', a.attstattarget)
                                  ORDER BY a.attnum), '[]')
          INTO v_stats
          FROM pg_attribute a
         WHERE a.attrelid = v_ixr.indexrelid AND a.attnum > 0
           AND a.attstattarget IS NOT NULL AND a.attstattarget <> -1;
        -- the tablespace of a plain index (the definition of a constraint
        -- names its own, but pg_get_indexdef does not); the statement is run
        -- with default_tablespace set to it
        v_ixspc := NULL;
        IF v_ixr.conoid IS NULL AND v_ixr.ixspc <> 0 THEN
            SELECT t.spcname INTO v_ixspc FROM pg_tablespace t WHERE t.oid = v_ixr.ixspc;
        END IF;
        v_ix := v_ix || jsonb_build_array(jsonb_build_object(
            'create', v_ixstmt, 'tmp', v_ixtmp, 'name', v_ixr.iname, 'con', v_ixr.conname,
            'spc', v_ixspc,
            'idesc', v_ixr.idesc, 'cdesc', v_ixr.cdesc,
            'cluster', v_ixr.indisclustered, 'stats', v_stats));
    END LOOP;
    RETURN jsonb_build_object(
        'schema', v_schema, 'old', v_pname, 'new', v_tmp,
        'part', format('%I.%I', v_schema, v_pname),
        'newq', format('%I.%I', v_schema, v_tmp),
        'parent', format('%I.%I', v_info.r_schema, v_info.r_table),
        'cols', v_cols, 'order', v_order, 'bound_cl', v_bound_cl,
        'bound', v_bound, 'check', v_check, 'tblspc', v_tblspc, 'ix', v_ix,
        'fp', kingres.timepart__convert_fp(p_part));
END;
$$;

-- The statements that replace one partition by a copy in another access method
-- (10.4, "Convert one partition"): after the checks, one DO statement that
-- the caller executes as the owner of the table (timepart__exec_direct or
-- timepart__exec_as), so that the whole conversion is one transaction of the
-- caller and the owner's privileges apply to all of it.  The block holds the
-- OIDs of the table and the partition and the caller's arguments, and no name:
-- the names, the columns, the indexes and everything else that the catalog
-- says come from timepart__convert_plan, read again after the lock.  What it
-- does, in order:
--
--   1. SHARE ROW EXCLUSIVE on the partition: its writers wait, its readers go
--      on (the design says SHARE; this mode also keeps out a plain CREATE
--      INDEX, which SHARE lets in, and a second conversion).  Then the plan
--      and the checks again, now that nothing can change on the partition.
--   2. A new table next to it (LIKE the partition, with the check of the
--      bound in its definition so that the attach below scans nothing), in
--      the new access method, with the options, comment, tablespace, replica
--      identity and column statistics targets and options of the old one.
--   3. The copy: the columns named one by one, ordered by sort_by (the
--      partition column by default for columnar).
--   4. The check: the two tables have the same number of rows, or the block
--      fails with verification_failed and nothing has happened.
--   5. The privileges of the old partition on the new one.
--   5b. The indexes of the old partition (every index: the parent's, matched
--      by the attach below, and the partition's own), made on the new table
--      with plain CREATE INDEX or ADD CONSTRAINT after the load, under
--      temporary names; the old names are given to them after the old
--      partition is dropped.  The attach finds an equal index for each index
--      of the parent and builds nothing under the strong lock.  A duplicate
--      found by a unique index fails the conversion with the server's message.
--      Then the storage parameters of the table, after the load: they apply to
--      what is written next, and parallel_workers would send a columnar table
--      into a parallel build of rows that are not written yet.
--   6. The swap: no wait at all if a session that holds the parent waits for
--      the partition (a cycle); else a short wait (the smaller of 500 ms and
--      half of deadlock_timeout) for ACCESS EXCLUSIVE on the parent, then detach,
--      attach, drop, rename and drop of the helper check; then the enabled
--      state of the cloned triggers, the clustering index and the statistics
--      targets of the indexes.  If the lock is not granted in time the block
--      fails with swap_lock_timeout and the copy is rolled back with
--      everything else.
CREATE FUNCTION kingres.timepart__convert_stmts(
    p_parent oid, p_part oid, p_target name, p_sort text[], p_options jsonb)
RETURNS text[]
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
SET DateStyle = 'ISO, MDY'
AS $$
DECLARE
    v_plan    jsonb;
    v_kind    text;
    v_opts    record;
    v_swap    integer;
    v_dl      integer;
    v_body    text;
BEGIN
    -- The checks and the plan, before any lock: a refusal is raised here, with
    -- nothing locked.  The block reads them again under its lock.
    v_plan := kingres.timepart__convert_plan(p_parent, p_part, p_target, p_sort, p_options);
    v_kind := kingres.timepart__am_kind(p_target);
    IF v_kind = 'columnar' THEN
        SELECT * INTO v_opts FROM kingres.timepart__columnar_options(p_options);
    ELSE
        SELECT NULL::text AS o_compression, NULL::integer AS o_level,
               NULL::integer AS o_stripe, NULL::integer AS o_chunk INTO v_opts;
    END IF;
    -- A writer of the partition holds the parent in ROW EXCLUSIVE while it
    -- waits for our lock on the partition, and we wait for the parent: a
    -- cycle that only a timeout breaks.  The wait is below the deadlock
    -- timeout, so the conversion gives way, not the user's statement.
    SELECT s.setting::integer INTO v_dl FROM pg_settings s WHERE s.name = 'deadlock_timeout';
    v_swap := greatest(1, least(500, coalesce(v_dl, 1000) / 2));

    v_body := format($tpl$
DECLARE
    v_am       text := %1$L;
    v_sort     text[] := %2$L;
    v_options  jsonb := %3$L;
    v_o_comp   text := %4$L;
    v_o_level  integer := %5$L;
    v_o_stripe integer := %6$L;
    v_o_chunk  integer := %7$L;
    v_swap     integer := %8$s;
    v_columnar boolean := %9$s;
    v_part_oid oid := %10$s;
    v_parent_oid oid := %11$s;
    v_prev_lt  text := pg_catalog.current_setting('lock_timeout');
    v_plan     jsonb;
    v_parent   text;
    v_part     text;
    v_new      text;
    v_schema   text;
    v_old_name text;
    v_cols     text;
    v_order    text;
    v_bound_cl text;
    v_bound    text;
    v_check    text;
    v_tblspc   text;
    v_ix       jsonb;
    v_fp       jsonb;
    v_dts      text := pg_catalog.current_setting('default_tablespace');
    v_trg      jsonb;
    v_final    text;
    v_owner    oid;
    v_old_cnt  bigint;
    v_new_cnt  bigint;
    v_text     text;
    v_k        text;
    v_v        text;
    v_ident    "char";
    i          integer;
    r          record;
BEGIN
    -- a partition that is gone: the cast of its OID to a name would give the
    -- digits, and LOCK TABLE of them is a syntax error
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_class c WHERE c.oid = v_part_oid) THEN
        RAISE EXCEPTION 'schema_changed: the partition with OID %% was dropped before the conversion could lock it; the next run tries again',
            v_part_oid USING ERRCODE = '55P03';
    END IF;
    BEGIN
        EXECUTE 'LOCK TABLE ' || v_part_oid::pg_catalog.regclass::pg_catalog.text
             || ' IN SHARE ROW EXCLUSIVE MODE';
    EXCEPTION WHEN undefined_table OR syntax_error THEN
        RAISE EXCEPTION 'schema_changed: the partition with OID %% was renamed or dropped while the conversion waited for its lock; the next run tries again',
            v_part_oid USING ERRCODE = '55P03';
    END;
    -- the lock that is held is the one on the partition, not on a table that
    -- took its name while this statement waited
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_locks l
                    WHERE l.pid = pg_catalog.pg_backend_pid() AND l.locktype = 'relation'
                      AND l.database = (SELECT d.oid FROM pg_catalog.pg_database d WHERE d.datname = pg_catalog.current_database())
                      AND l.relation = v_part_oid AND l.mode = 'ShareRowExclusiveLock' AND l.granted) THEN
        RAISE EXCEPTION 'schema_changed: the partition with OID %% was renamed or dropped while the conversion waited for its lock, and its name is another table now; the next run tries again',
            v_part_oid USING ERRCODE = '55P03';
    END IF;
    -- everything the catalog says about the partition, now that nothing can
    -- change on it; a refusal or an error here is raised as it would be above
    v_plan := kingres.timepart__convert_plan(v_parent_oid, v_part_oid, v_am::pg_catalog.name, v_sort, v_options);
    v_parent   := v_plan ->> 'parent';
    v_part     := v_plan ->> 'part';
    v_new      := v_plan ->> 'newq';
    v_schema   := v_plan ->> 'schema';
    v_old_name := v_plan ->> 'old';
    v_cols     := v_plan ->> 'cols';
    v_order    := v_plan ->> 'order';
    v_bound_cl := v_plan ->> 'bound_cl';
    v_bound    := v_plan ->> 'bound';
    v_check    := v_plan ->> 'check';
    v_tblspc   := v_plan ->> 'tblspc';
    v_ix       := v_plan -> 'ix';
    v_fp       := v_plan -> 'fp';

    EXECUTE 'CREATE TABLE ' || v_new || ' (LIKE ' || v_part
         || ' INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING COMMENTS'
         || ' INCLUDING STORAGE INCLUDING GENERATED INCLUDING COMPRESSION'
         || v_bound_cl || ') USING ' || pg_catalog.quote_ident(v_am) || v_tblspc;
    IF v_columnar AND (v_o_comp IS NOT NULL OR v_o_level IS NOT NULL
                       OR v_o_stripe IS NOT NULL OR v_o_chunk IS NOT NULL) THEN
        PERFORM kingres.columnar_set_options(v_new::pg_catalog.regclass, v_o_comp,
                                             v_o_level, v_o_stripe, v_o_chunk);
    END IF;
    SELECT d.description INTO v_text FROM pg_catalog.pg_description d
     WHERE d.classoid = 'pg_catalog.pg_class'::pg_catalog.regclass
       AND d.objoid = v_part_oid AND d.objsubid = 0;
    IF FOUND THEN
        EXECUTE 'COMMENT ON TABLE ' || v_new || ' IS ' || pg_catalog.quote_literal(v_text);
    END IF;
    SELECT c.relreplident, c.relowner INTO v_ident, v_owner
      FROM pg_catalog.pg_class c WHERE c.oid = v_part_oid;
    IF v_ident = 'f' THEN
        EXECUTE 'ALTER TABLE ' || v_new || ' REPLICA IDENTITY FULL';
    ELSIF v_ident = 'n' THEN
        EXECUTE 'ALTER TABLE ' || v_new || ' REPLICA IDENTITY NOTHING';
    END IF;
    -- The statistics target and the options of each column, which LIKE does not
    -- carry (the storage parameters of the table follow the indexes, below).
    FOR r IN SELECT a.attname, a.attstattarget, a.attoptions
               FROM pg_catalog.pg_attribute a
              WHERE a.attrelid = v_part_oid AND a.attnum > 0 AND NOT a.attisdropped
              ORDER BY a.attnum
    LOOP
        IF r.attstattarget IS NOT NULL AND r.attstattarget <> -1 THEN
            BEGIN
                EXECUTE 'ALTER TABLE ' || v_new || ' ALTER COLUMN ' || pg_catalog.quote_ident(r.attname)
                     || ' SET STATISTICS ' || r.attstattarget::pg_catalog.text;
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'the statistics target of the column %% of %% was not carried to the new table: %%',
                    r.attname, v_part, SQLERRM;
            END;
        END IF;
        IF r.attoptions IS NOT NULL THEN
            FOR i IN 1 .. pg_catalog.array_length(r.attoptions, 1) LOOP
                v_k := pg_catalog.split_part(r.attoptions[i], '=', 1);
                v_v := pg_catalog.substr(r.attoptions[i], pg_catalog.strpos(r.attoptions[i], '=') + 1);
                -- the version stamp of the column is the server's own, and
                -- the new column has its own
                CONTINUE WHEN v_k = 'pg_attver';
                BEGIN
                    EXECUTE 'ALTER TABLE ' || v_new || ' ALTER COLUMN ' || pg_catalog.quote_ident(r.attname)
                         || ' SET (' || pg_catalog.quote_ident(v_k) || ' = ' || pg_catalog.quote_literal(v_v) || ')';
                EXCEPTION WHEN OTHERS THEN
                    RAISE WARNING 'the option %% of the column %% of %% was not carried to the new table: %%',
                        r.attoptions[i], r.attname, v_part, SQLERRM;
                END;
            END LOOP;
        END IF;
    END LOOP;

    EXECUTE 'INSERT INTO ' || v_new || ' (' || v_cols || ') SELECT ' || v_cols
         || ' FROM ' || v_part || v_order;

    EXECUTE 'SELECT pg_catalog.count(*) FROM ' || v_part INTO v_old_cnt;
    EXECUTE 'SELECT pg_catalog.count(*) FROM ' || v_new INTO v_new_cnt;
    IF v_old_cnt IS DISTINCT FROM v_new_cnt THEN
        RAISE EXCEPTION 'verification_failed: %% has %% rows, its copy has %%',
            v_part, v_old_cnt, v_new_cnt USING ERRCODE = 'KT001';
    END IF;

    -- the indexes, after the load, with plain CREATE INDEX (under the lock of
    -- the partition, so the rows cannot change); a duplicate fails here
    FOR r IN SELECT x ->> 'create' AS stmt, x ->> 'spc' AS spc
               FROM pg_catalog.jsonb_array_elements(v_ix) WITH ORDINALITY t(x, n) ORDER BY n
    LOOP
        PERFORM pg_catalog.set_config('default_tablespace', coalesce(r.spc, v_dts), true);
        EXECUTE r.stmt;
    END LOOP;
    PERFORM pg_catalog.set_config('default_tablespace', v_dts, true);

    -- The storage parameters of the table (and of its TOAST table), which LIKE
    -- does not carry, after the load and the indexes: parallel_workers would
    -- have a columnar table refuse a parallel index build of rows that the
    -- transaction has not written yet.  The target access method may not
    -- accept one of them: that one is a warning, the rest are carried.
    FOR r IN SELECT o.o AS opt
               FROM pg_catalog.pg_class c, LATERAL pg_catalog.unnest(c.reloptions) o(o)
              WHERE c.oid = v_part_oid
    LOOP
        v_k := pg_catalog.split_part(r.opt, '=', 1);
        v_v := pg_catalog.substr(r.opt, pg_catalog.strpos(r.opt, '=') + 1);
        BEGIN
            EXECUTE 'ALTER TABLE ' || v_new || ' SET ('
                 || CASE WHEN pg_catalog.strpos(v_k, '.') > 0
                         THEN pg_catalog.quote_ident(pg_catalog.split_part(v_k, '.', 1)) || '.'
                              || pg_catalog.quote_ident(pg_catalog.split_part(v_k, '.', 2))
                         ELSE pg_catalog.quote_ident(v_k) END
                 || ' = ' || pg_catalog.quote_literal(v_v) || ')';
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'the storage parameter %% of %% was not carried to the new table: %%',
                r.opt, v_part, SQLERRM;
        END;
    END LOOP;
    -- the privileges of the old partition, table and column level
    FOR r IN SELECT DISTINCT x.grantee
               FROM pg_catalog.pg_class c, LATERAL pg_catalog.aclexplode(c.relacl) x
              WHERE c.oid = v_new::pg_catalog.regclass AND x.grantee <> v_owner
    LOOP
        EXECUTE 'REVOKE ALL ON TABLE ' || v_new || ' FROM '
             || CASE WHEN r.grantee = 0 THEN 'PUBLIC'
                     ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(r.grantee)) END;
    END LOOP;
    FOR r IN SELECT x.grantee, x.privilege_type, x.is_grantable
               FROM pg_catalog.pg_class c,
                    LATERAL pg_catalog.aclexplode(coalesce(c.relacl, pg_catalog.acldefault('r', c.relowner))) x
              WHERE c.oid = v_part_oid AND x.grantee <> c.relowner
    LOOP
        EXECUTE 'GRANT ' || r.privilege_type || ' ON TABLE ' || v_new || ' TO '
             || CASE WHEN r.grantee = 0 THEN 'PUBLIC'
                     ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(r.grantee)) END
             || CASE WHEN r.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END;
    END LOOP;
    FOR r IN SELECT a.attname, x.grantee, x.privilege_type, x.is_grantable
               FROM pg_catalog.pg_attribute a, LATERAL pg_catalog.aclexplode(a.attacl) x
              WHERE a.attrelid = v_part_oid AND a.attnum > 0 AND NOT a.attisdropped
                AND x.grantee <> v_owner
    LOOP
        EXECUTE 'GRANT ' || r.privilege_type || ' (' || pg_catalog.quote_ident(r.attname)
             || ') ON TABLE ' || v_new || ' TO '
             || CASE WHEN r.grantee = 0 THEN 'PUBLIC'
                     ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(r.grantee)) END
             || CASE WHEN r.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END;
    END LOOP;
    -- the privileges that the owner took from itself stay taken
    FOR r IN SELECT d.privilege_type
               FROM pg_catalog.pg_class c,
                    LATERAL pg_catalog.aclexplode(pg_catalog.acldefault('r', c.relowner)) d
              WHERE c.oid = v_part_oid AND c.relacl IS NOT NULL AND d.grantee = c.relowner
                AND NOT EXISTS (SELECT 1 FROM pg_catalog.aclexplode(c.relacl) x
                                 WHERE x.grantee = c.relowner AND x.privilege_type = d.privilege_type)
    LOOP
        EXECUTE 'REVOKE ' || r.privilege_type || ' ON TABLE ' || v_new || ' FROM '
             || pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(v_owner));
    END LOOP;

    -- the enabled state of the triggers that the partition has from the
    -- table: the attach clones them enabled, and the old state is put back below
    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name', t.tgname, 'en', t.tgenabled::pg_catalog.text)
                                ORDER BY t.tgname) INTO v_trg
      FROM pg_catalog.pg_trigger t
     WHERE t.tgrelid = v_part_oid AND NOT t.tgisinternal AND t.tgparentid <> 0
       AND t.tgenabled <> 'O';

    -- the swap.  A session that holds the parent (a writer through it, a
    -- reader inside a transaction) and waits for a lock on the partition,
    -- which we hold, is a cycle with the lock we are about to ask for.  It would
    -- be broken by our timeout below, or, if the session has waited longer than
    -- deadlock_timeout, by the deadlock detector running in that session,
    -- which would then be the one that fails.  So do not ask: the conversion
    -- gives way at once.
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_locks w JOIN pg_catalog.pg_locks h ON h.pid = w.pid
                WHERE w.locktype = 'relation' AND w.database = (SELECT d.oid FROM pg_catalog.pg_database d WHERE d.datname = pg_catalog.current_database())
                  AND w.relation = v_part_oid AND NOT w.granted
                  AND h.locktype = 'relation' AND h.database = w.database
                  AND h.relation = v_parent_oid AND h.granted) THEN
        RAISE EXCEPTION 'swap_lock_timeout: a session that holds %% waits for the partition %%; the copy was discarded and the next run tries again',
            v_parent, v_part USING ERRCODE = '55P03';
    END IF;
    PERFORM pg_catalog.set_config('lock_timeout', v_swap::pg_catalog.text || 'ms', true);
    BEGIN
        EXECUTE 'LOCK TABLE ' || v_parent || ' IN ACCESS EXCLUSIVE MODE';
    EXCEPTION WHEN lock_not_available THEN
        RAISE EXCEPTION 'swap_lock_timeout: %% could not be locked within %% ms; the copy was discarded and the next run tries again',
            v_parent, v_swap USING ERRCODE = '55P03';
    END;
    -- What the partition carries and a change does not need the table's lock
    -- for (privileges, names, comments and options of the indexes) is read
    -- again, now that the parent is locked: a change that committed during the
    -- copy or the wait would be dropped with the old partition, so the
    -- conversion gives way and the next run tries again.
    IF kingres.timepart__convert_fp(v_part_oid) IS DISTINCT FROM v_fp THEN
        RAISE EXCEPTION 'schema_changed: the privileges, or the names, comments or options of the indexes, of %% were changed while the conversion copied it; the copy was discarded and the next run tries again',
            v_part USING ERRCODE = '55P03';
    END IF;
    EXECUTE 'ALTER TABLE ' || v_parent || ' DETACH PARTITION ' || v_part;
    EXECUTE 'ALTER TABLE ' || v_parent || ' ATTACH PARTITION ' || v_new || ' ' || v_bound;
    EXECUTE 'DROP TABLE ' || v_part;
    EXECUTE 'ALTER TABLE ' || v_new || ' RENAME TO ' || pg_catalog.quote_ident(v_old_name);
    v_final := pg_catalog.quote_ident(v_schema) || '.' || pg_catalog.quote_ident(v_old_name);
    IF v_bound_cl <> '' THEN
        EXECUTE 'ALTER TABLE ' || v_final
             || ' DROP CONSTRAINT ' || pg_catalog.quote_ident(v_check);
    END IF;
    -- the names, and the comments, of the indexes and constraints
    FOR r IN SELECT x FROM pg_catalog.jsonb_array_elements(v_ix) t(x)
    LOOP
        IF r.x ->> 'con' IS NOT NULL THEN
            EXECUTE 'ALTER TABLE ' || v_final || ' RENAME CONSTRAINT '
                 || pg_catalog.quote_ident(r.x ->> 'tmp') || ' TO ' || pg_catalog.quote_ident(r.x ->> 'con');
            IF r.x ->> 'cdesc' IS NOT NULL THEN
                EXECUTE 'COMMENT ON CONSTRAINT ' || pg_catalog.quote_ident(r.x ->> 'con') || ' ON '
                     || v_final || ' IS ' || pg_catalog.quote_literal(r.x ->> 'cdesc');
            END IF;
        ELSE
            EXECUTE 'ALTER INDEX ' || pg_catalog.quote_ident(v_schema) || '.'
                 || pg_catalog.quote_ident(r.x ->> 'tmp') || ' RENAME TO ' || pg_catalog.quote_ident(r.x ->> 'name');
        END IF;
        IF r.x ->> 'idesc' IS NOT NULL THEN
            EXECUTE 'COMMENT ON INDEX ' || pg_catalog.quote_ident(v_schema) || '.'
                 || pg_catalog.quote_ident(coalesce(r.x ->> 'con', r.x ->> 'name'))
                 || ' IS ' || pg_catalog.quote_literal(r.x ->> 'idesc');
        END IF;
        -- the statistics targets of the expression columns of the index
        FOR i IN 0 .. pg_catalog.jsonb_array_length(r.x -> 'stats') - 1 LOOP
            BEGIN
                EXECUTE 'ALTER INDEX ' || pg_catalog.quote_ident(v_schema) || '.'
                     || pg_catalog.quote_ident(coalesce(r.x ->> 'con', r.x ->> 'name'))
                     || ' ALTER COLUMN ' || ((r.x -> 'stats' -> i) ->> 'n')
                     || ' SET STATISTICS ' || ((r.x -> 'stats' -> i) ->> 't');
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'a statistics target of the index %% was not carried to the new table: %%',
                    coalesce(r.x ->> 'con', r.x ->> 'name'), SQLERRM;
            END;
        END LOOP;
        -- the index that the table is clustered on
        IF (r.x ->> 'cluster')::pg_catalog.bool THEN
            BEGIN
                EXECUTE 'ALTER TABLE ' || v_final || ' CLUSTER ON '
                     || pg_catalog.quote_ident(coalesce(r.x ->> 'con', r.x ->> 'name'));
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'the clustering index %% was not carried to the new table: %%',
                    coalesce(r.x ->> 'con', r.x ->> 'name'), SQLERRM;
            END;
        END IF;
    END LOOP;
    -- the enabled state of the cloned triggers
    FOR r IN SELECT x FROM pg_catalog.jsonb_array_elements(coalesce(v_trg, '[]'::pg_catalog.jsonb)) t(x)
    LOOP
        EXECUTE 'ALTER TABLE ' || v_final
             || CASE r.x ->> 'en' WHEN 'D' THEN ' DISABLE TRIGGER '
                                  WHEN 'R' THEN ' ENABLE REPLICA TRIGGER '
                                  ELSE ' ENABLE ALWAYS TRIGGER ' END
             || pg_catalog.quote_ident(r.x ->> 'name');
    END LOOP;
    PERFORM pg_catalog.set_config('lock_timeout', v_prev_lt, true);
END
$tpl$,
        p_target, p_sort::text, p_options::text, v_opts.o_compression, v_opts.o_level,
        v_opts.o_stripe, v_opts.o_chunk, v_swap, (v_kind = 'columnar')::text,
        p_part::oid, p_parent::oid);
    RETURN ARRAY[format('DO %L', v_body)];
END;
$$;

-- After the transaction of a conversion has committed: give every conversion
-- of the run that was done and not yet noted its size afterwards, the rows and
-- the time it took, in the history, and return the partitions, so that the
-- caller can analyze them.  Nothing of this can be known inside the
-- conversion's own transaction: the stripes of a columnar table are written
-- when the transaction commits.  SECURITY DEFINER, because the history is
-- written by the extension; the caller is judged as in timepart__step_end.
CREATE FUNCTION kingres.timepart__convert_note(
    p_run bigint, p_caller_oid oid, p_caller_super boolean)
RETURNS TABLE (part_schema name, part_name name)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_run   kingres.timepart_run_data%ROWTYPE;
    v_a     kingres.timepart_run_action_data%ROWTYPE;
    v_oid   oid;
    v_size  bigint;
    v_rows  bigint;
    v_ratio float8;
    v_text  text;
BEGIN
    SELECT r.* INTO v_run FROM kingres.timepart_run_data r
     WHERE r.run_id = p_run FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'run % does not exist', p_run USING ERRCODE = '42704';
    END IF;
    PERFORM kingres.timepart__require_driver(
        CASE WHEN v_run.stamp = kingres.timepart__stamp()
             THEN v_run.table_owner_oid ELSE 0::pg_catalog.oid END,
        p_caller_oid, p_caller_super);
    FOR v_a IN SELECT a.* FROM kingres.timepart_run_action_data a
                WHERE a.run_id = p_run AND a.kind = 'convert'
                  AND a.state = 'done' AND a.bytes_after IS NULL
                ORDER BY a.seq
    LOOP
        v_oid := kingres.timepart__oid(v_a.partition_schema, v_a.partition_name);
        v_size := coalesce(pg_total_relation_size(v_oid), 0);
        v_rows := NULL;
        v_ratio := NULL;
        IF v_oid IS NOT NULL
           AND pg_catalog.to_regprocedure('kingres.columnar_info(regclass)') IS NOT NULL
           AND kingres.timepart__am_kind(
                   (SELECT am.amname FROM pg_class c JOIN pg_am am ON am.oid = c.relam
                     WHERE c.oid = v_oid)) = 'columnar' THEN
            EXECUTE 'SELECT i.rows, i.compression_ratio FROM kingres.columnar_info($1) i'
                INTO v_rows, v_ratio USING v_oid::pg_catalog.regclass;
        END IF;
        v_text := format('%s%s, %s s',
                         CASE WHEN v_rows IS NULL THEN ''
                              ELSE format('%s rows, compression ratio %s, ', v_rows,
                                          coalesce(round(v_ratio::numeric, 2)::text, 'n/a')) END,
                         format('%s bytes before, %s after', v_a.bytes_before, v_size),
                         round(extract(epoch FROM coalesce(v_a.finished_at, now()) - v_a.started_at)::numeric, 1));
        UPDATE kingres.timepart_run_action_data a
           SET bytes_after = v_size,
               detail = coalesce(a.detail || ': ', '') || v_text
         WHERE a.run_id = v_a.run_id AND a.seq = v_a.seq;
        part_schema := v_a.partition_schema;
        part_name := v_a.partition_name;
        RETURN NEXT;
    END LOOP;
END;
$$;

-- What follows the commit of a conversion, in a transaction of its own
-- (10.4 step 8): note the result in the history and ANALYZE the new
-- partitions.  A failure to analyze (a lock that is not granted in time) is
-- a warning: the conversion is complete without statistics, which autovacuum
-- makes later.  SECURITY INVOKER: the ANALYZE is the caller's.
CREATE FUNCTION kingres.timepart__convert_after(p_run bigint)
RETURNS integer
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_self  oid;
    v_super boolean;
    v_part  record;
    v_n     integer := 0;
BEGIN
    SELECT r.oid, r.rolsuper INTO v_self, v_super
      FROM pg_roles r WHERE r.rolname = current_user;
    PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
    FOR v_part IN SELECT n.part_schema, n.part_name
                    FROM kingres.timepart__convert_note(p_run, v_self, v_super) n
    LOOP
        BEGIN
            EXECUTE format('ANALYZE %I.%I', v_part.part_schema, v_part.part_name);
            v_n := v_n + 1;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'ANALYZE of %.% was not done: %',
                quote_ident(v_part.part_schema), quote_ident(v_part.part_name), SQLERRM;
        END;
    END LOOP;
    RETURN v_n;
END;
$$;

-- The conversion needs kingres_columnar: the error names it.  (Replaces
-- timepart__no_columnar of 0.1, which was only executable by superusers.)
CREATE FUNCTION kingres.timepart__need_columnar()
RETURNS void
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_extension e
                    WHERE e.extname = 'kingres_columnar') THEN
        RAISE EXCEPTION 'converting a partition needs the extension kingres_columnar, which is not installed'
            USING ERRCODE = '0A000',
                  HINT = 'Install kingres_columnar in this database; the run skips the conversion step until then.';
    END IF;
END;
$$;

------------------------------------------------------------------------
-- The conversion procedures
------------------------------------------------------------------------

-- Replace one leaf partition by a copy in another access method (10.4).  The
-- partition is checked, copied, verified and swapped in one transaction (see
-- timepart__convert_stmts); a failure at any point leaves the old partition
-- as it was.  The transaction commits, and the new partition is analyzed in a
-- transaction of its own.  It cannot run inside a transaction block, and the
-- search path is set as in timepart_run.  Called by the owner of the table, as
-- itself, or by a superuser (the owner's code then runs in the superuser's
-- session, which timepart__exec_as refuses unless the owner is a superuser or
-- the session trusts the owners of its tables).
CREATE PROCEDURE kingres.convert_partition(
    parent regclass, part regclass,
    access_method name DEFAULT 'columnar', sort_by text[] DEFAULT NULL,
    options jsonb DEFAULT NULL)
LANGUAGE plpgsql
AS $$
DECLARE
    v_info   record;
    v_stmts  text[];
    v_self   oid;
    v_super  boolean;
    v_pschema name;
    v_pname   name;
BEGIN
    PERFORM pg_catalog.set_config('search_path', 'pg_catalog, pg_temp', true);
    -- Refuse a transaction block before anything is done.
    COMMIT;
    PERFORM pg_catalog.set_config('search_path', 'pg_catalog, pg_temp', true);
    IF parent IS NULL OR part IS NULL OR access_method IS NULL THEN
        RAISE EXCEPTION 'parent, part and access_method must not be null'
            USING ERRCODE = '22004';
    END IF;
    IF kingres.timepart__am_kind(access_method) IS DISTINCT FROM 'heap' THEN
        PERFORM kingres.timepart__need_columnar();
    END IF;
    PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
    SELECT r.oid, r.rolsuper INTO v_self, v_super
      FROM pg_catalog.pg_roles r WHERE r.rolname OPERATOR(pg_catalog.=) current_user;
    SELECT * INTO v_info FROM kingres.timepart__key_info(parent::pg_catalog.oid);
    SELECT n.nspname, c.relname INTO v_pschema, v_pname
      FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
     WHERE c.oid = part::pg_catalog.oid;
    v_stmts := kingres.timepart__convert_stmts(
        parent::pg_catalog.oid, part::pg_catalog.oid, access_method, sort_by, options);
    IF v_self = v_info.r_owner_oid AND session_user = current_user THEN
        PERFORM kingres.timepart__exec_direct(v_stmts);
    ELSIF v_super THEN
        PERFORM kingres.timepart__exec_as(v_info.r_owner_oid, v_stmts);
    ELSE
        RAISE EXCEPTION 'permission denied: only the owner of the table itself or a superuser may convert its partitions'
            USING ERRCODE = '42501';
    END IF;
    COMMIT;
    PERFORM pg_catalog.set_config('search_path', 'pg_catalog, pg_temp', true);
    PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
    BEGIN
        EXECUTE pg_catalog.format('ANALYZE %I.%I', v_pschema, v_pname);
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'ANALYZE of %.% was not done: %',
            pg_catalog.quote_ident(v_pschema), pg_catalog.quote_ident(v_pname), SQLERRM;
    END;
END;
$$;

-- convert_partition for every partition whose upper bound is at or before
-- older_than and whose access method differs, oldest first, one transaction
-- each.  Partitions committed before a failure stay converted; the first
-- partition that is refused or fails ends the call with its error (the policy
-- path, timepart_run, records each partition and goes on).  A timestamp or
-- date key is read as UTC wall-clock time here, as in
-- drop_old_time_partitions called with its default zone.
CREATE PROCEDURE kingres.convert_old_partitions(
    parent regclass, older_than timestamptz,
    access_method name DEFAULT 'columnar', sort_by text[] DEFAULT NULL,
    options jsonb DEFAULT NULL)
LANGUAGE plpgsql
AS $$
DECLARE
    v_info   record;
    v_kind   text;
    v_limit  timestamptz;
    v_parts  oid[];
    v_oid    oid;
BEGIN
    PERFORM pg_catalog.set_config('search_path', 'pg_catalog, pg_temp', true);
    -- Refuse a transaction block before anything is done.
    COMMIT;
    PERFORM pg_catalog.set_config('search_path', 'pg_catalog, pg_temp', true);
    IF parent IS NULL OR older_than IS NULL OR access_method IS NULL THEN
        RAISE EXCEPTION 'parent, older_than and access_method must not be null'
            USING ERRCODE = '22004';
    END IF;
    IF older_than IN ('infinity', '-infinity') THEN
        RAISE EXCEPTION 'older_than must be a finite time' USING ERRCODE = '22008';
    END IF;
    v_kind := kingres.timepart__am_kind(access_method);
    IF v_kind IS DISTINCT FROM 'heap' THEN
        PERFORM kingres.timepart__need_columnar();
    END IF;
    IF v_kind IS NULL OR v_kind OPERATOR(pg_catalog.=) 'other' THEN
        RAISE EXCEPTION 'conversion_refused: "%" is not a supported table access method (use columnar or heap)',
            access_method USING ERRCODE = '0A000';
    END IF;
    PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
    SELECT * INTO v_info FROM kingres.timepart__key_info(parent::pg_catalog.oid);
    PERFORM kingres.timepart__require_owner(
        current_user, v_info.r_owner_oid,
        pg_catalog.format('%I.%I', v_info.r_schema, v_info.r_table));
    v_limit := kingres.timepart__eff(older_than, v_info.r_keytype, 'UTC');
    SELECT coalesce(pg_catalog.array_agg(c.part_oid ORDER BY c.hi), '{}') INTO v_parts
      FROM kingres.timepart__children(parent::pg_catalog.oid) c
     WHERE NOT c.is_default AND c.hi < 'infinity' AND c.hi <= v_limit
       AND kingres.timepart__am_kind(c.am_name) IS DISTINCT FROM v_kind;
    FOREACH v_oid IN ARRAY v_parts LOOP
        CALL kingres.convert_partition(parent, v_oid::pg_catalog.regclass,
                                       access_method, sort_by, options);
        PERFORM pg_catalog.set_config('search_path', 'pg_catalog, pg_temp', true);
    END LOOP;
END;
$$;

------------------------------------------------------------------------
-- Event triggers: a rename or a drop of the table updates the policy
------------------------------------------------------------------------

-- A renamed or moved table keeps its policy and its history: the rows follow
-- the OID.  Only the rows of this installation are followed (see "Identity"):
-- the OID in a row that a backup carried means nothing here, and may be the
-- OID of an unrelated table.  A policy is changed only when the table it
-- names is gone, too.
CREATE FUNCTION kingres.timepart__on_ddl_end()
RETURNS event_trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    r record;
BEGIN
    FOR r IN SELECT d.objid FROM pg_event_trigger_ddl_commands() d
              WHERE d.object_type = 'table' AND d.objid IS NOT NULL
    LOOP
        UPDATE kingres.timepart_policy_data p
           SET schema_name = n.nspname, table_name = c.relname,
               updated_at = now()
          FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
         WHERE c.oid = r.objid AND c.relkind = 'p'
           AND p.parent_oid = r.objid
           AND kingres.timepart__policy_stamp(p.schema_name, p.table_name, p.stamp)
               = kingres.timepart__stamp()
           AND (p.schema_name, p.table_name) IS DISTINCT FROM (n.nspname, c.relname)
           AND kingres.timepart__oid(p.schema_name, p.table_name) IS NULL
           AND NOT EXISTS (SELECT 1 FROM kingres.timepart_policy_data p2
                            WHERE p2.schema_name = n.nspname
                              AND p2.table_name = c.relname);
        -- the runs of the table carry its name as it is now
        UPDATE kingres.timepart_run_data x
           SET schema_name = n.nspname, table_name = c.relname
          FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
         WHERE c.oid = r.objid AND c.relkind = 'p'
           AND x.table_oid = r.objid
           AND x.stamp = kingres.timepart__stamp()
           AND (x.schema_name, x.table_name) IS DISTINCT FROM (n.nspname, c.relname);
    END LOOP;
END;
$$;

-- A dropped table loses its policy; its history stays, with the owner the
-- table had, and no longer belongs to any table (the OID is forgotten, so that
-- a later table of the same name, or with the same OID, is another table).
CREATE FUNCTION kingres.timepart__on_sql_drop()
RETURNS event_trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    r record;
BEGIN
    FOR r IN SELECT o.objid FROM pg_event_trigger_dropped_objects() o
              WHERE o.object_type = 'table'
    LOOP
        DELETE FROM kingres.timepart_policy_data p
         WHERE p.parent_oid = r.objid
           AND p.stamp = kingres.timepart__stamp()
           AND kingres.timepart__oid(p.schema_name, p.table_name) IS NULL;
        UPDATE kingres.timepart_run_data x SET table_oid = NULL
         WHERE x.table_oid = r.objid AND x.stamp = kingres.timepart__stamp();
    END LOOP;
END;
$$;

CREATE EVENT TRIGGER kingres_timepart_ddl_end ON ddl_command_end
    WHEN TAG IN ('ALTER TABLE')
    EXECUTE FUNCTION kingres.timepart__on_ddl_end();
ALTER EVENT TRIGGER kingres_timepart_ddl_end ENABLE ALWAYS;

CREATE EVENT TRIGGER kingres_timepart_sql_drop ON sql_drop
    EXECUTE FUNCTION kingres.timepart__on_sql_drop();
ALTER EVENT TRIGGER kingres_timepart_sql_drop ENABLE ALWAYS;

------------------------------------------------------------------------
-- Privileges: EXECUTE is revoked from PUBLIC on every function that is not
-- a pure helper.  The functions that act on a user table check ownership
-- themselves; whoever should use them is granted EXECUTE by an administrator.
------------------------------------------------------------------------

REVOKE ALL ON FUNCTION
    kingres.timepart_adopt(boolean),
    kingres.timepart__exec_as(oid, text[]),
    kingres.timepart__adopt(name, name, boolean, boolean),
    kingres.timepart__policy_fp(kingres.timepart_policy_data),
    kingres.timepart__policy_seal_trg(),
    kingres.timepart__policy_seal_truncate(),
    kingres.timepart__require_driver(oid, oid, boolean),
    kingres.timepart__trust_owners(),
    kingres.timepart__step_begin(bigint, text, oid, boolean, boolean),
    kingres.timepart__step_end(bigint, text, name, name, timestamptz, timestamptz, text, text, bigint, oid, boolean),
    kingres.timepart__begin_run(regclass, timestamptz, text, oid, boolean),
    kingres.timepart__finish_run(bigint, oid, boolean),
    kingres.create_time_partitions(regclass, interval, timestamptz, timestamptz, name, text),
    kingres.drop_old_time_partitions(regclass, timestamptz, boolean, text),
    kingres.timepart_set_policy(regclass, interval, interval, interval, text, interval, text[], jsonb, text, interval, boolean),
    kingres.timepart_unset_policy(regclass),
    kingres.timepart_plan(regclass, timestamptz),
    kingres.timepart_partitions(regclass),
    kingres.timepart_check(interval, timestamptz),
    kingres.timepart_due(timestamptz),
    kingres.timepart_begin_run(regclass, timestamptz, text),
    kingres.timepart_finish_run(bigint),
    kingres.timepart_prune_runs(name, name, timestamptz),
    kingres.timepart_run_action(bigint, text),
    kingres.timepart__claim(name, name, text),
    kingres.timepart__on_ddl_end(),
    kingres.timepart__on_sql_drop(),
    kingres.timepart__convert_note(bigint, oid, boolean),
    kingres.timepart__convert_after(bigint)
    FROM PUBLIC;
REVOKE ALL ON PROCEDURE
    kingres.timepart_run_phase(bigint, text),
    kingres.timepart_run(regclass, timestamptz, text[], bigint),
    kingres.convert_partition(regclass, regclass, name, text[], jsonb),
    kingres.convert_old_partitions(regclass, timestamptz, name, text[], jsonb)
    FROM PUBLIC;

-- The owner of a table drives the maintenance of its own tables from its own
-- session (see timepart__exec_as): these two give a role the EXECUTE that
-- takes and drop it again.  The role can then run a table of its own through
-- timepart_run, or step by step through timepart_due, timepart_begin_run,
-- timepart_run_phase or timepart_run_action, and timepart_finish_run; the
-- functions check that the table is the caller's.  Superuser only.
CREATE FUNCTION kingres.timepart_grant_driver(p_role name)
RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    PERFORM kingres.timepart__require_superuser();
    EXECUTE pg_catalog.format('GRANT USAGE ON SCHEMA kingres TO %I', p_role);
    EXECUTE pg_catalog.format(
        'GRANT EXECUTE ON FUNCTION '
        'kingres.timepart_due(timestamptz), '
        'kingres.timepart_begin_run(regclass, timestamptz, text), '
        'kingres.timepart__begin_run(regclass, timestamptz, text, oid, boolean), '
        'kingres.timepart_run_action(bigint, text), '
        'kingres.timepart__step_begin(bigint, text, oid, boolean, boolean), '
        'kingres.timepart__step_end(bigint, text, name, name, timestamptz, timestamptz, text, text, bigint, oid, boolean), '
        'kingres.timepart_finish_run(bigint), '
        'kingres.timepart__finish_run(bigint, oid, boolean), '
        'kingres.timepart__convert_note(bigint, oid, boolean), '
        'kingres.timepart__convert_after(bigint) TO %I', p_role);
    EXECUTE pg_catalog.format(
        'GRANT EXECUTE ON PROCEDURE '
        'kingres.timepart_run_phase(bigint, text), '
        'kingres.timepart_run(regclass, timestamptz, text[], bigint) TO %I', p_role);
END;
$$;

CREATE FUNCTION kingres.timepart_revoke_driver(p_role name)
RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    PERFORM kingres.timepart__require_superuser();
    EXECUTE pg_catalog.format(
        'REVOKE EXECUTE ON FUNCTION '
        'kingres.timepart_due(timestamptz), '
        'kingres.timepart_begin_run(regclass, timestamptz, text), '
        'kingres.timepart__begin_run(regclass, timestamptz, text, oid, boolean), '
        'kingres.timepart_run_action(bigint, text), '
        'kingres.timepart__step_begin(bigint, text, oid, boolean, boolean), '
        'kingres.timepart__step_end(bigint, text, name, name, timestamptz, timestamptz, text, text, bigint, oid, boolean), '
        'kingres.timepart_finish_run(bigint), '
        'kingres.timepart__finish_run(bigint, oid, boolean), '
        'kingres.timepart__convert_note(bigint, oid, boolean), '
        'kingres.timepart__convert_after(bigint) FROM %I', p_role);
    EXECUTE pg_catalog.format(
        'REVOKE EXECUTE ON PROCEDURE '
        'kingres.timepart_run_phase(bigint, text), '
        'kingres.timepart_run(regclass, timestamptz, text[], bigint) FROM %I', p_role);
END;
$$;

REVOKE ALL ON FUNCTION kingres.timepart_grant_driver(name),
    kingres.timepart_revoke_driver(name) FROM PUBLIC;

-- The two DDL steps run as the caller and are checked by PostgreSQL itself;
-- they are executable by whoever may call create_time_partitions and
-- drop_old_time_partitions, which call them with the caller's rights.
-- (Left executable by PUBLIC: they check nothing of their own and do nothing
-- a caller could not do with the same statements.)

------------------------------------------------------------------------
-- Comments
------------------------------------------------------------------------

COMMENT ON TABLE kingres.timepart_policy_data IS
    'Time partitioning policy per table (base table, dumped by pg_dump; use the view timepart_policy)';
COMMENT ON VIEW kingres.timepart_policy IS
    'The policies of the tables the calling role owns; the policy of a table is changed with timepart_set_policy';
COMMENT ON VIEW kingres.timepart_run IS 'History of runs, shown to the roles that owned the table when the run began; table_oid is the table, null once it is gone';
COMMENT ON VIEW kingres.timepart_run_action IS 'Actions of the runs that the calling role may see';
COMMENT ON COLUMN kingres.timepart_policy_data.parent_oid IS 'OID of the table; a hint, the table is found by name';
COMMENT ON COLUMN kingres.timepart_policy_data.partition_every IS 'Width of one partition';
COMMENT ON COLUMN kingres.timepart_policy_data.timezone IS 'Time zone of the grid of partition bounds';
COMMENT ON COLUMN kingres.timepart_policy_data.create_ahead IS 'How far ahead of the run time partitions are created';
COMMENT ON COLUMN kingres.timepart_policy_data.retention IS 'Partitions that end before run time minus this are retired; null keeps everything';
COMMENT ON COLUMN kingres.timepart_policy_data.retention_action IS 'drop or detach';
COMMENT ON COLUMN kingres.timepart_policy_data.columnar_after IS 'Partitions older than this are converted to columnar storage (needs kingres_columnar)';
COMMENT ON COLUMN kingres.timepart_policy_data.next_run_at IS 'When timepart_due reports the policy as due';
COMMENT ON COLUMN kingres.timepart_policy_data.table_owner IS 'Name of the owner of the table when the policy was set, as recorded; the owner is table_owner_oid (a run fails with owner_changed if it differs)';
COMMENT ON COLUMN kingres.timepart_policy_data.table_owner_oid IS 'Owner of the table when the policy was set; valid when stamp is the stamp of this installation, else the role of the name table_owner';
COMMENT ON COLUMN kingres.timepart_policy_data.created_by_oid IS 'Role that made the policy; null when unknown';
COMMENT ON COLUMN kingres.timepart_policy_data.stamp IS 'Installation that wrote the row; the OIDs in a row with another stamp come from a backup (see timepart_adopt)';
COMMENT ON COLUMN kingres.timepart_run_data.stamp IS 'Installation that wrote the row; the OIDs in a row with another stamp come from a backup (see timepart_adopt)';
COMMENT ON COLUMN kingres.timepart_run_data.table_oid IS 'The table the run was made for; null once the table is dropped';
COMMENT ON COLUMN kingres.timepart_run_data.table_owner_oid IS 'Owner of the table when the run began: the role that may see the run';
COMMENT ON COLUMN kingres.timepart_run_data.table_owner IS 'Name of that owner as recorded';
COMMENT ON COLUMN kingres.timepart_run_data.started_by_oid IS 'The session user that began the run';
COMMENT ON TABLE kingres.timepart_run_data IS 'History of runs of time partitioning policies';
COMMENT ON COLUMN kingres.timepart_run_data.as_of IS 'The time the run was planned for';
COMMENT ON COLUMN kingres.timepart_run_data.state IS 'running, done, partial (an action failed) or failed (the run failed)';
COMMENT ON TABLE kingres.timepart_run_action_data IS 'Actions of a run: create, convert, drop, detach, or a misaligned partition reported';
COMMENT ON COLUMN kingres.timepart_run_action_data.state IS 'running, done, failed or skipped';
COMMENT ON VIEW kingres.timepart_policies IS 'Policies with the state of the latest run of each';

COMMENT ON FUNCTION kingres.create_time_partitions(regclass, interval, timestamptz, timestamptz, name, text) IS
    'Create every missing partition of a table from the one holding start_from to the one holding end_at; returns the number created';
COMMENT ON FUNCTION kingres.drop_old_time_partitions(regclass, timestamptz, boolean, text) IS
    'Drop, or only detach, the partitions whose upper bound is at or before older_than; returns the number';
COMMENT ON FUNCTION kingres.timepart_set_policy(regclass, interval, interval, interval, text, interval, text[], jsonb, text, interval, boolean) IS
    'Create or replace the time partitioning policy of a table; needs ownership of the table';
COMMENT ON FUNCTION kingres.timepart_unset_policy(regclass) IS
    'Remove the policy of a table; its history is kept';
COMMENT ON FUNCTION kingres.timepart_plan(regclass, timestamptz) IS
    'The actions a run would take at as_of, without taking any';
COMMENT ON FUNCTION kingres.timepart_adopt(boolean) IS
    'Adopt the policy rows that a backup carried here (owner by name against the catalog, then a seal), and their history; superuser only';
COMMENT ON FUNCTION kingres.timepart_begin_run(regclass, timestamptz, text) IS
    'Record a run in state running and claim the table (row lock, backend recorded); a superuser, or the owner of the table for its own table';
COMMENT ON PROCEDURE kingres.timepart_run_phase(bigint, text) IS
    'Execute one phase (create, convert or retire) of a run, one transaction per action; a superuser, or the owner of the table';
COMMENT ON FUNCTION kingres.timepart_finish_run(bigint) IS
    'Close a run: final state, next run time, prune old runs; a superuser, or the owner of the table';
COMMENT ON PROCEDURE kingres.timepart_run(regclass, timestamptz, text[], bigint) IS
    'Begin a run, execute its phases and finish it; a superuser, or the owner of the table; cannot run inside a transaction block';
COMMENT ON FUNCTION kingres.timepart_due(timestamptz) IS
    'Enabled, sealed policies whose next_run_at is at or before as_of: every one for a superuser (after adopting restored rows), the caller''s own tables for any other role';
COMMENT ON FUNCTION kingres.timepart_partitions(regclass) IS
    'Partitions of a table with bounds, size and access method';
COMMENT ON FUNCTION kingres.timepart_check(interval, timestamptz) IS
    'Problems of tables with a policy: ahead_low, last_run_failed, policy_orphan, policy_unverified, default_partition_present, misaligned';
COMMENT ON FUNCTION kingres.timepart_prune_runs(name, name, timestamptz) IS
    'Delete runs of a table older than 90 days or beyond the newest 1000; superuser only';
COMMENT ON PROCEDURE kingres.convert_partition(regclass, regclass, name, text[], jsonb) IS
    'Replace a leaf partition by a copy in another access method (columnar or heap), in one transaction; needs kingres_columnar; the owner of the table or a superuser; cannot run inside a transaction block';
COMMENT ON PROCEDURE kingres.convert_old_partitions(regclass, timestamptz, name, text[], jsonb) IS
    'convert_partition for every partition whose upper bound is at or before a time, oldest first; needs kingres_columnar; cannot run inside a transaction block';
COMMENT ON FUNCTION kingres.timepart_interval_parts(interval) IS 'Unit and count of a partition_every, or an error';
COMMENT ON FUNCTION kingres.timepart_cell_start(interval, text, bigint) IS 'Start of the cell number k of the grid';
COMMENT ON FUNCTION kingres.timepart_cell_of(interval, text, timestamptz) IS 'Number of the grid cell that holds an instant';
COMMENT ON FUNCTION kingres.timepart_part_name(name, interval, text, timestamptz) IS 'Generated name of a partition';
COMMENT ON FUNCTION kingres.timepart_create_one(oid, name, name, text, text, name) IS 'Create and attach one partition as the caller';
COMMENT ON FUNCTION kingres.timepart_retire_one(oid, oid, boolean) IS 'Detach, and unless detach_only drop, one partition as the caller';

-- ---------------------------------------------------------------------------
-- Version 0.3: distributed tables (the upgrade script 0.2--0.3, appended)
-- ---------------------------------------------------------------------------

------------------------------------------------------------------------
-- Functions whose body changes (the signature is the same as in 0.2)
------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION kingres.timepart__key_info(
    p_rel oid,
    OUT r_schema name, OUT r_table name, OUT r_owner_oid oid,
    OUT r_owner name, OUT r_keycol name, OUT r_keytype text,
    OUT r_persistence "char", OUT r_am oid, OUT r_default name)
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_c    record;
    v_pt   record;
    v_att  record;
    v_name text;
    v_dist record;
BEGIN
    SELECT c.relkind, c.relpersistence, c.relowner, c.relam, n.nspname,
           c.relname, pg_get_userbyid(c.relowner) AS ownername
      INTO v_c
      FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE c.oid = p_rel;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'relation with OID % does not exist', p_rel
            USING ERRCODE = '42P01';
    END IF;
    v_name := format('%I.%I', v_c.nspname, v_c.relname);
    IF v_c.relkind <> 'p' THEN
        RAISE EXCEPTION '% is not a partitioned table', v_name
            USING ERRCODE = '42809';
    END IF;
    IF v_c.relpersistence = 't' THEN
        RAISE EXCEPTION 'temporary table "%" is not supported', v_c.relname
            USING ERRCODE = '0A000';
    END IF;
    SELECT * INTO v_dist FROM kingres.timepart__dist(p_rel);
    IF v_dist.r_dist THEN
        -- a user-partitioned distributed table: hash on top, the user's
        -- partitions below; the partition key is in the catalog of kingres_shard
        IF v_dist.r_method <> 'range' THEN
            RAISE EXCEPTION '% is not partitioned by RANGE', v_name
                USING ERRCODE = '0A000';
        END IF;
        SELECT a.attname, a.atttypid INTO v_att
          FROM pg_attribute a
         WHERE a.attrelid = p_rel AND a.attnum > 0 AND NOT a.attisdropped
           AND quote_ident(a.attname) = regexp_replace(v_dist.r_key, '^[(](.*)[)]$', '\1');
        IF NOT FOUND THEN
            RAISE EXCEPTION '% must be partitioned by exactly one column, which is not an expression', v_name
                USING ERRCODE = '0A000';
        END IF;
    ELSE
        SELECT pt.partstrat, pt.partnatts, pt.partattrs[0] AS attnum
          INTO v_pt FROM pg_partitioned_table pt WHERE pt.partrelid = p_rel;
        IF v_pt.partstrat <> 'r' THEN
            RAISE EXCEPTION '% is not partitioned by RANGE', v_name
                USING ERRCODE = '0A000';
        END IF;
        IF v_pt.partnatts <> 1 OR v_pt.attnum = 0 THEN
            RAISE EXCEPTION '% must be partitioned by exactly one column, which is not an expression', v_name
                USING ERRCODE = '0A000';
        END IF;
        SELECT a.attname, a.atttypid INTO v_att
          FROM pg_attribute a
         WHERE a.attrelid = p_rel AND a.attnum = v_pt.attnum;
    END IF;
    r_keytype := CASE v_att.atttypid
        WHEN 'pg_catalog.timestamptz'::regtype THEN 'timestamptz'
        WHEN 'pg_catalog.timestamp'::regtype THEN 'timestamp'
        WHEN 'pg_catalog.date'::regtype THEN 'date'
    END;
    IF r_keytype IS NULL THEN
        RAISE EXCEPTION 'partition column "%" of % must be of type date, timestamp or timestamptz',
            v_att.attname, v_name USING ERRCODE = '0A000';
    END IF;
    r_schema := v_c.nspname;
    r_table := v_c.relname;
    r_owner_oid := v_c.relowner;
    r_owner := v_c.ownername;
    r_keycol := v_att.attname;
    r_persistence := v_c.relpersistence;
    r_am := v_c.relam;
    IF v_dist.r_dist THEN
        EXECUTE 'SELECT p.partition_name FROM kingres.dist_partition p '
                'WHERE p.parent::pg_catalog.oid = $1 AND upper(btrim(p.bound)) = ''DEFAULT'''
            INTO r_default USING p_rel;
    ELSE
        SELECT c2.relname INTO r_default
          FROM pg_inherits i JOIN pg_class c2 ON c2.oid = i.inhrelid
         WHERE i.inhparent = p_rel AND pg_get_expr(c2.relpartbound, c2.oid) = 'DEFAULT';
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION kingres.timepart__children(p_parent oid)
RETURNS TABLE (part_oid oid, part_schema name, part_name name,
               lo timestamptz, hi timestamptz, is_default boolean,
               am_name name)
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
SET DateStyle = 'ISO, MDY'
AS $$
DECLARE
    v_keytype text;
    r         record;
    v_m       text[];
    v_lo      timestamptz;
    v_hi      timestamptz;
    v_dist    boolean;
    v_schema  name;
BEGIN
    SELECT k.r_keytype, k.r_schema INTO v_keytype, v_schema FROM kingres.timepart__key_info(p_parent) k;
    v_dist := (SELECT d.r_dist FROM kingres.timepart__dist(p_parent) d);
    -- The partitions of a distributed table are the rows of dist_partition: logical
    -- objects without a relation or an OID, one leaf per bucket; the bound is the
    -- text that was given to create_partition.
    FOR r IN
        SELECT c.oid AS o, n.nspname AS s, c.relname AS nm,
               pg_get_expr(c.relpartbound, c.oid) AS b, a.amname AS am
          FROM pg_inherits i
          JOIN pg_class c ON c.oid = i.inhrelid
          JOIN pg_namespace n ON n.oid = c.relnamespace
          LEFT JOIN pg_am a ON a.oid = c.relam
         WHERE i.inhparent = p_parent AND NOT v_dist
        UNION ALL
        SELECT NULL::oid, v_schema, p.partition_name,
               CASE WHEN upper(btrim(p.bound)) = 'DEFAULT' THEN 'DEFAULT'
                    ELSE 'FOR VALUES ' || btrim(p.bound) END,
               NULL::name
          FROM kingres.timepart__dist_bounds(p_parent) p
         WHERE v_dist
    LOOP
        part_oid := r.o;
        part_schema := r.s;
        part_name := r.nm;
        am_name := r.am;
        IF r.b = 'DEFAULT' THEN
            lo := NULL;
            hi := NULL;
            is_default := true;
            RETURN NEXT;
            CONTINUE;
        END IF;
        v_m := regexp_match(r.b, '^FOR VALUES\s+FROM\s*\((.*)\)\s*TO\s*\((.*)\)\s*$', 'i');
        IF v_m IS NULL THEN
            RAISE EXCEPTION 'cannot read the bound of partition %.%: %',
                r.s, r.nm, r.b USING ERRCODE = '0A000';
        END IF;
        FOR i IN 1..2 LOOP
            DECLARE
                v_lit text := (regexp_match(btrim(v_m[i]), '^''([^'']*)'''))[1];
                v_val timestamptz;
            BEGIN
                IF v_lit IS NULL THEN
                    IF btrim(v_m[i]) !~* '^(MINVALUE|MAXVALUE)$' THEN
                        RAISE EXCEPTION 'cannot read the bound of partition %.%: %',
                            r.s, r.nm, r.b USING ERRCODE = '0A000';
                    END IF;
                    v_val := CASE WHEN btrim(v_m[i]) ILIKE 'MINVALUE' THEN '-infinity'
                                  ELSE 'infinity' END;
                ELSIF v_keytype = 'timestamptz' THEN
                    v_val := v_lit::timestamptz;
                ELSIF v_keytype = 'timestamp' THEN
                    v_val := v_lit::timestamp AT TIME ZONE 'UTC';
                ELSE
                    v_val := v_lit::date::timestamp AT TIME ZONE 'UTC';
                END IF;
                IF i = 1 THEN v_lo := v_val; ELSE v_hi := v_val; END IF;
            END;
        END LOOP;
        lo := v_lo;
        hi := v_hi;
        is_default := false;
        RETURN NEXT;
    END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION kingres.timepart__create_rows(p_parent oid, p_every interval,
                                              p_tz text, p_k_from bigint,
                                              p_k_to bigint)
RETURNS TABLE (part_schema name, part_name name,
               lo timestamptz, hi timestamptz)
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_info record;
    v_los  timestamptz[];
    v_his  timestamptz[];
    v_cnt  integer;
    j      integer := 1;
    k      bigint;
    v_s    timestamptz;
    v_e    timestamptz;
    v_max  integer;
BEGIN
    IF p_k_to - p_k_from + 1 > 10000 THEN
        RAISE EXCEPTION 'too many partitions in one call: % cells',
            p_k_to - p_k_from + 1
            USING ERRCODE = '54000',
                  HINT = 'Create at most 10000 partitions per call; use a wider partition_every or a shorter range.';
    END IF;
    SELECT * INTO v_info FROM kingres.timepart__key_info(p_parent);
    v_max := CASE WHEN (SELECT d.r_dist FROM kingres.timepart__dist(p_parent) d)
                  THEN 57 ELSE 63 END;
    SELECT coalesce(array_agg(c.lo ORDER BY c.lo), '{}'),
           coalesce(array_agg(c.hi ORDER BY c.lo), '{}')
      INTO v_los, v_his
      FROM kingres.timepart__children(p_parent) c
     WHERE NOT c.is_default;
    v_cnt := coalesce(cardinality(v_los), 0);
    v_s := kingres.timepart_cell_start(p_every, p_tz, p_k_from);
    FOR k IN p_k_from..p_k_to LOOP
        v_e := kingres.timepart_cell_start(p_every, p_tz, k + 1);
        -- Existing partitions do not overlap each other, so they are sorted
        -- by upper bound too; the first one whose upper bound is after the
        -- start of the cell is the only one that can touch it.
        WHILE j <= v_cnt AND v_his[j] <= v_s LOOP
            j := j + 1;
        END LOOP;
        -- A zone that skipped a whole local day gives a cell that starts and
        -- ends at one instant: there is nothing to create for it.
        IF v_e > v_s AND NOT (j <= v_cnt AND v_los[j] < v_e) THEN
            part_schema := v_info.r_schema;
            part_name := kingres.timepart__part_name(v_info.r_table, p_every,
                                                     p_tz, v_s, v_max);
            lo := v_s;
            hi := v_e;
            RETURN NEXT;
        END IF;
        v_s := v_e;
    END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION kingres.timepart__plan_rows(
    p_parent oid, p_every interval, p_tz text, p_ahead interval,
    p_retention interval, p_retention_action text,
    p_columnar_after interval, p_as_of timestamptz)
RETURNS TABLE (seq integer, kind text, part_oid oid, part_schema name,
               part_name name, range_from timestamptz, range_to timestamptz,
               reason text)
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_info    record;
    v_tz      text;
    v_asof    timestamptz;
    v_cur_k   bigint;
    v_first_k bigint;
    v_last_k  bigint;
    v_min_lo  timestamptz;
    v_thr_ret timestamptz;
    v_thr_col timestamptz;
    r         record;
    v_seq     integer := 0;
    v_dist    boolean;
    v_kinds   jsonb;
BEGIN
    IF p_as_of IS NULL OR p_as_of IN ('infinity', '-infinity') THEN
        RAISE EXCEPTION 'as_of must be a finite time' USING ERRCODE = '22008';
    END IF;
    SELECT * INTO v_info FROM kingres.timepart__key_info(p_parent);
    v_dist := (SELECT d.r_dist FROM kingres.timepart__dist(p_parent) d);
    v_tz := CASE WHEN v_info.r_keytype = 'timestamptz' THEN p_tz ELSE 'UTC' END;
    v_asof := kingres.timepart__eff(p_as_of, v_info.r_keytype, p_tz);
    v_thr_ret := CASE WHEN p_retention IS NULL THEN NULL
                      ELSE kingres.timepart__add(v_asof, p_retention, v_tz, -1) END;
    v_thr_col := CASE WHEN p_columnar_after IS NULL THEN NULL
                      ELSE kingres.timepart__add(v_asof, p_columnar_after, v_tz, -1) END;

    -- Partitions whose bounds are not on the grid are reported and left alone.
    FOR r IN SELECT * FROM kingres.timepart__misaligned(p_parent, p_every, v_tz) c
    LOOP
        v_seq := v_seq + 1;
        seq := v_seq; kind := 'misaligned';
        part_oid := r.part_oid; part_schema := r.part_schema;
        part_name := r.part_name;
        range_from := r.lo; range_to := r.hi;
        reason := 'bounds are not on the grid of the policy';
        RETURN NEXT;
    END LOOP;

    -- Partitions to create.
    SELECT min(c.lo) INTO v_min_lo
      FROM kingres.timepart__children(p_parent) c
     WHERE NOT c.is_default AND c.lo > '-infinity';
    v_cur_k := kingres.timepart_cell_of(p_every, v_tz, v_asof);
    v_first_k := v_cur_k;
    IF v_min_lo IS NOT NULL THEN
        v_first_k := least(v_cur_k,
                           kingres.timepart_cell_of(p_every, v_tz, v_min_lo));
    END IF;
    IF v_thr_ret IS NOT NULL THEN
        v_first_k := greatest(v_first_k,
                              kingres.timepart_cell_of(p_every, v_tz, v_thr_ret));
    END IF;
    v_last_k := greatest(
        v_cur_k,
        kingres.timepart_cell_of(
            p_every, v_tz,
            kingres.timepart__add(v_asof, p_ahead, v_tz, 1)
            - interval '1 microsecond'));
    FOR r IN SELECT * FROM kingres.timepart__create_rows(
                 p_parent, p_every, v_tz, v_first_k, v_last_k) c
    LOOP
        v_seq := v_seq + 1;
        seq := v_seq; kind := 'create';
        part_oid := NULL; part_schema := r.part_schema;
        part_name := r.part_name;
        range_from := r.lo; range_to := r.hi;
        reason := 'missing partition';
        RETURN NEXT;
    END LOOP;

    -- Partitions to convert.
    IF v_thr_col IS NOT NULL THEN
        -- the storage of the leaves of a distributed table is read on the nodes
        -- (a partition is columnar when every leaf is; mixed while a
        -- conversion is half done, and then converted again)
        IF v_dist THEN
            SELECT coalesce(jsonb_object_agg(k.partition_name, k.kind), '{}')
              INTO v_kinds FROM kingres.timepart__dist_kinds(p_parent) k;
        END IF;
        FOR r IN SELECT * FROM kingres.timepart__children(p_parent) c
                  WHERE NOT c.is_default AND c.hi < 'infinity'
                    AND c.hi <= v_thr_col
                    AND kingres.timepart__on_grid(p_every, v_tz, c.lo)
                    AND kingres.timepart__on_grid(p_every, v_tz, c.hi)
                    AND coalesce(v_kinds ->> c.part_name::text, c.am_name::text)
                        IS DISTINCT FROM 'columnar'
                    AND NOT (v_thr_ret IS NOT NULL AND c.hi <= v_thr_ret)
                  ORDER BY c.hi
        LOOP
            v_seq := v_seq + 1;
            seq := v_seq; kind := 'convert';
            part_oid := r.part_oid; part_schema := r.part_schema;
            part_name := r.part_name;
            range_from := r.lo; range_to := r.hi;
            reason := 'older than columnar_after';
            RETURN NEXT;
        END LOOP;
    END IF;

    -- Partitions to retire.
    IF v_thr_ret IS NOT NULL THEN
        FOR r IN SELECT * FROM kingres.timepart__children(p_parent) c
                  WHERE NOT c.is_default AND c.hi < 'infinity'
                    AND c.hi <= v_thr_ret
                    AND kingres.timepart__on_grid(p_every, v_tz, c.lo)
                    AND kingres.timepart__on_grid(p_every, v_tz, c.hi)
                  ORDER BY c.hi
        LOOP
            v_seq := v_seq + 1;
            seq := v_seq;
            kind := CASE WHEN p_retention_action = 'detach' THEN 'detach'
                         ELSE 'drop' END;
            part_oid := r.part_oid; part_schema := r.part_schema;
            part_name := r.part_name;
            range_from := r.lo; range_to := r.hi;
            reason := 'older than retention';
            RETURN NEXT;
        END LOOP;
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION kingres.timepart_run_action(p_run bigint, p_phase text)
RETURNS boolean
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
SET DateStyle = 'ISO, MDY'
AS $$
DECLARE
    v_s       record;
    v_self    oid;
    v_super   boolean;
    v_stmts   text[];
    v_state   text;
    v_detail  text;
    v_attempt integer;
    v_tries   integer;
    v_info    record;
    v_sort    text[];
    v_opts    jsonb;
    v_dist    boolean;
    v_bound   text;
BEGIN
    SELECT r.oid, r.rolsuper INTO v_self, v_super
      FROM pg_roles r WHERE r.rolname = current_user;
    SELECT * INTO v_s FROM kingres.timepart__step_begin(
        p_run, p_phase, v_self, v_super, session_user = current_user);
    IF NOT v_s.o_more THEN
        RETURN false;
    END IF;
    IF v_s.o_mode = 'recorded' THEN
        RETURN true;
    END IF;

    v_state := 'failed';
    -- A distributed table is changed with the partition functions of
    -- kingres_shard, on every node: the caller must be a superuser.
    v_dist := (SELECT d.r_dist FROM kingres.timepart__dist(v_s.o_parent) d);
    IF v_dist AND NOT v_super THEN
        PERFORM kingres.timepart__step_end(
            p_run, v_s.o_kind, v_s.o_part_schema, v_s.o_part_name, v_s.o_from,
            v_s.o_to, 'failed',
            'permission denied: the partitions of a distributed table are changed by a superuser',
            v_s.o_bytes, v_self, v_super);
        RETURN true;
    END IF;
    -- A conversion copies a whole partition: it is tried once in a run (a
    -- lock that is not granted in time is tried again by the next run, not
    -- by a second copy).
    v_tries := CASE WHEN v_s.o_kind = 'convert' THEN 1 ELSE v_s.o_retries END;
    FOR v_attempt IN 1..v_tries LOOP
        BEGIN
            -- The statements and the lock timeout are prepared here; only the
            -- DDL runs as the table's owner.
            IF v_dist THEN
                -- the operations of kingres_shard (map group primary): each is one
                -- two-phase transaction on every node, refused with object_in_use
                -- while a bucket move or a table operation claims the group
                PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
                IF v_s.o_kind = 'create' THEN
                    v_bound := format('FROM (%L) TO (%L)',
                        kingres.timepart__bound_literal(v_s.o_keytype, v_s.o_from),
                        kingres.timepart__bound_literal(v_s.o_keytype, v_s.o_to));
                    PERFORM kingres.create_partition(v_s.o_parent::regclass,
                                                     v_s.o_part_name::text, v_bound, true);
                ELSIF v_s.o_kind = 'convert' THEN
                    SELECT * INTO v_info FROM kingres.timepart__key_info(v_s.o_parent);
                    SELECT p.columnar_sort, p.columnar_options INTO v_sort, v_opts
                      FROM kingres.timepart_policy p
                     WHERE p.schema_name = v_info.r_schema
                       AND p.table_name = v_info.r_table;
                    v_detail := kingres.timepart__dist_convert(
                        v_s.o_parent, v_s.o_part_name, 'columnar'::name, v_sort, v_opts);
                ELSIF v_s.o_kind = 'detach' THEN
                    PERFORM kingres.detach_partition(v_s.o_parent::regclass, v_s.o_part_name::text);
                ELSE
                    PERFORM kingres.drop_partition(v_s.o_parent::regclass, v_s.o_part_name::text, true);
                END IF;
                v_state := 'done';
                v_detail := CASE WHEN v_s.o_kind = 'convert' THEN 'converted to columnar: ' || v_detail END;
                EXIT;
            END IF;
            IF v_s.o_kind = 'create' THEN
                PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
                v_stmts := kingres.timepart__create_stmts(
                    v_s.o_parent, v_s.o_part_schema, v_s.o_part_name,
                    kingres.timepart__bound_literal(v_s.o_keytype, v_s.o_from),
                    kingres.timepart__bound_literal(v_s.o_keytype, v_s.o_to),
                    v_s.o_am);
            ELSIF v_s.o_kind = 'convert' THEN
                -- The sort and the options are the policy's; the checks, the
                -- statements and the lock waits of the conversion are
                -- timepart__convert_stmts's.
                PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
                SELECT * INTO v_info FROM kingres.timepart__key_info(v_s.o_parent);
                SELECT p.columnar_sort, p.columnar_options INTO v_sort, v_opts
                  FROM kingres.timepart_policy p
                 WHERE p.schema_name = v_info.r_schema
                   AND p.table_name = v_info.r_table;
                v_stmts := kingres.timepart__convert_stmts(
                    v_s.o_parent, v_s.o_part_oid, 'columnar'::name, v_sort, v_opts);
            ELSE
                PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('retire'), true);
                v_stmts := kingres.timepart__retire_stmts(
                    v_s.o_parent, v_s.o_part_oid, v_s.o_kind = 'detach');
            END IF;
            IF v_s.o_mode = 'direct' THEN
                PERFORM kingres.timepart__exec_direct(v_stmts);
            ELSE
                PERFORM kingres.timepart__exec_as(v_s.o_owner_oid, v_stmts);
            END IF;
            v_state := 'done';
            v_detail := CASE WHEN v_s.o_kind = 'convert' THEN 'converted to columnar' END;
            EXIT;
        EXCEPTION
            WHEN object_in_use THEN
                -- a colocation group that a bucket move, a table operation or a
                -- conversion uses: retry_later.  The action is tried again with
                -- a growing wait, and a run that still finds it busy is partial
                -- and comes back within five minutes.
                v_state := 'failed';
                v_detail := 'lock_timeout: retry_later: ' || SQLERRM
                            || format(' (attempt %s of %s)', v_attempt, v_tries);
            WHEN lock_not_available THEN
                v_state := 'failed';
                IF v_s.o_kind = 'convert' AND (SQLERRM LIKE 'swap_lock_timeout:%'
                                               OR SQLERRM LIKE 'schema_changed:%') THEN
                    v_detail := SQLERRM;
                ELSE
                    v_detail := 'lock_timeout: ' || SQLERRM
                                || format(' (attempt %s of %s)', v_attempt, v_tries);
                END IF;
            WHEN query_canceled THEN
                -- The statement_timeout of the driver's statement, or a
                -- cancel by an operator: only the first is an action's
                -- failure.
                IF NOT kingres.timepart__timed_out() THEN
                    RAISE;
                END IF;
                v_state := 'failed';
                v_detail := 'statement_timeout: ' || SQLERRM;
                EXIT;
            WHEN OTHERS THEN
                IF v_s.o_kind = 'convert' AND SQLERRM LIKE 'conversion_refused:%' THEN
                    -- Not a failure of the run: the partition cannot be
                    -- converted as it is (timepart_check reports it).
                    v_state := 'skipped';
                    v_detail := SQLERRM;
                ELSE
                    v_state := 'failed';
                    v_detail := SQLSTATE || ': ' || SQLERRM;
                END IF;
                EXIT;
        END;
        IF v_attempt < v_tries THEN
            -- a distributed table waits longer at each attempt (the group is
            -- busy for as long as a move or a conversion takes)
            PERFORM pg_sleep(least(60000, (v_s.o_sleep_min + random() * (v_s.o_sleep_max - v_s.o_sleep_min))
                                          * CASE WHEN v_dist THEN power(2, v_attempt - 1) ELSE 1 END) / 1000.0);
        END IF;
    END LOOP;

    PERFORM kingres.timepart__step_end(
        p_run, v_s.o_kind, v_s.o_part_schema, v_s.o_part_name, v_s.o_from,
        v_s.o_to, v_state, v_detail, v_s.o_bytes, v_self, v_super);
    RETURN true;
END;
$$;

CREATE OR REPLACE FUNCTION kingres.timepart_set_policy(
    rel regclass, partition_every interval,
    create_ahead interval DEFAULT '7 days',
    retention interval DEFAULT NULL,
    retention_action text DEFAULT 'drop',
    columnar_after interval DEFAULT NULL,
    columnar_sort text[] DEFAULT NULL,
    columnar_options jsonb DEFAULT NULL,
    timezone text DEFAULT 'UTC',
    run_every interval DEFAULT '1 hour',
    enabled boolean DEFAULT true)
RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_info   record;
BEGIN
    SELECT * INTO v_info FROM kingres.timepart__key_info(rel::oid);
    PERFORM kingres.timepart__require_owner(
        current_user, v_info.r_owner_oid,
        format('%I.%I', v_info.r_schema, v_info.r_table));
    IF v_info.r_default IS NOT NULL THEN
        RAISE EXCEPTION 'table %.% has a default partition "%"',
            quote_ident(v_info.r_schema), quote_ident(v_info.r_table),
            v_info.r_default
            USING ERRCODE = '0A000',
                  HINT = 'ATTACH PARTITION scans the default partition under a strong lock, and DETACH ... CONCURRENTLY is refused; create partitions far enough ahead instead.';
    END IF;
    PERFORM kingres.timepart__validate_policy(
        v_info.r_keytype, partition_every, timezone, create_ahead, retention,
        retention_action, columnar_after, columnar_sort, columnar_options,
        run_every);
    -- a distributed table has a leaf for every bucket of every partition
    PERFORM kingres.timepart__dist_budget(rel::oid, partition_every, create_ahead,
                                          retention);

    -- A role writes through the view, and the trigger pins what it must not
    -- choose (the owner, the stamp, who made the policy).  A superuser, which
    -- the trigger trusts, writes the table itself, with the same values.
    IF EXISTS (SELECT 1 FROM pg_roles r
                WHERE r.rolname = current_user AND r.rolsuper) THEN
        -- the one write of a superuser that asks for a seal: this function is
        -- the documented interface
        PERFORM kingres.timepart__mark_seal(v_info.r_schema, v_info.r_table);
        INSERT INTO kingres.timepart_policy_data AS p (
            schema_name, table_name, parent_oid, partition_every, timezone,
            create_ahead, retention, retention_action, columnar_after,
            columnar_sort, columnar_options, run_every, enabled, table_owner,
            table_owner_oid, created_by, created_by_oid, stamp)
        VALUES (
            v_info.r_schema, v_info.r_table, rel::oid, partition_every, timezone,
            create_ahead, retention, retention_action, columnar_after,
            columnar_sort, columnar_options, run_every, enabled, v_info.r_owner,
            v_info.r_owner_oid, current_user,
            (SELECT r.oid FROM pg_roles r WHERE r.rolname = current_user),
            kingres.timepart__stamp())
        ON CONFLICT (schema_name, table_name) DO UPDATE SET
            parent_oid = EXCLUDED.parent_oid,
            partition_every = EXCLUDED.partition_every,
            timezone = EXCLUDED.timezone,
            create_ahead = EXCLUDED.create_ahead,
            retention = EXCLUDED.retention,
            retention_action = EXCLUDED.retention_action,
            columnar_after = EXCLUDED.columnar_after,
            columnar_sort = EXCLUDED.columnar_sort,
            columnar_options = EXCLUDED.columnar_options,
            run_every = EXCLUDED.run_every,
            enabled = EXCLUDED.enabled,
            table_owner = EXCLUDED.table_owner,
            table_owner_oid = EXCLUDED.table_owner_oid,
            stamp = EXCLUDED.stamp,
            updated_at = clock_timestamp();
    ELSE
        INSERT INTO kingres.timepart_policy AS p (
            schema_name, table_name, parent_oid, partition_every, timezone,
            create_ahead, retention, retention_action, columnar_after,
            columnar_sort, columnar_options, run_every, enabled)
        VALUES (
            v_info.r_schema, v_info.r_table, rel::oid, partition_every, timezone,
            create_ahead, retention, retention_action, columnar_after,
            columnar_sort, columnar_options, run_every, enabled)
        ON CONFLICT (schema_name, table_name) DO UPDATE SET
            parent_oid = EXCLUDED.parent_oid,
            partition_every = EXCLUDED.partition_every,
            timezone = EXCLUDED.timezone,
            create_ahead = EXCLUDED.create_ahead,
            retention = EXCLUDED.retention,
            retention_action = EXCLUDED.retention_action,
            columnar_after = EXCLUDED.columnar_after,
            columnar_sort = EXCLUDED.columnar_sort,
            columnar_options = EXCLUDED.columnar_options,
            run_every = EXCLUDED.run_every,
            enabled = EXCLUDED.enabled,
            updated_at = clock_timestamp();
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION kingres.create_time_partitions(
    rel regclass, partition_every interval, end_at timestamptz,
    start_from timestamptz DEFAULT now(), access_method name DEFAULT NULL,
    timezone text DEFAULT 'UTC')
RETURNS integer
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_info   record;
    v_parts  record;
    v_tz     text;
    v_first  bigint;
    v_last   bigint;
    v_n      integer := 0;
    v_am     name := access_method;
    r        record;
BEGIN
    -- Reading the bounds of the partitions takes a lock on them, so the wait
    -- is bounded from the first statement on.
    PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
    SELECT * INTO v_info FROM kingres.timepart__key_info(rel::oid);
    PERFORM kingres.timepart__require_owner(
        current_user, v_info.r_owner_oid,
        format('%I.%I', v_info.r_schema, v_info.r_table));
    IF v_info.r_default IS NOT NULL THEN
        RAISE EXCEPTION 'table %.% has a default partition "%"',
            quote_ident(v_info.r_schema), quote_ident(v_info.r_table),
            v_info.r_default
            USING ERRCODE = '0A000',
                  HINT = 'ATTACH PARTITION scans the default partition under a strong lock; create partitions far enough ahead instead.';
    END IF;
    PERFORM kingres.timepart__check_tz(timezone);
    SELECT * INTO v_parts FROM kingres.timepart_interval_parts(partition_every);
    IF v_info.r_keytype = 'date' AND v_parts.unit = 'hour' THEN
        RAISE EXCEPTION 'partition_every in hours needs a timestamp or timestamptz column, not date'
            USING ERRCODE = '22023';
    END IF;
    IF end_at IS NULL OR start_from IS NULL
       OR end_at IN ('infinity', '-infinity')
       OR start_from IN ('infinity', '-infinity') THEN
        RAISE EXCEPTION 'start_from and end_at must be finite times'
            USING ERRCODE = '22008';
    END IF;
    v_tz := CASE WHEN v_info.r_keytype = 'timestamptz' THEN timezone ELSE 'UTC' END;
    v_first := kingres.timepart_cell_of(
        partition_every, v_tz,
        kingres.timepart__eff(start_from, v_info.r_keytype, timezone));
    v_last := kingres.timepart_cell_of(
        partition_every, v_tz,
        kingres.timepart__eff(end_at, v_info.r_keytype, timezone));
    IF v_last < v_first THEN
        RAISE EXCEPTION 'end_at is before start_from' USING ERRCODE = '22023';
    END IF;
    IF v_am IS NULL THEN
        SELECT a.amname INTO v_am FROM pg_am a WHERE a.oid = v_info.r_am;
    END IF;
    IF (SELECT d.r_dist FROM kingres.timepart__dist(rel::oid) d) THEN
        -- a distributed table: one leaf per bucket on every node, heap
        IF access_method IS NOT NULL AND access_method <> 'heap' THEN
            RAISE EXCEPTION 'the partitions of a distributed table are created as heap'
                USING ERRCODE = '0A000',
                      HINT = 'Convert them with convert_distributed_partition.';
        END IF;
        FOR r IN SELECT * FROM kingres.timepart__create_rows(
                     rel::oid, partition_every, v_tz, v_first, v_last) c
        LOOP
            PERFORM kingres.create_partition(
                rel, r.part_name::text,
                format('FROM (%L) TO (%L)',
                       kingres.timepart__bound_literal(v_info.r_keytype, r.lo),
                       kingres.timepart__bound_literal(v_info.r_keytype, r.hi)),
                false);
            v_n := v_n + 1;
        END LOOP;
        RETURN v_n;
    END IF;
    FOR r IN SELECT * FROM kingres.timepart__create_rows(
                 rel::oid, partition_every, v_tz, v_first, v_last) c
    LOOP
        PERFORM kingres.timepart_create_one(
            rel::oid, r.part_schema, r.part_name,
            kingres.timepart__bound_literal(v_info.r_keytype, r.lo),
            kingres.timepart__bound_literal(v_info.r_keytype, r.hi), v_am);
        v_n := v_n + 1;
    END LOOP;
    RETURN v_n;
END;
$$;

CREATE OR REPLACE FUNCTION kingres.drop_old_time_partitions(
    rel regclass, older_than timestamptz, detach_only boolean DEFAULT false,
    timezone text DEFAULT 'UTC')
RETURNS integer
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_info   record;
    v_limit  timestamptz;
    v_n      integer := 0;
    r        record;
BEGIN
    PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('retire'), true);
    SELECT * INTO v_info FROM kingres.timepart__key_info(rel::oid);
    PERFORM kingres.timepart__require_owner(
        current_user, v_info.r_owner_oid,
        format('%I.%I', v_info.r_schema, v_info.r_table));
    PERFORM kingres.timepart__check_tz(timezone);
    IF older_than IS NULL OR older_than IN ('infinity', '-infinity') THEN
        RAISE EXCEPTION 'older_than must be a finite time' USING ERRCODE = '22008';
    END IF;
    v_limit := kingres.timepart__eff(older_than, v_info.r_keytype, timezone);
    FOR r IN SELECT * FROM kingres.timepart__children(rel::oid) c
              WHERE NOT c.is_default AND c.hi < 'infinity' AND c.hi <= v_limit
              ORDER BY c.hi
    LOOP
        IF r.part_oid IS NULL THEN
            -- a partition of a distributed table
            IF coalesce(detach_only, false) THEN
                PERFORM kingres.detach_partition(rel, r.part_name::text);
            ELSE
                PERFORM kingres.drop_partition(rel, r.part_name::text);
            END IF;
        ELSE
            PERFORM kingres.timepart_retire_one(rel::oid, r.part_oid,
                                                coalesce(detach_only, false));
        END IF;
        v_n := v_n + 1;
    END LOOP;
    RETURN v_n;
END;
$$;

CREATE OR REPLACE FUNCTION kingres.timepart_partitions(rel regclass)
RETURNS TABLE (partition regclass, range_from timestamptz,
               range_to timestamptz, access_method name, size_bytes bigint,
               row_estimate bigint, compression_ratio float8,
               attached boolean)
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_info   record;
BEGIN
    -- Reading the bounds of the partitions takes locks: bound the wait, so that
    -- a long transaction on the table cannot hold a monitor up.
    PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
    SELECT * INTO v_info FROM kingres.timepart__key_info(rel::oid);
    IF (SELECT d.r_dist FROM kingres.timepart__dist(rel::oid) d) THEN
        RAISE EXCEPTION '%.% is a distributed table: its partitions are not tables of this database',
            quote_ident(v_info.r_schema), quote_ident(v_info.r_table)
            USING ERRCODE = '42809',
                  HINT = 'Use timepart_dist_partitions.';
    END IF;
    IF NOT (pg_has_role(current_user, v_info.r_owner_oid, 'USAGE')
            OR has_table_privilege(current_user, rel::oid, 'SELECT')) THEN
        RAISE EXCEPTION 'permission denied for table %',
            format('%I.%I', v_info.r_schema, v_info.r_table)
            USING ERRCODE = '42501';
    END IF;
    RETURN QUERY
    SELECT format('%I.%I', c.part_schema, c.part_name)::regclass,
           c.lo, c.hi, c.am_name,
           pg_total_relation_size(c.part_oid),
           (SELECT CASE WHEN cl.reltuples < 0 THEN NULL
                        ELSE cl.reltuples::bigint END
              FROM pg_class cl WHERE cl.oid = c.part_oid),
           NULL::float8, true
      FROM kingres.timepart__children(rel::oid) c
     WHERE NOT c.is_default
     ORDER BY c.lo;
    RETURN QUERY
    SELECT DISTINCT ON (a.partition_schema, a.partition_name)
           kingres.timepart__oid(a.partition_schema, a.partition_name)::regclass,
           a.range_from, a.range_to,
           (SELECT am.amname FROM pg_class cl JOIN pg_am am ON am.oid = cl.relam
             WHERE cl.oid = kingres.timepart__oid(a.partition_schema, a.partition_name)),
           pg_total_relation_size(kingres.timepart__oid(a.partition_schema, a.partition_name)),
           (SELECT CASE WHEN cl.reltuples < 0 THEN NULL
                        ELSE cl.reltuples::bigint END
              FROM pg_class cl
             WHERE cl.oid = kingres.timepart__oid(a.partition_schema, a.partition_name)),
           NULL::float8, false
      FROM kingres.timepart_run_action a
      JOIN kingres.timepart_run r ON r.run_id = a.run_id
     WHERE r.table_oid = rel::oid
       AND a.kind = 'detach' AND a.state = 'done'
       AND kingres.timepart__oid(a.partition_schema, a.partition_name) IS NOT NULL
       AND has_table_privilege(current_user,
                               kingres.timepart__oid(a.partition_schema, a.partition_name)::oid, 'SELECT')
       AND NOT EXISTS (
           SELECT 1 FROM pg_inherits i
            WHERE i.inhrelid = kingres.timepart__oid(a.partition_schema, a.partition_name)::oid)
     ORDER BY a.partition_schema, a.partition_name, a.run_id DESC;
END;
$$;

CREATE OR REPLACE FUNCTION kingres.timepart__convert_note(
    p_run bigint, p_caller_oid oid, p_caller_super boolean)
RETURNS TABLE (part_schema name, part_name name)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_run   kingres.timepart_run_data%ROWTYPE;
    v_a     kingres.timepart_run_action_data%ROWTYPE;
    v_oid   oid;
    v_size  bigint;
    v_rows  bigint;
    v_ratio float8;
    v_text  text;
BEGIN
    SELECT r.* INTO v_run FROM kingres.timepart_run_data r
     WHERE r.run_id = p_run FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'run % does not exist', p_run USING ERRCODE = '42704';
    END IF;
    PERFORM kingres.timepart__require_driver(
        CASE WHEN v_run.stamp = kingres.timepart__stamp()
             THEN v_run.table_owner_oid ELSE 0::pg_catalog.oid END,
        p_caller_oid, p_caller_super);
    FOR v_a IN SELECT a.* FROM kingres.timepart_run_action_data a
                WHERE a.run_id = p_run AND a.kind = 'convert'
                  AND a.state = 'done' AND a.bytes_after IS NULL
                ORDER BY a.seq
    LOOP
        v_oid := kingres.timepart__oid(v_a.partition_schema, v_a.partition_name);
        -- the leaves of a distributed partition are analyzed on their nodes
        IF v_oid IS NULL AND v_run.table_oid IS NOT NULL
           AND (SELECT d.r_dist FROM kingres.timepart__dist(v_run.table_oid) d) THEN
            UPDATE kingres.timepart_run_action_data a
               SET bytes_after = 0
             WHERE a.run_id = v_a.run_id AND a.seq = v_a.seq;
            CONTINUE;
        END IF;
        v_size := coalesce(pg_total_relation_size(v_oid), 0);
        v_rows := NULL;
        v_ratio := NULL;
        IF v_oid IS NOT NULL
           AND pg_catalog.to_regprocedure('kingres.columnar_info(regclass)') IS NOT NULL
           AND kingres.timepart__am_kind(
                   (SELECT am.amname FROM pg_class c JOIN pg_am am ON am.oid = c.relam
                     WHERE c.oid = v_oid)) = 'columnar' THEN
            EXECUTE 'SELECT i.rows, i.compression_ratio FROM kingres.columnar_info($1) i'
                INTO v_rows, v_ratio USING v_oid::pg_catalog.regclass;
        END IF;
        v_text := format('%s%s, %s s',
                         CASE WHEN v_rows IS NULL THEN ''
                              ELSE format('%s rows, compression ratio %s, ', v_rows,
                                          coalesce(round(v_ratio::numeric, 2)::text, 'n/a')) END,
                         format('%s bytes before, %s after', v_a.bytes_before, v_size),
                         round(extract(epoch FROM coalesce(v_a.finished_at, now()) - v_a.started_at)::numeric, 1));
        UPDATE kingres.timepart_run_action_data a
           SET bytes_after = v_size,
               detail = coalesce(a.detail || ': ', '') || v_text
         WHERE a.run_id = v_a.run_id AND a.seq = v_a.seq;
        part_schema := v_a.partition_schema;
        part_name := v_a.partition_name;
        RETURN NEXT;
    END LOOP;
END;
$$;

DROP FUNCTION kingres.timepart__convert_stmts(oid, oid, name, text[], jsonb);
CREATE FUNCTION kingres.timepart__convert_stmts(
    p_parent oid, p_part oid, p_target name, p_sort text[], p_options jsonb,
    p_dist boolean DEFAULT false)
RETURNS text[]
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
SET DateStyle = 'ISO, MDY'
AS $$
DECLARE
    v_plan    jsonb;
    v_kind    text;
    v_opts    record;
    v_swap    integer;
    v_dl      integer;
    v_body    text;
BEGIN
    -- The checks and the plan, before any lock: a refusal is raised here, with
    -- nothing locked.  The block reads them again under its lock.
    v_plan := kingres.timepart__convert_plan(p_parent, p_part, p_target, p_sort, p_options);
    v_kind := kingres.timepart__am_kind(p_target);
    IF v_kind = 'columnar' THEN
        SELECT * INTO v_opts FROM kingres.timepart__columnar_options(p_options);
    ELSE
        SELECT NULL::text AS o_compression, NULL::integer AS o_level,
               NULL::integer AS o_stripe, NULL::integer AS o_chunk INTO v_opts;
    END IF;
    -- A writer of the partition holds the parent in ROW EXCLUSIVE while it
    -- waits for our lock on the partition, and we wait for the parent: a
    -- cycle that only a timeout breaks.  The wait is below the deadlock
    -- timeout, so the conversion gives way, not the user's statement.
    SELECT s.setting::integer INTO v_dl FROM pg_settings s WHERE s.name = 'deadlock_timeout';
    v_swap := greatest(1, least(500, coalesce(v_dl, 1000) / 2));

    v_body := format($tpl$
DECLARE
    v_am       text := %1$L;
    v_sort     text[] := %2$L;
    v_options  jsonb := %3$L;
    v_o_comp   text := %4$L;
    v_o_level  integer := %5$L;
    v_o_stripe integer := %6$L;
    v_o_chunk  integer := %7$L;
    v_swap     integer := %8$s;
    v_columnar boolean := %9$s;
    v_part_oid oid := %10$s;
    v_parent_oid oid := %11$s;
    v_dist     boolean := %12$s;
    v_prev_lt  text := pg_catalog.current_setting('lock_timeout');
    v_plan     jsonb;
    v_parent   text;
    v_part     text;
    v_new      text;
    v_schema   text;
    v_old_name text;
    v_cols     text;
    v_order    text;
    v_bound_cl text;
    v_bound    text;
    v_check    text;
    v_tblspc   text;
    v_ix       jsonb;
    v_fp       jsonb;
    v_dts      text := pg_catalog.current_setting('default_tablespace');
    v_trg      jsonb;
    v_final    text;
    v_owner    oid;
    v_old_cnt  bigint;
    v_new_cnt  bigint;
    v_text     text;
    v_k        text;
    v_v        text;
    v_ident    "char";
    i          integer;
    r          record;
BEGIN
    -- a partition that is gone: the cast of its OID to a name would give the
    -- digits, and LOCK TABLE of them is a syntax error
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_class c WHERE c.oid = v_part_oid) THEN
        RAISE EXCEPTION 'schema_changed: the partition with OID %% was dropped before the conversion could lock it; the next run tries again',
            v_part_oid USING ERRCODE = '55P03';
    END IF;
    BEGIN
        EXECUTE 'LOCK TABLE ' || v_part_oid::pg_catalog.regclass::pg_catalog.text
             || ' IN SHARE ROW EXCLUSIVE MODE';
    EXCEPTION WHEN undefined_table OR syntax_error THEN
        RAISE EXCEPTION 'schema_changed: the partition with OID %% was renamed or dropped while the conversion waited for its lock; the next run tries again',
            v_part_oid USING ERRCODE = '55P03';
    END;
    -- the lock that is held is the one on the partition, not on a table that
    -- took its name while this statement waited
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_locks l
                    WHERE l.pid = pg_catalog.pg_backend_pid() AND l.locktype = 'relation'
                      AND l.database = (SELECT d.oid FROM pg_catalog.pg_database d WHERE d.datname = pg_catalog.current_database())
                      AND l.relation = v_part_oid AND l.mode = 'ShareRowExclusiveLock' AND l.granted) THEN
        RAISE EXCEPTION 'schema_changed: the partition with OID %% was renamed or dropped while the conversion waited for its lock, and its name is another table now; the next run tries again',
            v_part_oid USING ERRCODE = '55P03';
    END IF;
    -- everything the catalog says about the partition, now that nothing can
    -- change on it; a refusal or an error here is raised as it would be above
    v_plan := kingres.timepart__convert_plan(v_parent_oid, v_part_oid, v_am::pg_catalog.name, v_sort, v_options);
    v_parent   := v_plan ->> 'parent';
    v_part     := v_plan ->> 'part';
    v_new      := v_plan ->> 'newq';
    v_schema   := v_plan ->> 'schema';
    v_old_name := v_plan ->> 'old';
    v_cols     := v_plan ->> 'cols';
    v_order    := v_plan ->> 'order';
    v_bound_cl := v_plan ->> 'bound_cl';
    v_bound    := v_plan ->> 'bound';
    v_check    := v_plan ->> 'check';
    v_tblspc   := v_plan ->> 'tblspc';
    v_ix       := v_plan -> 'ix';
    v_fp       := v_plan -> 'fp';

    EXECUTE 'CREATE TABLE ' || v_new || ' (LIKE ' || v_part
         || ' INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING COMMENTS'
         || ' INCLUDING STORAGE INCLUDING GENERATED INCLUDING COMPRESSION'
         || v_bound_cl || ') USING ' || pg_catalog.quote_ident(v_am) || v_tblspc;
    IF v_columnar AND (v_o_comp IS NOT NULL OR v_o_level IS NOT NULL
                       OR v_o_stripe IS NOT NULL OR v_o_chunk IS NOT NULL) THEN
        PERFORM kingres.columnar_set_options(v_new::pg_catalog.regclass, v_o_comp,
                                             v_o_level, v_o_stripe, v_o_chunk);
    END IF;
    SELECT d.description INTO v_text FROM pg_catalog.pg_description d
     WHERE d.classoid = 'pg_catalog.pg_class'::pg_catalog.regclass
       AND d.objoid = v_part_oid AND d.objsubid = 0;
    IF FOUND THEN
        EXECUTE 'COMMENT ON TABLE ' || v_new || ' IS ' || pg_catalog.quote_literal(v_text);
    END IF;
    SELECT c.relreplident, c.relowner INTO v_ident, v_owner
      FROM pg_catalog.pg_class c WHERE c.oid = v_part_oid;
    -- a columnar leaf of a distributed table has REPLICA IDENTITY FULL: the logical
    -- replication of a bucket move decodes its inserts with it
    IF v_ident = 'f' OR (v_columnar AND v_dist) THEN
        EXECUTE 'ALTER TABLE ' || v_new || ' REPLICA IDENTITY FULL';
    ELSIF v_ident = 'n' THEN
        EXECUTE 'ALTER TABLE ' || v_new || ' REPLICA IDENTITY NOTHING';
    END IF;
    -- The statistics target and the options of each column, which LIKE does not
    -- carry (the storage parameters of the table follow the indexes, below).
    FOR r IN SELECT a.attname, a.attstattarget, a.attoptions
               FROM pg_catalog.pg_attribute a
              WHERE a.attrelid = v_part_oid AND a.attnum > 0 AND NOT a.attisdropped
              ORDER BY a.attnum
    LOOP
        IF r.attstattarget IS NOT NULL AND r.attstattarget <> -1 THEN
            BEGIN
                EXECUTE 'ALTER TABLE ' || v_new || ' ALTER COLUMN ' || pg_catalog.quote_ident(r.attname)
                     || ' SET STATISTICS ' || r.attstattarget::pg_catalog.text;
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'the statistics target of the column %% of %% was not carried to the new table: %%',
                    r.attname, v_part, SQLERRM;
            END;
        END IF;
        IF r.attoptions IS NOT NULL THEN
            FOR i IN 1 .. pg_catalog.array_length(r.attoptions, 1) LOOP
                v_k := pg_catalog.split_part(r.attoptions[i], '=', 1);
                v_v := pg_catalog.substr(r.attoptions[i], pg_catalog.strpos(r.attoptions[i], '=') + 1);
                -- the version stamp of the column is the server's own, and
                -- the new column has its own
                CONTINUE WHEN v_k = 'pg_attver';
                BEGIN
                    EXECUTE 'ALTER TABLE ' || v_new || ' ALTER COLUMN ' || pg_catalog.quote_ident(r.attname)
                         || ' SET (' || pg_catalog.quote_ident(v_k) || ' = ' || pg_catalog.quote_literal(v_v) || ')';
                EXCEPTION WHEN OTHERS THEN
                    RAISE WARNING 'the option %% of the column %% of %% was not carried to the new table: %%',
                        r.attoptions[i], r.attname, v_part, SQLERRM;
                END;
            END LOOP;
        END IF;
    END LOOP;

    EXECUTE 'INSERT INTO ' || v_new || ' (' || v_cols || ') SELECT ' || v_cols
         || ' FROM ' || v_part || v_order;

    EXECUTE 'SELECT pg_catalog.count(*) FROM ' || v_part INTO v_old_cnt;
    EXECUTE 'SELECT pg_catalog.count(*) FROM ' || v_new INTO v_new_cnt;
    IF v_old_cnt IS DISTINCT FROM v_new_cnt THEN
        RAISE EXCEPTION 'verification_failed: %% has %% rows, its copy has %%',
            v_part, v_old_cnt, v_new_cnt USING ERRCODE = 'KT001';
    END IF;

    -- the indexes, after the load, with plain CREATE INDEX (under the lock of
    -- the partition, so the rows cannot change); a duplicate fails here
    FOR r IN SELECT x ->> 'create' AS stmt, x ->> 'spc' AS spc
               FROM pg_catalog.jsonb_array_elements(v_ix) WITH ORDINALITY t(x, n) ORDER BY n
    LOOP
        PERFORM pg_catalog.set_config('default_tablespace', coalesce(r.spc, v_dts), true);
        EXECUTE r.stmt;
    END LOOP;
    PERFORM pg_catalog.set_config('default_tablespace', v_dts, true);

    -- The storage parameters of the table (and of its TOAST table), which LIKE
    -- does not carry, after the load and the indexes: parallel_workers would
    -- have a columnar table refuse a parallel index build of rows that the
    -- transaction has not written yet.  The target access method may not
    -- accept one of them: that one is a warning, the rest are carried.
    FOR r IN SELECT o.o AS opt
               FROM pg_catalog.pg_class c, LATERAL pg_catalog.unnest(c.reloptions) o(o)
              WHERE c.oid = v_part_oid
    LOOP
        v_k := pg_catalog.split_part(r.opt, '=', 1);
        v_v := pg_catalog.substr(r.opt, pg_catalog.strpos(r.opt, '=') + 1);
        BEGIN
            EXECUTE 'ALTER TABLE ' || v_new || ' SET ('
                 || CASE WHEN pg_catalog.strpos(v_k, '.') > 0
                         THEN pg_catalog.quote_ident(pg_catalog.split_part(v_k, '.', 1)) || '.'
                              || pg_catalog.quote_ident(pg_catalog.split_part(v_k, '.', 2))
                         ELSE pg_catalog.quote_ident(v_k) END
                 || ' = ' || pg_catalog.quote_literal(v_v) || ')';
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'the storage parameter %% of %% was not carried to the new table: %%',
                r.opt, v_part, SQLERRM;
        END;
    END LOOP;
    -- the privileges of the old partition, table and column level
    FOR r IN SELECT DISTINCT x.grantee
               FROM pg_catalog.pg_class c, LATERAL pg_catalog.aclexplode(c.relacl) x
              WHERE c.oid = v_new::pg_catalog.regclass AND x.grantee <> v_owner
    LOOP
        EXECUTE 'REVOKE ALL ON TABLE ' || v_new || ' FROM '
             || CASE WHEN r.grantee = 0 THEN 'PUBLIC'
                     ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(r.grantee)) END;
    END LOOP;
    FOR r IN SELECT x.grantee, x.privilege_type, x.is_grantable
               FROM pg_catalog.pg_class c,
                    LATERAL pg_catalog.aclexplode(coalesce(c.relacl, pg_catalog.acldefault('r', c.relowner))) x
              WHERE c.oid = v_part_oid AND x.grantee <> c.relowner
    LOOP
        EXECUTE 'GRANT ' || r.privilege_type || ' ON TABLE ' || v_new || ' TO '
             || CASE WHEN r.grantee = 0 THEN 'PUBLIC'
                     ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(r.grantee)) END
             || CASE WHEN r.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END;
    END LOOP;
    FOR r IN SELECT a.attname, x.grantee, x.privilege_type, x.is_grantable
               FROM pg_catalog.pg_attribute a, LATERAL pg_catalog.aclexplode(a.attacl) x
              WHERE a.attrelid = v_part_oid AND a.attnum > 0 AND NOT a.attisdropped
                AND x.grantee <> v_owner
    LOOP
        EXECUTE 'GRANT ' || r.privilege_type || ' (' || pg_catalog.quote_ident(r.attname)
             || ') ON TABLE ' || v_new || ' TO '
             || CASE WHEN r.grantee = 0 THEN 'PUBLIC'
                     ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(r.grantee)) END
             || CASE WHEN r.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END;
    END LOOP;
    -- the privileges that the owner took from itself stay taken
    FOR r IN SELECT d.privilege_type
               FROM pg_catalog.pg_class c,
                    LATERAL pg_catalog.aclexplode(pg_catalog.acldefault('r', c.relowner)) d
              WHERE c.oid = v_part_oid AND c.relacl IS NOT NULL AND d.grantee = c.relowner
                AND NOT EXISTS (SELECT 1 FROM pg_catalog.aclexplode(c.relacl) x
                                 WHERE x.grantee = c.relowner AND x.privilege_type = d.privilege_type)
    LOOP
        EXECUTE 'REVOKE ' || r.privilege_type || ' ON TABLE ' || v_new || ' FROM '
             || pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(v_owner));
    END LOOP;

    -- the enabled state of the triggers that the partition has from the
    -- table: the attach clones them enabled, and the old state is put back below
    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name', t.tgname, 'en', t.tgenabled::pg_catalog.text)
                                ORDER BY t.tgname) INTO v_trg
      FROM pg_catalog.pg_trigger t
     WHERE t.tgrelid = v_part_oid AND NOT t.tgisinternal AND t.tgparentid <> 0
       AND t.tgenabled <> 'O';

    -- the swap.  A session that holds the parent (a writer through it, a
    -- reader inside a transaction) and waits for a lock on the partition,
    -- which we hold, is a cycle with the lock we are about to ask for.  It would
    -- be broken by our timeout below, or, if the session has waited longer than
    -- deadlock_timeout, by the deadlock detector running in that session,
    -- which would then be the one that fails.  So do not ask: the conversion
    -- gives way at once.
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_locks w JOIN pg_catalog.pg_locks h ON h.pid = w.pid
                WHERE w.locktype = 'relation' AND w.database = (SELECT d.oid FROM pg_catalog.pg_database d WHERE d.datname = pg_catalog.current_database())
                  AND w.relation = v_part_oid AND NOT w.granted
                  AND h.locktype = 'relation' AND h.database = w.database
                  AND h.relation = v_parent_oid AND h.granted) THEN
        RAISE EXCEPTION 'swap_lock_timeout: a session that holds %% waits for the partition %%; the copy was discarded and the next run tries again',
            v_parent, v_part USING ERRCODE = '55P03';
    END IF;
    PERFORM pg_catalog.set_config('lock_timeout', v_swap::pg_catalog.text || 'ms', true);
    BEGIN
        EXECUTE 'LOCK TABLE ' || v_parent || ' IN ACCESS EXCLUSIVE MODE';
    EXCEPTION WHEN lock_not_available THEN
        RAISE EXCEPTION 'swap_lock_timeout: %% could not be locked within %% ms; the copy was discarded and the next run tries again',
            v_parent, v_swap USING ERRCODE = '55P03';
    END;
    -- What the partition carries and a change does not need the table's lock
    -- for (privileges, names, comments and options of the indexes) is read
    -- again, now that the parent is locked: a change that committed during the
    -- copy or the wait would be dropped with the old partition, so the
    -- conversion gives way and the next run tries again.
    IF kingres.timepart__convert_fp(v_part_oid) IS DISTINCT FROM v_fp THEN
        RAISE EXCEPTION 'schema_changed: the privileges, or the names, comments or options of the indexes, of %% were changed while the conversion copied it; the copy was discarded and the next run tries again',
            v_part USING ERRCODE = '55P03';
    END IF;
    EXECUTE 'ALTER TABLE ' || v_parent || ' DETACH PARTITION ' || v_part;
    EXECUTE 'ALTER TABLE ' || v_parent || ' ATTACH PARTITION ' || v_new || ' ' || v_bound;
    EXECUTE 'DROP TABLE ' || v_part;
    EXECUTE 'ALTER TABLE ' || v_new || ' RENAME TO ' || pg_catalog.quote_ident(v_old_name);
    v_final := pg_catalog.quote_ident(v_schema) || '.' || pg_catalog.quote_ident(v_old_name);
    IF v_bound_cl <> '' THEN
        EXECUTE 'ALTER TABLE ' || v_final
             || ' DROP CONSTRAINT ' || pg_catalog.quote_ident(v_check);
    END IF;
    -- the names, and the comments, of the indexes and constraints
    FOR r IN SELECT x FROM pg_catalog.jsonb_array_elements(v_ix) t(x)
    LOOP
        IF r.x ->> 'con' IS NOT NULL THEN
            EXECUTE 'ALTER TABLE ' || v_final || ' RENAME CONSTRAINT '
                 || pg_catalog.quote_ident(r.x ->> 'tmp') || ' TO ' || pg_catalog.quote_ident(r.x ->> 'con');
            IF r.x ->> 'cdesc' IS NOT NULL THEN
                EXECUTE 'COMMENT ON CONSTRAINT ' || pg_catalog.quote_ident(r.x ->> 'con') || ' ON '
                     || v_final || ' IS ' || pg_catalog.quote_literal(r.x ->> 'cdesc');
            END IF;
        ELSE
            EXECUTE 'ALTER INDEX ' || pg_catalog.quote_ident(v_schema) || '.'
                 || pg_catalog.quote_ident(r.x ->> 'tmp') || ' RENAME TO ' || pg_catalog.quote_ident(r.x ->> 'name');
        END IF;
        IF r.x ->> 'idesc' IS NOT NULL THEN
            EXECUTE 'COMMENT ON INDEX ' || pg_catalog.quote_ident(v_schema) || '.'
                 || pg_catalog.quote_ident(coalesce(r.x ->> 'con', r.x ->> 'name'))
                 || ' IS ' || pg_catalog.quote_literal(r.x ->> 'idesc');
        END IF;
        -- the statistics targets of the expression columns of the index
        FOR i IN 0 .. pg_catalog.jsonb_array_length(r.x -> 'stats') - 1 LOOP
            BEGIN
                EXECUTE 'ALTER INDEX ' || pg_catalog.quote_ident(v_schema) || '.'
                     || pg_catalog.quote_ident(coalesce(r.x ->> 'con', r.x ->> 'name'))
                     || ' ALTER COLUMN ' || ((r.x -> 'stats' -> i) ->> 'n')
                     || ' SET STATISTICS ' || ((r.x -> 'stats' -> i) ->> 't');
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'a statistics target of the index %% was not carried to the new table: %%',
                    coalesce(r.x ->> 'con', r.x ->> 'name'), SQLERRM;
            END;
        END LOOP;
        -- the index that the table is clustered on
        IF (r.x ->> 'cluster')::pg_catalog.bool THEN
            BEGIN
                EXECUTE 'ALTER TABLE ' || v_final || ' CLUSTER ON '
                     || pg_catalog.quote_ident(coalesce(r.x ->> 'con', r.x ->> 'name'));
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'the clustering index %% was not carried to the new table: %%',
                    coalesce(r.x ->> 'con', r.x ->> 'name'), SQLERRM;
            END;
        END IF;
    END LOOP;
    -- the enabled state of the cloned triggers
    FOR r IN SELECT x FROM pg_catalog.jsonb_array_elements(coalesce(v_trg, '[]'::pg_catalog.jsonb)) t(x)
    LOOP
        EXECUTE 'ALTER TABLE ' || v_final
             || CASE r.x ->> 'en' WHEN 'D' THEN ' DISABLE TRIGGER '
                                  WHEN 'R' THEN ' ENABLE REPLICA TRIGGER '
                                  ELSE ' ENABLE ALWAYS TRIGGER ' END
             || pg_catalog.quote_ident(r.x ->> 'name');
    END LOOP;
    PERFORM pg_catalog.set_config('lock_timeout', v_prev_lt, true);
END
$tpl$,
        p_target, p_sort::text, p_options::text, v_opts.o_compression, v_opts.o_level,
        v_opts.o_stripe, v_opts.o_chunk, v_swap, (v_kind = 'columnar')::text,
        p_part::oid, p_parent::oid, p_dist::text);
    RETURN ARRAY[format('DO %L', v_body)];
END;
$$;


------------------------------------------------------------------------
-- Distributed tables (increments St-D1a and St-D1b, section 11)
------------------------------------------------------------------------
--
-- A user-partitioned distributed table of kingres_shard (hash on top, the user's range partitions below) has a
-- policy like any other table.  Its partitions are logical objects, rows of kingres.dist_partition with one leaf per
-- bucket on the node that owns the bucket; a run creates, retires and converts them with the partition functions of
-- kingres_shard, on the map group primary, as a superuser.  Nothing here needs kingres_shard to be installed: a
-- database without it has no distributed table.

-- Is the table a range-partitioned distributed table of kingres_shard?  The partition key is as pg_get_partkeydef
-- gives it, without the method.
CREATE FUNCTION kingres.timepart__dist(
    p_rel oid,
    OUT r_dist boolean, OUT r_method text, OUT r_key text,
    OUT r_colocation integer)
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    r_dist := false;
    IF pg_catalog.to_regclass('kingres.dist_table') IS NULL
       OR NOT EXISTS (SELECT 1 FROM pg_catalog.pg_attribute a
                       WHERE a.attrelid = pg_catalog.to_regclass('kingres.dist_table')
                         AND a.attname = 'partition_method' AND NOT a.attisdropped) THEN
        RETURN;
    END IF;
    EXECUTE 'SELECT true, d.partition_method, d.partition_key, d.colocation_id '
            'FROM kingres.dist_table d '
            'WHERE d.relid::pg_catalog.oid = $1 AND d.method = ''hash'' '
            'AND d.partition_method IS NOT NULL'
        INTO r_dist, r_method, r_key, r_colocation USING p_rel;
    r_dist := coalesce(r_dist, false);
END;
$$;

-- The partitions of a distributed table with the bound as it was given to create_partition; nothing without kingres_shard.
CREATE FUNCTION kingres.timepart__dist_bounds(p_parent oid)
RETURNS TABLE (partition_name name, bound text)
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    IF pg_catalog.to_regclass('kingres.dist_partition') IS NULL THEN
        RETURN;
    END IF;
    RETURN QUERY EXECUTE
        'SELECT p.partition_name, p.bound FROM kingres.dist_partition p '
        'WHERE p.parent::pg_catalog.oid = $1'
        USING p_parent;
END;
$$;

-- timepart_part_name with the length limit as an argument: 63 bytes for a partition of an ordinary table, 57 for one
-- of a distributed table (its leaves append _bNNNN).
CREATE FUNCTION kingres.timepart__part_name(p_base name, p_every interval,
                                            p_tz text, p_start timestamptz,
                                            p_max integer)
RETURNS name
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_unit   text;
    v_n      integer;
    v_tail   text;
    v_base   text := p_base::text;
BEGIN
    SELECT u.unit, u.n INTO v_unit, v_n
      FROM kingres.timepart_interval_parts(p_every) u;
    v_tail := '_p' || CASE v_unit
        WHEN 'hour'  THEN to_char(p_start AT TIME ZONE 'UTC', 'YYYYMMDDHH24')
        WHEN 'day'   THEN to_char(p_start AT TIME ZONE p_tz, 'YYYYMMDD')
        WHEN 'week'  THEN to_char(p_start AT TIME ZONE p_tz, 'YYYYMMDD')
        WHEN 'month' THEN to_char(p_start AT TIME ZONE p_tz, 'YYYYMM')
        ELSE              to_char(p_start AT TIME ZONE p_tz, 'YYYY')
    END;
    WHILE octet_length(v_base) + octet_length(v_tail) > p_max LOOP
        v_base := left(v_base, char_length(v_base) - 1);
    END LOOP;
    RETURN (v_base || v_tail)::name;
END;
$$;

CREATE OR REPLACE FUNCTION kingres.timepart_part_name(p_base name, p_every interval,
                                           p_tz text, p_start timestamptz)
RETURNS name
LANGUAGE sql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
    SELECT kingres.timepart__part_name(p_base, p_every, p_tz, p_start, 63)
$$;

-- The storage of the partitions of a distributed table, read on the nodes that hold the leaves: per partition the
-- number of leaves, how many of them are columnar and the kind (heap, columnar, mixed, or other when a leaf is
-- missing or has another access method).  SECURITY DEFINER because asking the nodes is for superusers; the caller
-- must be a superuser or have the privileges of the owner of the table, as in timepart__special_table.
CREATE FUNCTION kingres.timepart__dist_kinds(p_parent oid)
RETURNS TABLE (partition_name name, kind text, leaves integer,
               columnar_leaves integer)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles r
                    WHERE r.rolname = session_user AND r.rolsuper)
       AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_class c
                        WHERE c.oid = p_parent
                          AND pg_catalog.pg_has_role(session_user, c.relowner, 'USAGE')) THEN
        RAISE EXCEPTION 'permission denied: only the owner of the table or a superuser may ask'
            USING ERRCODE = '42501';
    END IF;
    IF NOT (SELECT d.r_dist FROM kingres.timepart__dist(p_parent) d) THEN
        RAISE EXCEPTION 'relation with OID % is not a distributed table', p_parent
            USING ERRCODE = '42809';
    END IF;
    RETURN QUERY EXECUTE
        'SELECT s.partition_name::pg_catalog.name, '
        'CASE WHEN count(*) = count(*) FILTER (WHERE s.access_method = ''columnar'') THEN ''columnar'' '
        '     WHEN count(*) = count(*) FILTER (WHERE s.access_method = ''heap'') THEN ''heap'' '
        '     WHEN count(*) FILTER (WHERE s.access_method = ''columnar'') > 0 THEN ''mixed'' '
        '     ELSE ''other'' END, '
        'count(*)::pg_catalog.int4, '
        '(count(*) FILTER (WHERE s.access_method = ''columnar''))::pg_catalog.int4 '
        'FROM kingres.partition_leaf_storage($1::pg_catalog.oid::pg_catalog.regclass) s '
        'GROUP BY s.partition_name'
        USING p_parent;
END;
$$;

-- The partitions of a distributed table: the bounds, the number of leaves and their storage (heap, columnar, or
-- mixed while a conversion is half done).  The counterpart of timepart_partitions, whose partitions are tables.
CREATE FUNCTION kingres.timepart_dist_partitions(rel regclass)
RETURNS TABLE (partition_name name, range_from timestamptz,
               range_to timestamptz, access_method text, leaves integer,
               columnar_leaves integer)
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_info record;
BEGIN
    PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
    SELECT * INTO v_info FROM kingres.timepart__key_info(rel::oid);
    IF NOT (SELECT d.r_dist FROM kingres.timepart__dist(rel::oid) d) THEN
        RAISE EXCEPTION '%.% is not a distributed table; see timepart_partitions',
            quote_ident(v_info.r_schema), quote_ident(v_info.r_table)
            USING ERRCODE = '42809';
    END IF;
    IF NOT (pg_has_role(current_user, v_info.r_owner_oid, 'USAGE')
            OR has_table_privilege(current_user, rel::oid, 'SELECT')) THEN
        RAISE EXCEPTION 'permission denied for table %',
            format('%I.%I', v_info.r_schema, v_info.r_table)
            USING ERRCODE = '42501';
    END IF;
    RETURN QUERY
    SELECT c.part_name, c.lo, c.hi, k.kind, k.leaves, k.columnar_leaves
      FROM kingres.timepart__children(rel::oid) c
      LEFT JOIN kingres.timepart__dist_kinds(rel::oid) k
        ON k.partition_name = c.part_name
     WHERE NOT c.is_default
     ORDER BY c.lo;
END;
$$;

-- The leaves one policy needs in a steady state against kingres_shard.max_partition_leaves: the buckets times the
-- partitions of the retention (one year when there is none) and of the lookahead.  A refusal of the policy, with the
-- numbers; create_partition refuses the partition that would pass the limit all the same.
CREATE FUNCTION kingres.timepart__dist_budget(
    p_rel oid, p_every interval, p_ahead interval, p_retention interval)
RETURNS void
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_b     record;
    v_parts bigint;
BEGIN
    IF NOT (SELECT d.r_dist FROM kingres.timepart__dist(p_rel) d) THEN
        RETURN;
    END IF;
    EXECUTE 'SELECT b.buckets, b.max_leaves '
            'FROM kingres.partition_leaf_budget($1::pg_catalog.oid::pg_catalog.regclass) b'
        INTO v_b USING p_rel;
    v_parts := ceil(extract(epoch FROM coalesce(p_retention, interval '1 year') + p_ahead)
                    / extract(epoch FROM p_every))::bigint + 1;
    IF v_b.buckets::bigint * v_parts > v_b.max_leaves THEN
        RAISE EXCEPTION 'the policy needs about % leaves in a steady state (% buckets, % partitions); kingres_shard.max_partition_leaves is %',
            v_b.buckets::bigint * v_parts, v_b.buckets, v_parts, v_b.max_leaves
            USING ERRCODE = '54000',
                  HINT = 'Use a wider partition_every, a shorter retention or create_ahead, or raise kingres_shard.max_partition_leaves.';
    END IF;
END;
$$;

-- Convert the leaves of one partition of a distributed table, on the nodes that hold them (11.4).  The colocation
-- group is claimed first (kingres.begin_leaf_conversion, committed at once through a session of its own), so that no
-- bucket moves, no table operation copies the group and no partition is created or dropped meanwhile; then each
-- leaf that is not in the target storage yet is converted on its node by kingres.convert_leaf, in a session of its
-- own that commits; the claim is renewed after each leaf and released at the end, also when a leaf fails.  The leaves
-- converted before a failure stay converted (the partition is then mixed, and the next run goes on).  Returns what
-- was done.  A superuser, on the map group primary.
CREATE FUNCTION kingres.timepart__dist_convert(
    p_parent oid, p_partition name, p_target name, p_sort text[],
    p_options jsonb)
RETURNS text
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
DECLARE
    v_self    integer;
    v_op      bigint;
    v_leaves  jsonb;
    v_leaf    record;
    v_node    integer;
    v_bp      text;
    v_have    text;
    v_trust   boolean := kingres.timepart__trust_owners();
    v_ms      integer := kingres.timepart__setting_int(
                             'kingres_timepart.dist_leaf_timeout_ms', 14400000, 1000, 86400000);
    v_done    integer := 0;
    v_had     integer := 0;
    v_kind    text := kingres.timepart__am_kind(p_target);
    v_msg     text;
    v_state   text;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles r WHERE r.rolname = current_user AND r.rolsuper) THEN
        RAISE EXCEPTION 'permission denied: the leaves of a distributed table are converted by a superuser'
            USING ERRCODE = '42501';
    END IF;
    IF v_kind IS NULL OR v_kind = 'other' THEN
        RAISE EXCEPTION 'conversion_refused: "%" is not a supported table access method (use columnar or heap)', p_target
            USING ERRCODE = '0A000';
    END IF;
    IF v_kind <> 'heap' THEN
        PERFORM kingres.timepart__need_columnar();
    END IF;
    SELECT jsonb_agg(to_jsonb(s) ORDER BY s.node_id, s.bucket) INTO v_leaves
      FROM kingres.partition_leaf_storage(p_parent::regclass) s
     WHERE s.partition_name = p_partition::text;
    IF v_leaves IS NULL THEN
        RAISE EXCEPTION 'partition "%" of table "%" does not exist', p_partition, p_parent::regclass
            USING ERRCODE = '42704';
    END IF;
    -- every node that holds a leaf can convert it (kingres_timepart 0.3 and, for columnar, kingres_columnar)
    FOR v_node IN SELECT DISTINCT (x ->> 'node_id')::integer
                    FROM jsonb_array_elements(v_leaves) x ORDER BY 1
    LOOP
        v_have := kingres.internal_exec_scalar(v_node,
            'SELECT (pg_catalog.to_regprocedure(''kingres.convert_leaf(regclass,regclass,name,text[],jsonb,boolean)'') IS NOT NULL)::pg_catalog.text '
            '|| '','' || (EXISTS (SELECT 1 FROM pg_catalog.pg_extension e WHERE e.extname = ''kingres_columnar''))::pg_catalog.text',
            60000);
        IF v_have LIKE 'false,%' THEN
            RAISE EXCEPTION 'conversion_refused: node % does not have kingres_timepart 0.3 (kingres.convert_leaf) in this database', v_node
                USING ERRCODE = '0A000',
                      HINT = 'Install or update kingres_timepart on every node of the cluster.';
        END IF;
        IF v_kind = 'columnar' AND v_have LIKE '%,false' THEN
            RAISE EXCEPTION 'conversion_refused: node % does not have kingres_columnar in this database', v_node
                USING ERRCODE = '0A000',
                      HINT = 'Install kingres_columnar on every node of the cluster.';
        END IF;
    END LOOP;

    v_self := (SELECT l.node_id FROM kingres.local_node l);
    v_op := kingres.internal_exec_scalar(v_self,
        format('SELECT kingres.begin_leaf_conversion(%s::pg_catalog.oid::pg_catalog.regclass, %L, %L)',
               p_parent::oid, p_partition, p_target), 60000)::bigint;
    BEGIN
        FOR v_leaf IN
            SELECT x.partition_name, x.node_id, x.bucket, x.leaf, x.access_method
              FROM jsonb_to_recordset(v_leaves)
                   AS x(partition_name text, node_id integer, bucket integer,
                        leaf text, access_method text)
             ORDER BY x.node_id, x.bucket
        LOOP
            IF v_leaf.access_method IS NULL THEN
                RAISE EXCEPTION 'conversion_refused: the leaf % of bucket % is missing on node %',
                    v_leaf.leaf, v_leaf.bucket, v_leaf.node_id USING ERRCODE = '0A000';
            END IF;
            IF v_leaf.access_method = p_target::text THEN
                v_had := v_had + 1;
                CONTINUE;
            END IF;
            v_bp := format('%I.%I',
                           (SELECT n.nspname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
                             WHERE c.oid = p_parent),
                           (SELECT c.relname FROM pg_class c WHERE c.oid = p_parent)
                               || '_b' || lpad(v_leaf.bucket::text, 4, '0'));
            PERFORM kingres.internal_node_exec(v_leaf.node_id,
                format('CALL kingres.convert_leaf(%L::pg_catalog.regclass, %L::pg_catalog.regclass, %L, %L::pg_catalog.text[], %L::pg_catalog.jsonb, %L::pg_catalog.bool)',
                       v_bp, v_leaf.leaf, p_target, p_sort, p_options, v_trust),
                v_ms);
            v_done := v_done + 1;
            PERFORM kingres.internal_exec_scalar(v_self,
                format('SELECT kingres.renew_leaf_conversion(%s)::pg_catalog.text', v_op), 60000);
        END LOOP;
    EXCEPTION WHEN OTHERS OR query_canceled THEN
        v_msg := SQLERRM;
        v_state := SQLSTATE;
        BEGIN
            PERFORM kingres.internal_exec_scalar(v_self,
                format('SELECT kingres.end_leaf_conversion(%s, %L)::pg_catalog.text', v_op,
                       left('stopped: ' || v_msg, 200)), 60000);
        EXCEPTION WHEN OTHERS OR query_canceled THEN
            NULL;
        END;
        RAISE EXCEPTION '%', v_msg USING ERRCODE = v_state;
    END;
    PERFORM kingres.internal_exec_scalar(v_self,
        format('SELECT kingres.end_leaf_conversion(%s, %L)::pg_catalog.text', v_op,
               format('%s leaves converted to %s', v_done, p_target)), 60000);
    RETURN format('%s leaves converted to %s on %s nodes, %s already were',
                  v_done, p_target,
                  (SELECT count(DISTINCT (x ->> 'node_id')) FROM jsonb_array_elements(v_leaves) x), v_had);
END;
$$;

-- Convert one leaf of a distributed table on the node that holds it: the conversion of convert_partition (10.4), with
-- the bucket partition as the parent.  A superuser, called by timepart__dist_convert on every node that holds a leaf.
-- The swap is DDL on a bucket partition, which the hook of kingres_shard refuses for a user, so the transaction of the
-- swap runs with kingres_shard.enable_routing off (a setting of superusers); the new leaf of a columnar conversion has
-- REPLICA IDENTITY FULL, which the logical replication of a bucket move needs.  trust_owners is the setting
-- kingres_timepart.trust_table_owners of the session that asks.  Cannot run inside a transaction block.
CREATE PROCEDURE kingres.convert_leaf(
    parent regclass, leaf regclass,
    access_method name DEFAULT 'columnar', sort_by text[] DEFAULT NULL,
    options jsonb DEFAULT NULL, trust_owners boolean DEFAULT false)
LANGUAGE plpgsql
AS $$
DECLARE
    v_info    record;
    v_stmts   text[];
    v_self    oid;
    v_super   boolean;
    v_is      boolean;
    v_pschema name;
    v_pname   name;
BEGIN
    PERFORM pg_catalog.set_config('search_path', 'pg_catalog, pg_temp', true);
    -- Refuse a transaction block before anything is done.
    COMMIT;
    PERFORM pg_catalog.set_config('search_path', 'pg_catalog, pg_temp', true);
    IF parent IS NULL OR leaf IS NULL OR access_method IS NULL THEN
        RAISE EXCEPTION 'parent, leaf and access_method must not be null'
            USING ERRCODE = '22004';
    END IF;
    SELECT r.oid, r.rolsuper INTO v_self, v_super
      FROM pg_catalog.pg_roles r WHERE r.rolname OPERATOR(pg_catalog.=) current_user;
    IF NOT v_super THEN
        RAISE EXCEPTION 'permission denied: only a superuser may convert the leaves of a distributed table'
            USING ERRCODE = '42501';
    END IF;
    IF pg_catalog.to_regclass('kingres.dist_table') IS NULL THEN
        RAISE EXCEPTION '% is not a bucket partition of a distributed table', parent
            USING ERRCODE = '42809';
    END IF;
    EXECUTE 'SELECT EXISTS (SELECT 1 FROM pg_catalog.pg_inherits i '
            'JOIN kingres.dist_table d ON d.relid::pg_catalog.oid = i.inhparent '
            'WHERE i.inhrelid = $1::pg_catalog.oid)'
        INTO v_is USING parent;
    IF NOT v_is THEN
        RAISE EXCEPTION '% is not a bucket partition of a distributed table', parent
            USING ERRCODE = '42809';
    END IF;
    IF kingres.timepart__am_kind(access_method) IS DISTINCT FROM 'heap' THEN
        PERFORM kingres.timepart__need_columnar();
    END IF;
    PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
    SELECT * INTO v_info FROM kingres.timepart__key_info(parent::pg_catalog.oid);
    SELECT n.nspname, c.relname INTO v_pschema, v_pname
      FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid OPERATOR(pg_catalog.=) c.relnamespace
     WHERE c.oid OPERATOR(pg_catalog.=) leaf::pg_catalog.oid;
    v_stmts := kingres.timepart__convert_stmts(
        parent::pg_catalog.oid, leaf::pg_catalog.oid, access_method, sort_by, options, true);
    IF trust_owners THEN
        PERFORM pg_catalog.set_config('kingres_timepart.trust_table_owners', 'on', true);
    END IF;
    PERFORM pg_catalog.set_config('kingres_shard.enable_routing', 'off', true);
    IF v_self OPERATOR(pg_catalog.=) v_info.r_owner_oid AND session_user OPERATOR(pg_catalog.=) current_user THEN
        PERFORM kingres.timepart__exec_direct(v_stmts);
    ELSE
        PERFORM kingres.timepart__exec_as(v_info.r_owner_oid, v_stmts);
    END IF;
    COMMIT;
    PERFORM pg_catalog.set_config('search_path', 'pg_catalog, pg_temp', true);
    PERFORM pg_catalog.set_config('lock_timeout', kingres.timepart__lock_timeout('create'), true);
    BEGIN
        EXECUTE pg_catalog.format('ANALYZE %I.%I', v_pschema, v_pname);
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'ANALYZE of %.% was not done: %',
            pg_catalog.quote_ident(v_pschema), pg_catalog.quote_ident(v_pname), SQLERRM;
    END;
END;
$$;

-- convert_partition for a partition of a distributed table, for use by hand: every leaf that is not in the target
-- storage yet, on its node (see timepart__dist_convert).  A superuser, on the map group primary; returns what was done.
CREATE FUNCTION kingres.convert_distributed_partition(
    parent regclass, partition_name name,
    access_method name DEFAULT 'columnar', sort_by text[] DEFAULT NULL,
    options jsonb DEFAULT NULL)
RETURNS text
LANGUAGE plpgsql
SET search_path = pg_catalog, kingres, pg_temp
AS $$
BEGIN
    IF NOT (SELECT d.r_dist FROM kingres.timepart__dist(parent::oid) d) THEN
        RAISE EXCEPTION '% is not a distributed table', parent
            USING ERRCODE = '42809';
    END IF;
    RETURN kingres.timepart__dist_convert(parent::oid, partition_name,
                                          access_method, sort_by, options);
END;
$$;

------------------------------------------------------------------------
-- Privileges and comments
------------------------------------------------------------------------

REVOKE ALL ON FUNCTION
    kingres.timepart__dist_kinds(oid),
    kingres.timepart__dist_convert(oid, name, name, text[], jsonb),
    kingres.timepart_dist_partitions(regclass),
    kingres.convert_distributed_partition(regclass, name, name, text[], jsonb)
    FROM PUBLIC;
REVOKE ALL ON PROCEDURE
    kingres.convert_leaf(regclass, regclass, name, text[], jsonb, boolean)
    FROM PUBLIC;

COMMENT ON FUNCTION kingres.timepart_dist_partitions(regclass) IS
    'The partitions of a distributed table with bounds, number of leaves and storage (heap, columnar or mixed)';
COMMENT ON PROCEDURE kingres.convert_leaf(regclass, regclass, name, text[], jsonb, boolean) IS
    'Convert one leaf of a distributed table on the node that holds it (a superuser; called for every leaf of a partition by the policy); cannot run inside a transaction block';
